INSERT INTO lp_resources (slug, kind, perspective, audience, urgency, evidence_level, emoji, title, summary, body, sections, reading_minutes, min_day, max_day, countries, sex, tags, is_featured, review_status, sort_order) VALUES
  ('ec-why-tantrums-happen', 'article', 'scientific', 'shared', 'important', 'consensus', '🌪️', '{"en":"Why tantrums happen: inside the toddler brain","bn":"শিশু কেন রেগে কান্নাকাটি করে: ছোট মস্তিষ্কের ভেতরের কথা"}'::jsonb, '{"en":"Tantrums are a normal part of being two to four. The feeling part of the brain is strong, while the part that calms feelings is still growing. Your calm presence is what helps.","bn":"দুই থেকে চার বছর বয়সে রেগে কান্নাকাটি (tantrum) খুব স্বাভাবিক। এই বয়সে আবেগ খুব জোরালো, কিন্তু আবেগ সামলানোর ক্ষমতা এখনো তৈরি হচ্ছে। আপনার শান্ত উপস্থিতিই শিশুকে সাহায্য করে।"}'::jsonb, '{"en":"A minute ago your child was happy. Now they are on the floor screaming because the biscuit broke in half. It can feel embarrassing or even frightening. But tantrums are a normal part of growing up, and for most children they become less frequent by around four or five, as language and self-control grow.\n\n## What is happening inside\n\nA young child''s brain is still building the parts that calm big feelings and make plans. The feeling part works at full strength from early on; the ''brake'' at the front of the brain keeps developing for many years. So when a two-year-old is frustrated, tired or disappointed, the feeling arrives fast and the brake is weak.\n\nToddlers also want to do things by themselves, but often cannot yet. They have more wishes than words. When they cannot explain what they want, the feeling comes out through the body: crying, kicking, throwing, lying down.\n\n## Common triggers\n\n- Hunger, tiredness or feeling unwell\n- Too much noise, too many people, a long day out\n- Changes, such as stopping play to go home\n- Hearing ''no'', or not being understood\n- Big changes at home, such as a new baby or a move\n\n## What helps in the moment\n\n1. Stay close and stay calm. Your child borrows your calm. Breathe slowly yourself.\n2. Keep everyone safe. Move breakable things, or gently move your child to a safer spot.\n3. Use few words: ''You are very angry. I am here.'' Long explanations do not reach a child in the middle of a storm.\n4. If it was a real limit, kindly hold it. Giving in teaches that screaming works.\n5. When the storm passes, offer a hug and some water, and move on. No lecture is needed.\n\n## What helps beforehand\n\n- Keep meals, naps and bedtime regular.\n- Warn before changes: ''Two more turns on the swing, then we go home.''\n- Offer small choices so your child feels some control.\n- Notice calm moments: ''You waited so nicely for your turn.''\n\n## Not a sign of bad parenting\n\nTantrums do not mean your child is spoiled or that you have failed. Almost every child has them. Hitting, shouting back or shaming tends to make them happen more, not less. What builds self-control over time is a calm adult who stays nearby and holds kind, clear limits.\n\n## When to talk to a health worker\n\nTalk to a doctor or health worker if tantrums happen many times every day or last a very long time, if your child often hurts themselves or others during them, if they are still very frequent after age five, or if you are also worried about your child''s speech, hearing or development. It is also fine to ask for help if you feel you are losing your temper often — that is a sign of a tired parent, not a bad one.","bn":"এক মিনিট আগেও শিশু হাসিখুশি ছিল। এখন মেঝেতে গড়াগড়ি দিয়ে চিৎকার করছে — কারণ বিস্কুটটা দুই টুকরো হয়ে গেছে। এমন সময় লজ্জা লাগতে পারে, ভয়ও লাগতে পারে। কিন্তু রেগে কান্নাকাটি (tantrum) বড় হওয়ারই স্বাভাবিক অংশ। ভাষা আর নিজেকে সামলানোর ক্ষমতা বাড়ার সাথে সাথে বেশিরভাগ শিশুর ক্ষেত্রে চার-পাঁচ বছরের দিকে এটা অনেক কমে আসে।\n\n## ভেতরে কী ঘটছে\n\nছোট শিশুর মস্তিষ্কে আবেগ শান্ত করার আর পরিকল্পনা করার অংশটা এখনো তৈরি হচ্ছে। আবেগের অংশটা ছোটবেলা থেকেই পুরো শক্তিতে কাজ করে, কিন্তু কপালের পেছনের ‘ব্রেক’ অংশটা গড়ে উঠতে অনেক বছর লাগে। তাই দুই বছরের শিশু যখন হতাশ, ক্লান্ত বা মন খারাপ করে, আবেগ আসে ঝড়ের মতো — আর ব্রেক থাকে দুর্বল।\n\nএই বয়সে শিশু সব কাজ নিজে করতে চায়, কিন্তু সবসময় পারে না। মনে চাওয়া অনেক, মুখে শব্দ কম। যা চায় তা বোঝাতে না পারলে আবেগটা শরীর দিয়ে বের হয় — কান্না, লাথি, জিনিস ছোড়া, মেঝেতে শুয়ে পড়া।\n\n## সাধারণত কখন হয়\n\n- ক্ষুধা, ঘুম পাওয়া বা শরীর খারাপ লাগা\n- বেশি শব্দ, বেশি মানুষ, সারাদিন বাইরে ঘোরা\n- হঠাৎ পরিবর্তন, যেমন খেলা থামিয়ে বাসায় ফেরা\n- ‘না’ শোনা, বা কেউ তার কথা না বোঝা\n- বাসায় বড় পরিবর্তন — নতুন ভাই-বোন, নতুন বাসা\n\n## ঝড়ের মুহূর্তে যা কাজে দেয়\n\n১. কাছে থাকুন, শান্ত থাকুন। শিশু আপনার শান্ত ভাবটা ধার করে নেয়। নিজে ধীরে শ্বাস নিন।\n২. সবাইকে নিরাপদ রাখুন। ভাঙার মতো জিনিস সরিয়ে দিন, বা শিশুকে আলতো করে নিরাপদ জায়গায় নিন।\n৩. কম কথা বলুন: “তুমি খুব রেগে গেছ। আমি আছি।” ঝড়ের মাঝে লম্বা বোঝানো শিশুর কানে পৌঁছায় না।\n৪. সীমাটা সত্যিই জরুরি হলে নরমভাবে সেটা ধরে রাখুন। হার মানলে শিশু শেখে, চিৎকার করলেই পাওয়া যায়।\n৫. ঝড় থামলে জড়িয়ে ধরুন, একটু পানি দিন, তারপর স্বাভাবিক কাজে ফিরুন। বকাঝকা বা উপদেশের দরকার নেই।\n\n## আগে থেকে যা সাহায্য করে\n\n- খাওয়া, দুপুরের ঘুম আর রাতের ঘুমের সময় নিয়মিত রাখুন।\n- পরিবর্তনের আগে জানিয়ে দিন: “আর দুইবার দোলনায় চড়বে, তারপর বাসায় যাব।”\n- ছোট ছোট পছন্দ দিন, যাতে শিশু মনে করে তারও কিছু বলার আছে।\n- শান্ত মুহূর্তগুলো খেয়াল করে বলুন: “তুমি কী সুন্দর করে তোমার পালার জন্য অপেক্ষা করলে!”\n\n## এটা খারাপ লালনপালনের লক্ষণ নয়\n\nরেগে কান্নাকাটি মানে শিশু ‘আদরে বাঁদর’ হয়ে গেছে বা আপনি ব্যর্থ — এমন নয়। প্রায় সব শিশুই এমন করে। মারধর, পাল্টা চিৎকার বা লজ্জা দিলে এটা বরং বাড়ে। সময়ের সাথে নিজেকে সামলাতে শেখায় একজন শান্ত বড় মানুষ, যিনি পাশে থাকেন আর নরম কিন্তু স্পষ্ট সীমা রাখেন।\n\n## কখন স্বাস্থ্যকর্মীর সাথে কথা বলবেন\n\nপ্রতিদিন অনেকবার বা খুব লম্বা সময় ধরে এমন হলে, রাগের সময় শিশু প্রায়ই নিজেকে বা অন্যকে আঘাত করলে, পাঁচ বছরের পরেও খুব ঘনঘন হলে, অথবা শিশুর কথা, শোনা বা বিকাশ নিয়েও চিন্তা থাকলে ডাক্তার বা স্বাস্থ্যকর্মীর সাথে কথা বলুন। আপনি নিজে প্রায়ই মেজাজ হারিয়ে ফেলছেন মনে হলেও সাহায্য চাইতে পারেন — এটা ক্লান্ত বাবা-মায়ের লক্ষণ, খারাপ বাবা-মায়ের নয়।"}'::jsonb, '{}'::jsonb, 4, 730, 1461, '{}'::text[], 'any', ARRAY['tantrum', 'anger', 'toddler brain', 'meltdown', 'crying', 'behaviour']::text[], false, 'in_review'::lp_review_status, 5001),
  ('ec-naming-feelings', 'article', 'scientific', 'shared', 'educational', 'consensus', '🎭', '{"en":"Naming feelings: giving your child words for what they feel","bn":"অনুভূতির নাম দেওয়া: মনের কথা বলার শব্দ শেখানো"}'::jsonb, '{"en":"When you put a name to your child''s feeling, they feel understood and calm down faster. Over time they learn to say ''I am angry'' instead of hitting.","bn":"শিশুর অনুভূতিকে একটা নাম দিলে সে বোঝে, কেউ তাকে বুঝেছে — তাই তাড়াতাড়ি শান্ত হয়। ধীরে ধীরে সে মারার বদলে বলতে শেখে, “আমার রাগ লাগছে।”"}'::jsonb, '{"en":"Before children can control a feeling, they need a word for it. When you name what your child feels, you help their brain sort the feeling out, and you show them that feelings are safe to talk about.\n\n## Why it works\n\nA two-year-old feels anger, fear, sadness and jealousy as strongly as an adult, but has few words for them. Saying ''You are sad because Abbu went to the office'' helps the child feel understood, and a child who feels understood calms down sooner. Children who know feeling words are better able, over time, to say ''I am angry'' instead of hitting or biting.\n\n## How to do it\n\n1. Notice first. Look at the face and body: tight fists, a wobbly lip, hiding behind your legs.\n2. Name it simply: ''You look angry.'' ''That was scary.'' ''You are disappointed that the rain stopped your game.''\n3. Say why, if you can: ''You wanted the blue cup.''\n4. Accept the feeling, guide the action: ''It is okay to be angry. It is not okay to hit. You can stamp your feet or squeeze this pillow.''\n5. Offer comfort or a next step: ''Shall we look for the blue cup after lunch?''\n\n## Grow the feeling words\n\nStart with four: happy, sad, angry, scared. Add more as your child grows: tired, worried, excited, proud, lonely, frustrated, jealous. Use the languages your family speaks at home.\n\n- Talk about feelings in picture books: ''How does the little bird feel now?''\n- Name your own feelings calmly: ''I feel tired today, so I am going to sit for a while.''\n- Make faces in the mirror together: happy, surprised, sleepy.\n- At bedtime, ask: ''What made you happy today? Was anything sad?''\n\n## What to avoid\n\n- ''Don''t cry, boys don''t cry.'' Every child, boy or girl, needs to cry sometimes.\n- ''There is nothing to be scared of.'' To your child, the fear is real.\n- Laughing at a feeling, or talking about it to others in front of the child.\n- Distracting every single time. Distraction can help, but feelings also need to be heard.\n\n## Fathers and grandparents too\n\nChildren learn most by watching. When a father says ''I was angry, so I took a deep breath'', or a grandmother says ''I missed you today'', the child learns that feelings are a normal part of every family. Naming feelings does not spoil a child; it gives them a tool they will use all their life.","bn":"শিশু কোনো অনুভূতি সামলাতে শেখার আগে তার একটা নাম জানা দরকার। আপনি যখন শিশুর মনের অবস্থাকে নাম দেন, তখন তার মস্তিষ্ক অনুভূতিটা গুছিয়ে নিতে পারে, আর সে শেখে — মনের কথা বলা যায়, এতে ভয়ের কিছু নেই।\n\n## কেন কাজ করে\n\nদুই বছরের শিশুরও রাগ, ভয়, দুঃখ, হিংসা বড়দের মতোই তীব্র — কিন্তু বোঝানোর শব্দ তার কাছে খুব কম। “আব্বু অফিসে চলে গেছে, তাই তোমার মন খারাপ” — এভাবে বললে শিশু টের পায়, কেউ তাকে বুঝেছে। আর বোঝা পেলে সে তাড়াতাড়ি শান্ত হয়। যে শিশু অনুভূতির শব্দ জানে, সময়ের সাথে সে মারা বা কামড়ানোর বদলে বলতে পারে, “আমার রাগ লাগছে।”\n\n## কীভাবে করবেন\n\n১. আগে খেয়াল করুন। মুখ আর শরীর দেখুন — মুঠি শক্ত, ঠোঁট কাঁপছে, নাকি আপনার পায়ের পেছনে লুকাচ্ছে।\n২. সহজ করে নাম দিন: “তোমার রাগ লাগছে মনে হয়।” “খুব ভয় পেয়েছিলে, তাই না?” “বৃষ্টিতে খেলা বন্ধ হয়ে গেল, তাই মন খারাপ।”\n৩. পারলে কারণটাও বলুন: “তুমি নীল কাপটা চাইছিলে।”\n৪. অনুভূতি মেনে নিন, কাজটা ঠিক করে দিন: “রাগ হতেই পারে। কিন্তু মারা যাবে না। চাইলে পা দিয়ে মাটিতে ধপধপ করো, বা এই বালিশটা চেপে ধরো।”\n৫. সান্ত্বনা দিন বা পরের ধাপ দেখান: “দুপুরে খাওয়ার পর আমরা নীল কাপটা খুঁজব, ঠিক আছে?”\n\n## অনুভূতির শব্দভান্ডার বাড়ান\n\nশুরু করুন চারটি দিয়ে: খুশি, দুঃখ, রাগ, ভয়। বয়স বাড়লে যোগ করুন: ক্লান্ত, দুশ্চিন্তা, উত্তেজনা, গর্ব, একা লাগা, বিরক্তি, হিংসা। বাসায় যে ভাষায় কথা বলেন, সেই ভাষাতেই শেখান।\n\n- ছবির বই পড়ার সময় জিজ্ঞেস করুন: “ছোট পাখিটার এখন কেমন লাগছে?”\n- নিজের অনুভূতি শান্তভাবে বলুন: “আজ আমার খুব ক্লান্ত লাগছে, তাই একটু বসব।”\n- আয়নার সামনে একসাথে মুখ বানান — খুশির মুখ, অবাক মুখ, ঘুমঘুম মুখ।\n- ঘুমানোর আগে জিজ্ঞেস করুন: “আজ কী দেখে খুশি হয়েছিলে? মন খারাপের কিছু হয়েছিল?”\n\n## যা এড়িয়ে চলবেন\n\n- “ছেলেরা কাঁদে না।” ছেলে হোক বা মেয়ে, প্রতিটি শিশুর মাঝে মাঝে কাঁদার দরকার হয়।\n- “এতে ভয়ের কী আছে!” শিশুর কাছে ভয়টা সত্যি।\n- অনুভূতি নিয়ে হাসাহাসি করা, বা শিশুর সামনেই অন্যদের কাছে বলে বেড়ানো।\n- প্রতিবার শুধু মন ঘুরিয়ে দেওয়া। মাঝে মাঝে সেটা কাজে দেয়, কিন্তু অনুভূতিকে শোনারও দরকার আছে।\n\n## বাবা আর দাদা-দাদি, নানা-নানিরাও\n\nশিশু সবচেয়ে বেশি শেখে দেখে দেখে। বাবা যখন বলেন, “আমার রাগ হয়েছিল, তাই একটা লম্বা শ্বাস নিলাম,” বা নানু বলেন, “আজ তোমাকে খুব মনে পড়ছিল,” শিশু বোঝে — অনুভূতি প্রতিটি পরিবারের স্বাভাবিক অংশ। অনুভূতির নাম শেখালে শিশু নষ্ট হয় না; বরং সে সারাজীবন কাজে লাগার মতো একটা হাতিয়ার পায়।"}'::jsonb, '{}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['feelings', 'emotions', 'emotion words', 'empathy', 'self-control']::text[], false, 'in_review'::lp_review_status, 5002),
  ('ec-positive-discipline', 'article', 'scientific', 'shared', 'important', 'guideline', '🤝', '{"en":"Positive discipline: guiding without hitting or shouting","bn":"ইতিবাচক শাসন: মারধর বা চিৎকার ছাড়াই পথ দেখানো"}'::jsonb, '{"en":"Discipline means teaching, not hurting. Routines, simple choices, time-in and calm consequences work better than hitting or shouting, which harm children and do not improve behaviour.","bn":"শাসন মানে শেখানো, কষ্ট দেওয়া নয়। নিয়মিত রুটিন, ছোট পছন্দ, পাশে থেকে শান্ত করা আর শান্ত পরিণতি — এগুলো মারধর বা চিৎকারের চেয়ে ভালো কাজ করে। মারধর শিশুর ক্ষতি করে, আচরণও ভালো করে না।"}'::jsonb, '{"en":"Many of us were raised with a slap or a cane, and we turned out fine — or so it feels. It is natural to reach for what we know, especially when we are tired. But research summarised by the World Health Organization is clear: physical punishment does not improve behaviour over time. It is linked with more aggression, more anxiety and a weaker bond between parent and child. Shouting and frightening threats have similar effects. The good news is that there are ways that work better.\n\n## Discipline means teaching\n\nThe aim is not to make a child afraid, but to help them learn what to do instead. A two- to four-year-old learns by repetition, by watching you and by feeling safe with you.\n\n## Tools that work\n\n- **Routines.** The same order every day (wake, wash, eat, play, nap) means fewer battles. Children cooperate more when they know what comes next.\n- **Clear, short instructions.** Say what to do, not only what not to do: ''Walk next to me'', rather than ''Don''t run''. Get down to their eye level first.\n- **Two good choices.** ''Do you want to wear the red shirt or the yellow one?'' Both choices are fine with you, and your child feels some control.\n- **Praise the behaviour you want.** ''You put your shoes by the door. Thank you!'' Be specific and honest.\n- **Time-in.** When your child is overwhelmed, stay close instead of sending them away. Sit together, name the feeling, breathe, and talk once they are calm.\n- **Calm, linked consequences.** If the crayons go on the wall, the crayons are put away for now, and the child helps wipe the wall. Keep it short, related to what happened, and said without anger.\n- **Ignore small attention-seeking things** like whining, while giving lots of attention to good moments.\n- **Make the home easy.** Put breakable or dangerous things away so you need to say ''no'' less.\n\n## When you lose your temper\n\nEvery parent shouts sometimes. When it happens, calm down first, then repair: ''I shouted. I''m sorry. I was tired. Let''s try again.'' This teaches your child how to make things right — a lesson worth more than a perfect parent.\n\n## The whole family\n\nDiscipline works best when parents, grandparents and other carers agree on a few simple rules. Fathers can take a full share: holding limits calmly, praising, and doing the bedtime routine. If you feel you are often close to hitting, step away for a minute if your child is safe, and talk to someone you trust or a health worker. Asking for help is a strong thing to do.\n\n## What to avoid\n\n- Hitting, slapping, pinching, ear-pulling or using a stick\n- Shouting, name-calling, or saying ''I don''t love you''\n- Frightening threats: ''The police will take you'', ''I''ll leave you here''\n- Locking a child in a room or tying them up\n- Withholding food as punishment","bn":"আমাদের অনেকেই ছোটবেলায় চড়-থাপ্পড় বা বেত খেয়ে বড় হয়েছি — মনে হয়, ঠিকই তো আছি। ক্লান্ত থাকলে চেনা পথে হাত চলে যাওয়াটা স্বাভাবিক। কিন্তু বিশ্ব স্বাস্থ্য সংস্থার (WHO) সারসংক্ষেপ করা গবেষণা স্পষ্ট বলছে: শারীরিক শাস্তিতে সময়ের সাথে আচরণ ভালো হয় না। বরং এর সাথে আক্রমণাত্মক আচরণ, দুশ্চিন্তা আর বাবা-মায়ের সাথে দূরত্ব বাড়ার সম্পর্ক আছে। চিৎকার আর ভয় দেখানোর ফলও প্রায় একই রকম। ভালো খবর হলো, এর চেয়ে ভালো কাজ করে এমন উপায় আছে।\n\n## শাসন মানে শেখানো\n\nলক্ষ্য শিশুকে ভয় পাওয়ানো নয়, বরং কী করা উচিত সেটা শেখানো। দুই থেকে চার বছরের শিশু শেখে বারবার করে, আপনাকে দেখে, আর আপনার কাছে নিরাপদ বোধ করে।\n\n## যে উপায়গুলো কাজ করে\n\n- **নিয়মিত রুটিন।** প্রতিদিন একই ক্রমে ঘুম থেকে ওঠা, হাতমুখ ধোয়া, খাওয়া, খেলা, ঘুম — এতে ঝগড়া কমে। কী হবে জানা থাকলে শিশু বেশি সহযোগিতা করে।\n- **ছোট ও পরিষ্কার নির্দেশ।** শুধু “এটা কোরো না” না বলে বলুন কী করতে হবে: “দৌড়িও না” না বলে “আমার পাশে পাশে হাঁটো।” বলার আগে বসে শিশুর চোখের সমান হোন।\n- **দুটি ভালো পছন্দ।** “লাল জামা পরবে, না হলুদটা?” দুটোই আপনার কাছে ঠিক, আর শিশু মনে করে তারও মত আছে।\n- **ভালো আচরণের প্রশংসা।** “তুমি জুতা দরজার পাশে রেখেছ — ধন্যবাদ!” নির্দিষ্ট করে, সত্যি করে বলুন।\n- **পাশে থেকে শান্ত করা (time-in)।** শিশু আবেগে ভেসে গেলে দূরে না পাঠিয়ে কাছে থাকুন। একসাথে বসুন, অনুভূতির নাম দিন, শ্বাস নিন — শান্ত হলে তারপর কথা বলুন।\n- **শান্ত ও সম্পর্কিত পরিণতি।** দেয়ালে রং পেনসিল দিয়ে আঁকলে আপাতত রং পেনসিল তুলে রাখা হবে, আর শিশু দেয়াল মুছতে সাহায্য করবে। ছোট করে, ঘটনার সাথে মিলিয়ে, রাগ ছাড়া বলুন।\n- **ছোটখাটো মনোযোগ চাওয়া আচরণ এড়িয়ে যান,** যেমন ঘ্যানঘ্যান — আর ভালো মুহূর্তে অনেক মনোযোগ দিন।\n- **ঘরটা সহজ করুন।** ভাঙার মতো বা বিপজ্জনক জিনিস সরিয়ে রাখুন, যাতে বারবার ‘না’ বলতে না হয়।\n\n## যখন মেজাজ হারিয়ে ফেলেন\n\nসব বাবা-মা-ই মাঝে মাঝে চিৎকার করে ফেলেন। এমন হলে আগে নিজে শান্ত হোন, তারপর সম্পর্ক জোড়া লাগান: “আমি চিৎকার করেছি, দুঃখিত। আমি খুব ক্লান্ত ছিলাম। চলো আবার চেষ্টা করি।” এতে শিশু শেখে ভুল হলে কীভাবে ঠিক করতে হয় — যা একজন ‘নিখুঁত’ বাবা-মায়ের চেয়েও বড় শিক্ষা।\n\n## পুরো পরিবার মিলে\n\nবাবা-মা, দাদা-দাদি, নানা-নানি আর অন্য যারা দেখাশোনা করেন, সবাই কয়েকটা সহজ নিয়মে একমত হলে শাসন সবচেয়ে ভালো কাজ করে। বাবাও পুরো ভাগ নিতে পারেন — শান্তভাবে সীমা ধরে রাখা, প্রশংসা করা, ঘুমের রুটিন করানো। যদি মনে হয় প্রায়ই মেরে ফেলার কাছাকাছি চলে যাচ্ছেন, শিশু নিরাপদ থাকলে এক মিনিটের জন্য সরে যান, আর বিশ্বস্ত কারও বা স্বাস্থ্যকর্মীর সাথে কথা বলুন। সাহায্য চাওয়া শক্তির পরিচয়।\n\n## যা করবেন না\n\n- মারা, চড় দেওয়া, চিমটি কাটা, কান মলা বা লাঠি ব্যবহার\n- চিৎকার, গালি দেওয়া, বা “তোমাকে আর ভালোবাসি না” বলা\n- ভয় দেখানো: “পুলিশে ধরিয়ে দেব”, “তোমাকে এখানে রেখে চলে যাব”\n- ঘরে আটকে রাখা বা বেঁধে রাখা\n- শাস্তি হিসেবে খাবার না দেওয়া"}'::jsonb, '{}'::jsonb, 5, 730, 1461, '{}'::text[], 'any', ARRAY['discipline', 'no hitting', 'shouting', 'routines', 'choices', 'time-in', 'consequences', 'behaviour']::text[], false, 'in_review'::lp_review_status, 5003),
  ('ec-toilet-training', 'article', 'scientific', 'shared', 'routine', 'consensus', '🚽', '{"en":"Toilet training, step by step","bn":"টয়লেট ব্যবহার শেখানো: ধাপে ধাপে"}'::jsonb, '{"en":"Most children are ready to start between about two and three years. Wait for the signs, keep it relaxed, and never punish accidents.","bn":"বেশিরভাগ শিশু মোটামুটি দুই থেকে তিন বছরের মধ্যে টয়লেট শেখার জন্য তৈরি হয়। লক্ষণ দেখে শুরু করুন, চাপ দেবেন না, আর দুর্ঘটনায় কখনো শাস্তি দেবেন না।"}'::jsonb, '{"en":"Learning to use the toilet is a big step, and every child gets there in their own time. Many children are ready to start somewhere between two and three years; some are earlier, some later. Starting when your child is ready usually makes it quicker and calmer for everyone.\n\n## Signs your child may be ready\n\n- Stays dry for an hour or two at a time, or wakes from a nap dry\n- Knows when they are weeing or pooing, and may tell you, hide or go quiet\n- Is bothered by a wet or dirty nappy\n- Can walk to the toilet, sit, and pull simple trousers down and up\n- Can follow simple instructions and is interested when others use the toilet\n\n## Getting ready\n\nChoose a calm time, not the week a new baby arrives or you move house. Get a small potty, or a child seat and a stool for the family toilet, so your child''s feet are supported. If your home has a squat toilet, practise with a potty first and hold your child steadily later. Let your child watch a parent of the same sex, or an older sibling, and use simple words your family is comfortable with.\n\n## Step by step\n\n1. Put the potty where your child plays, and let them sit on it with clothes on at first.\n2. Then try sitting without a nappy for a few minutes after waking, after meals and before bath. Do not force them to sit for long.\n3. Use loose clothes or no trousers at home, so getting ready is quick.\n4. Watch for signals and say, ''Let''s go to the potty.''\n5. When something lands in the potty, praise calmly: ''You did it!'' A big show is not needed.\n6. Teach wiping (girls from front to back) and handwashing with soap every time.\n7. Move to pants in the day once there are more successes than accidents. Night dryness usually comes later; keep a nappy at night for as long as needed.\n\n## Accidents are part of learning\n\nAccidents will happen, often for weeks. Clean up without fuss: ''Oops, the wee came out. Next time we''ll try the potty.'' Shaming, smacking or making a child sit for a long time makes children hold on, which leads to constipation and more accidents.\n\n## Constipation can block progress\n\nHard, painful poos make children afraid to go. Offer plenty of water, fruit, vegetables, dal and whole grains, and keep your child active. If poos stay hard or painful, see a health worker.\n\n## Different paces are normal\n\nBoys and girls, first children and later ones, all learn at different speeds. Children with developmental differences can learn too, often with more time and a clear routine. Daytime dryness usually comes before night dryness, and some wetting at night is common for several more years.\n\n## When to see a health worker\n\nSee a doctor or health worker if there is pain or burning when weeing, blood in wee or poo, a fever, very hard poos, or if a child who was dry for months starts wetting again often. Also ask if your child is well past three and shows no signs of readiness at all.","bn":"টয়লেট ব্যবহার শেখা শিশুর জন্য বড় একটা ধাপ, আর প্রতিটি শিশু নিজের সময়ে এখানে পৌঁছায়। অনেক শিশু দুই থেকে তিন বছরের মধ্যে শুরু করার মতো তৈরি হয় — কেউ একটু আগে, কেউ একটু পরে। শিশু তৈরি হলে শুরু করলে সাধারণত দ্রুত হয়, আর সবার জন্য ঝামেলাও কম হয়।\n\n## শিশু তৈরি কি না বোঝার লক্ষণ\n\n- এক-দুই ঘণ্টা শুকনো থাকে, বা দুপুরের ঘুম থেকে শুকনো উঠে\n- প্রস্রাব-পায়খানা হচ্ছে টের পায় — বলে দেয়, আড়ালে যায় বা চুপ হয়ে যায়\n- ভেজা বা নোংরা ডায়াপারে অস্বস্তি দেখায়\n- টয়লেট পর্যন্ত হেঁটে যেতে, বসতে আর ঢিলা প্যান্ট নামাতে-ওঠাতে পারে\n- সহজ নির্দেশ মানতে পারে, অন্যদের টয়লেটে যাওয়া নিয়ে আগ্রহ দেখায়\n\n## প্রস্তুতি\n\nশান্ত একটা সময় বেছে নিন — নতুন ভাই-বোন আসার সপ্তাহে বা বাসা বদলের সময়ে নয়। একটা ছোট পটি কিনুন, অথবা বড় টয়লেটের জন্য শিশুদের সিট আর পা রাখার একটা টুল, যাতে পা ঝুলে না থাকে। বাসায় প্যান (squat) টয়লেট হলে প্রথমে পটিতে অভ্যাস করান, পরে প্যানে বসার সময় শক্ত করে ধরে রাখুন। শিশুকে একই লিঙ্গের বাবা বা মা, বা বড় ভাই-বোনকে দেখতে দিন, আর পরিবারে স্বাভাবিক এমন সহজ শব্দ ব্যবহার করুন।\n\n## ধাপে ধাপে\n\n১. পটিটা শিশুর খেলার জায়গায় রাখুন। প্রথমে জামাকাপড় পরেই বসতে দিন।\n২. তারপর ঘুম থেকে উঠে, খাওয়ার পরে আর গোসলের আগে ডায়াপার খুলে কয়েক মিনিট বসান। জোর করে অনেকক্ষণ বসিয়ে রাখবেন না।\n৩. বাসায় ঢিলা জামা বা প্যান্ট ছাড়া রাখুন, যাতে তাড়াতাড়ি বসা যায়।\n৪. লক্ষণ দেখলেই বলুন, “চলো, পটিতে যাই।”\n৫. পটিতে কিছু হলে শান্তভাবে প্রশংসা করুন: “তুমি পেরেছ!” বড় অনুষ্ঠান করার দরকার নেই।\n৬. মোছা শেখান (মেয়েদের সামনে থেকে পেছনের দিকে), আর প্রতিবার সাবান দিয়ে হাত ধোয়া।\n৭. দিনের বেলায় দুর্ঘটনার চেয়ে সফলতা বেশি হলে প্যান্ট পরানো শুরু করুন। রাতে শুকনো থাকা সাধারণত পরে আসে; যতদিন দরকার রাতে ডায়াপার রাখুন।\n\n## দুর্ঘটনা শেখারই অংশ\n\nকাপড় ভিজবে — কয়েক সপ্তাহ ধরেও। ঝামেলা না করে পরিষ্কার করুন: “ওহ, প্রস্রাব বের হয়ে গেছে। পরের বার পটিতে চেষ্টা করব।” লজ্জা দেওয়া, মারা বা অনেকক্ষণ বসিয়ে রাখলে শিশু চেপে রাখতে শেখে — এতে কোষ্ঠকাঠিন্য হয়, দুর্ঘটনাও বাড়ে।\n\n## কোষ্ঠকাঠিন্য আটকে দিতে পারে\n\nশক্ত, ব্যথাভরা পায়খানা হলে শিশু টয়লেটে যেতে ভয় পায়। যথেষ্ট পানি, ফল, শাকসবজি, ডাল আর লাল আটা বা লাল চালের মতো গোটা শস্য দিন, শিশুকে সক্রিয় রাখুন। পায়খানা শক্ত বা ব্যথাভরা থাকতেই থাকলে স্বাস্থ্যকর্মীর কাছে যান।\n\n## ভিন্ন গতি স্বাভাবিক\n\nছেলে-মেয়ে, প্রথম সন্তান বা পরের সন্তান — সবাই আলাদা গতিতে শেখে। বিকাশে ভিন্নতা আছে এমন শিশুরাও শিখতে পারে, প্রায়ই একটু বেশি সময় আর পরিষ্কার রুটিন লাগে। সাধারণত দিনে শুকনো থাকা আগে আসে, রাতে পরে; রাতে মাঝে মাঝে বিছানা ভেজানো আরও কয়েক বছর পর্যন্ত খুব সাধারণ।\n\n## কখন স্বাস্থ্যকর্মীর কাছে যাবেন\n\nপ্রস্রাবে ব্যথা বা জ্বালা, প্রস্রাব বা পায়খানায় রক্ত, জ্বর, খুব শক্ত পায়খানা, অথবা মাসের পর মাস শুকনো থাকা শিশু আবার ঘনঘন ভেজাতে শুরু করলে ডাক্তার বা স্বাস্থ্যকর্মীকে দেখান। তিন বছর অনেকটা পার হয়ে গেলেও যদি তৈরি হওয়ার কোনো লক্ষণই না দেখেন, সেটাও জিজ্ঞেস করুন।"}'::jsonb, '{}'::jsonb, 5, 730, 1461, '{}'::text[], 'any', ARRAY['toilet training', 'potty', 'nappy', 'diaper', 'wetting', 'constipation']::text[], false, 'in_review'::lp_review_status, 5004),
  ('ec-picky-eating-family-meals', 'article', 'scientific', 'shared', 'important', 'guideline', '🍛', '{"en":"Picky eating and family meals with Bangladeshi foods","bn":"খেতে না চাওয়া আর পরিবারের সাথে খাওয়া: দেশি খাবারে সমাধান"}'::jsonb, '{"en":"Fussy eating is common at this age. You decide what food is offered and when; your child decides how much. Eat together, keep it calm, and let home-cooked Bangladeshi food do the work.","bn":"এই বয়সে খেতে না চাওয়া খুব সাধারণ। কী খাবার আর কখন দেবেন, সেটা ঠিক করবেন আপনি; কতটুকু খাবে, সেটা ঠিক করবে শিশু। একসাথে খান, পরিবেশ শান্ত রাখুন, আর ঘরের রান্না দেশি খাবারের ওপর ভরসা রাখুন।"}'::jsonb, '{"en":"Between two and four, many children who once ate everything suddenly eat only rice, refuse anything green, or want the same food every day. This is common. Children grow more slowly now than in their first year, so their appetite often drops. Many are also cautious about new foods, and saying ''no'' is part of becoming independent.\n\n## A simple division of jobs\n\nYou decide **what** food is offered, **when** and **where**. Your child decides **whether** to eat and **how much**. When parents trust this, mealtimes become calmer and children usually eat what they need over a few days, even if one meal is small.\n\n## What to offer\n\nThe same food the family eats, made soft and less spicy, is ideal. Aim for variety across the day:\n\n- Rice, roti, khichuri, chira or suji as the base\n- Dal, egg, fish (small fish or deboned large fish), chicken or meat for protein\n- Green leafy shak, pumpkin, carrot, papaya, beans and other vegetables\n- Seasonal fruit such as banana, guava, mango, papaya or jackfruit\n- Milk or yoghurt (doi); breastfeeding can continue if mother and child wish\n\nOffer three meals and one or two planned snacks, at roughly the same times. Water is the best drink between meals. Too much milk or juice fills the stomach and leaves little room for food.\n\n## Making meals work\n\n1. Eat together whenever you can, at a mat or a table, with the TV off and phones away.\n2. Serve a small portion. Your child can ask for more.\n3. Put one food your child already likes on the plate with anything new.\n4. Offer a new food again and again, without pressure. Many children need to see and taste a food many times before they accept it.\n5. Let your child feed themselves, with fingers or a spoon, even if it is messy.\n6. Keep mealtimes to about 20–30 minutes, then calmly clear the plate. No extra snacks until the next planned time.\n7. Let your child help: wash vegetables, tear shak, stir the dal (away from the flame).\n\n## What to avoid\n\n- Forcing, threatening or feeding while the child cries\n- Chasing with a plate, or feeding in front of a phone or TV\n- Using sweets or chips as a reward, or giving them when a meal is refused\n- Packaged chips, chanachur, sugary drinks, packaged juice and sweets as everyday snacks\n- Choking risks: whole nuts and peanuts, whole grapes, hard sweets, popcorn, fish with bones. Cut round foods into small pieces and sit down to eat.\n\n## When to see a health worker\n\nPicky eating alone is rarely a problem if your child is active and growing well on the growth chart. See a health worker if your child is losing weight or not growing, is very tired or pale, often gags, chokes or vomits, eats only a handful of foods, or if mealtimes cause great distress for the family. Keep going to growth checks.","bn":"দুই থেকে চার বছর বয়সে অনেক শিশু, যে আগে সব খেত, হঠাৎ শুধু ভাত খায়, সবুজ কিছু দেখলেই মুখ ফিরিয়ে নেয়, বা প্রতিদিন একই খাবার চায়। এটা খুব সাধারণ। প্রথম বছরের তুলনায় এখন শিশুর বৃদ্ধি ধীর, তাই ক্ষুধাও প্রায়ই কমে যায়। নতুন খাবারে অনেক শিশু সাবধানী হয়, আর ‘না’ বলা স্বাধীন হয়ে ওঠারই অংশ।\n\n## দায়িত্বের সহজ ভাগ\n\n**কী** খাবার, **কখন** আর **কোথায়** দেবেন — সেটা আপনার সিদ্ধান্ত। **খাবে কি না** আর **কতটুকু** খাবে — সেটা শিশুর। এই ভাগে ভরসা রাখলে খাওয়ার সময় শান্ত হয়, আর এক বেলা কম খেলেও কয়েক দিনের হিসাবে শিশু সাধারণত দরকারমতো খেয়ে নেয়।\n\n## কী খাওয়াবেন\n\nপরিবারের সবাই যা খায়, সেটাই একটু নরম করে আর কম ঝাল দিয়ে দেওয়া সবচেয়ে ভালো। সারাদিনে বৈচিত্র্য রাখুন:\n\n- মূল খাবার হিসেবে ভাত, রুটি, খিচুড়ি, চিড়া বা সুজি\n- আমিষের জন্য ডাল, ডিম, মাছ (ছোট মাছ বা কাঁটা বাছা বড় মাছ), মুরগি বা মাংস\n- সবুজ শাক, মিষ্টি কুমড়া, গাজর, পেঁপে, শিম ও অন্যান্য সবজি\n- মৌসুমি ফল — কলা, পেয়ারা, আম, পেঁপে, কাঁঠাল\n- দুধ বা দই; মা আর শিশু চাইলে বুকের দুধ চালিয়ে যেতে পারেন\n\nদিনে তিন বেলা খাবার আর এক-দুইবার পরিকল্পিত নাশতা দিন, মোটামুটি একই সময়ে। দুই খাবারের মাঝে পানিই সবচেয়ে ভালো পানীয়। বেশি দুধ বা জুস পেট ভরিয়ে দেয়, খাবারের জায়গা থাকে না।\n\n## খাওয়ার সময়টা সহজ করতে\n\n১. যখনই পারেন একসাথে খান — পাটিতে বা টেবিলে, টিভি বন্ধ, ফোন দূরে।\n২. অল্প করে দিন। শিশু চাইলে আরও দেবেন।\n৩. নতুন খাবারের পাশে শিশুর পছন্দের একটা খাবার রাখুন।\n৪. নতুন খাবার বারবার দিন, চাপ ছাড়া। অনেক শিশু কোনো খাবার মেনে নেওয়ার আগে সেটা অনেকবার দেখে আর চেখে দেখে।\n৫. শিশুকে নিজের হাতে বা চামচে খেতে দিন, একটু ছড়িয়ে ফেললেও।\n৬. খাওয়ার সময় মোটামুটি ২০–৩০ মিনিট রাখুন, তারপর শান্তভাবে থালা তুলে নিন। পরের নির্ধারিত সময়ের আগে আলাদা নাশতা নয়।\n৭. শিশুকে কাজে লাগান: সবজি ধোয়া, শাক বাছা, চুলা থেকে দূরে ডাল নাড়া।\n\n## যা এড়িয়ে চলবেন\n\n- জোর করা, ভয় দেখানো বা কাঁদতে থাকা শিশুকে খাওয়ানো\n- থালা হাতে পেছনে পেছনে দৌড়ানো, বা ফোন-টিভি দেখিয়ে খাওয়ানো\n- পুরস্কার হিসেবে মিষ্টি বা চিপস দেওয়া, বা ভাত না খেলে সেগুলো দেওয়া\n- প্রতিদিনের নাশতায় প্যাকেটের চিপস, চানাচুর, কোমল পানীয়, প্যাকেটের জুস আর মিষ্টি\n- গলায় আটকানোর ঝুঁকি: আস্ত বাদাম ও চিনাবাদাম, আস্ত আঙুর, শক্ত চকলেট-লজেন্স, পপকর্ন, কাঁটাসহ মাছ। গোল খাবার ছোট টুকরো করুন, আর বসে খাওয়ান।\n\n## কখন স্বাস্থ্যকর্মীর কাছে যাবেন\n\nশিশু চঞ্চল থাকলে আর গ্রোথ চার্টে ঠিকমতো বাড়লে শুধু বাছাই করে খাওয়া সাধারণত সমস্যা নয়। ওজন কমলে বা না বাড়লে, খুব ক্লান্ত বা ফ্যাকাশে দেখালে, প্রায়ই ওয়াক তোলে, গলায় আটকায় বা বমি করলে, মাত্র হাতে গোনা কয়েকটা খাবার খেলে, বা খাওয়া নিয়ে পরিবারে খুব কষ্ট হলে স্বাস্থ্যকর্মীকে দেখান। নিয়মিত ওজন-উচ্চতা মাপাতে যেতে থাকুন।"}'::jsonb, '{}'::jsonb, 5, 730, 1461, '{}'::text[], 'any', ARRAY['picky eating', 'fussy eater', 'family meals', 'khichuri', 'snacks', 'choking', 'appetite']::text[], false, 'in_review'::lp_review_status, 5005),
  ('ec-sleep-2-to-4', 'article', 'scientific', 'shared', 'important', 'guideline', '🌙', '{"en":"Sleep from two to four years","bn":"দুই থেকে চার বছরের ঘুম"}'::jsonb, '{"en":"WHO advises 11–14 hours of good sleep a day for two-year-olds and 10–13 hours for three- and four-year-olds, naps included, with regular times. A calm bedtime routine is the key.","bn":"WHO-র পরামর্শ: দুই বছরের শিশুর দিনে ১১–১৪ ঘণ্টা, আর তিন-চার বছরের শিশুর ১০–১৩ ঘণ্টা ভালো ঘুম দরকার — দুপুরের ঘুমসহ, নিয়মিত সময়ে। শান্ত একটা ঘুমের রুটিনই আসল চাবি।"}'::jsonb, '{"en":"Good sleep helps young children grow, learn, remember, fight illness and manage their feelings. A tired child is often a cranky child, and tantrums are much more common when sleep is short.\n\n## How much sleep\n\nThe World Health Organization''s guideline for children under five recommends, across 24 hours and including naps:\n\n- **Two-year-olds:** 11 to 14 hours of good-quality sleep\n- **Three- and four-year-olds:** 10 to 13 hours of good-quality sleep\n\nIt also advises regular sleep and wake-up times. Many two-year-olds still need one afternoon nap; some three- and four-year-olds stop napping, while others still need a short rest. Children differ, so watch your child: if they wake up fairly cheerful and get through the day without being overtired, they are probably getting enough.\n\n## A bedtime routine that works\n\nDo the same few calm steps, in the same order, at about the same time every night:\n\n1. Dinner a little while before bed, then a wash, brushing teeth and a toilet visit.\n2. Night clothes, lights dimmed, screens off for at least an hour before.\n3. A story, a song, or a short talk about the day — or a dua, if your family prays.\n4. A cuddle and a clear goodnight, then lights off.\n\nThe whole routine can take 20 to 30 minutes. Fathers can own it on some nights; many children love that special time with Abbu.\n\n## Sleep in Bangladeshi homes\n\nMany families sleep together in one room or one bed, and that is a normal choice. What matters most is a calm, dark, quiet space and a regular time. Late evening guests, TV in the bedroom or a late dinner can push bedtime later; try to protect your child''s sleep time even on busy days. In hot weather, a fan, light cotton clothes and a mosquito net help.\n\n## Common problems\n\n- **Stalling** (''One more story! Water!''): build the extras into the routine, then hold the limit kindly.\n- **Night waking**: go in calmly, keep the light low and talk little, then settle back.\n- **Fears and bad dreams**: comfort, a small night light, and reassurance help. A bad dream is different from a scary-looking night terror, when a child is not fully awake; stay close, keep them safe and do not try to wake them.\n\n## When to see a health worker\n\nSee a health worker if your child snores loudly most nights, stops breathing or gasps in sleep, is very sleepy in the day despite enough hours, has frequent night terrors or sleepwalking, or if sleep problems are causing great strain for the family.","bn":"ভালো ঘুম ছোট শিশুকে বাড়তে, শিখতে, মনে রাখতে, অসুখের সাথে লড়তে আর আবেগ সামলাতে সাহায্য করে। ঘুম কম হলে শিশু খিটখিটে হয়, রেগে কান্নাকাটিও অনেক বেড়ে যায়।\n\n## কতটুকু ঘুম দরকার\n\nপাঁচ বছরের কম শিশুদের জন্য বিশ্ব স্বাস্থ্য সংস্থার (WHO) নির্দেশিকা অনুযায়ী, ২৪ ঘণ্টায়, দুপুরের ঘুমসহ:\n\n- **দুই বছর বয়সে:** ১১ থেকে ১৪ ঘণ্টা ভালো ঘুম\n- **তিন ও চার বছর বয়সে:** ১০ থেকে ১৩ ঘণ্টা ভালো ঘুম\n\nনির্দেশিকা নিয়মিত সময়ে ঘুমানো আর ঘুম থেকে ওঠার কথাও বলে। অনেক দুই বছরের শিশুর এখনো দুপুরে একবার ঘুম লাগে; তিন-চার বছরে কেউ কেউ দুপুরে আর ঘুমায় না, কারও আবার একটু বিশ্রাম লাগে। প্রতিটি শিশু আলাদা — খেয়াল করুন, শিশু যদি মোটামুটি হাসিখুশি ঘুম থেকে ওঠে আর সারাদিন অতিরিক্ত ক্লান্ত না থাকে, তাহলে সম্ভবত যথেষ্ট ঘুম হচ্ছে।\n\n## কাজের একটা ঘুমের রুটিন\n\nপ্রতি রাতে প্রায় একই সময়ে, একই ক্রমে কয়েকটা শান্ত ধাপ:\n\n১. ঘুমের কিছুক্ষণ আগে রাতের খাবার, তারপর হাতমুখ ধোয়া, দাঁত ব্রাশ আর টয়লেট।\n২. রাতের জামা, আলো কমিয়ে দেওয়া; অন্তত এক ঘণ্টা আগে থেকে স্ক্রিন বন্ধ।\n৩. একটা গল্প, একটা ছড়া বা গান, অথবা সারাদিনের কথা — পরিবারে দোয়া পড়ার অভ্যাস থাকলে একটা দোয়া।\n৪. আদর করে স্পষ্টভাবে শুভরাত্রি, তারপর বাতি বন্ধ।\n\nপুরো রুটিনে ২০ থেকে ৩০ মিনিট লাগতে পারে। কিছু রাতে বাবা পুরোটা করাতে পারেন — অনেক শিশু আব্বুর সাথে এই সময়টা খুব ভালোবাসে।\n\n## আমাদের ঘরের ঘুম\n\nঅনেক পরিবারে সবাই এক ঘরে বা এক বিছানায় ঘুমায় — এটা একটা স্বাভাবিক পছন্দ। সবচেয়ে জরুরি হলো শান্ত, অন্ধকার, নিরিবিলি জায়গা আর নিয়মিত সময়। রাতে মেহমান, শোবার ঘরে টিভি বা দেরিতে রাতের খাবার ঘুমের সময় পিছিয়ে দেয়; ব্যস্ত দিনেও শিশুর ঘুমের সময়টা রক্ষা করার চেষ্টা করুন। গরমে ফ্যান, পাতলা সুতির জামা আর মশারি সাহায্য করে।\n\n## সাধারণ সমস্যা\n\n- **সময় টানা** (“আরেকটা গল্প! পানি খাব!”): এগুলো রুটিনের মধ্যেই রেখে দিন, তারপর নরমভাবে সীমা ধরে রাখুন।\n- **রাতে জেগে ওঠা**: শান্তভাবে যান, আলো কম রাখুন, কথা কম বলুন, আবার ঘুম পাড়িয়ে দিন।\n- **ভয় আর দুঃস্বপ্ন**: আদর, ছোট একটা মৃদু বাতি আর আশ্বাস কাজে দেয়। দুঃস্বপ্ন আর ‘নাইট টেরর’ (night terror) আলাদা — নাইট টেররে শিশু ভয়ংকরভাবে চিৎকার করলেও পুরোপুরি জেগে থাকে না। কাছে থাকুন, নিরাপদ রাখুন, জোর করে জাগানোর চেষ্টা করবেন না।\n\n## কখন স্বাস্থ্যকর্মীর কাছে যাবেন\n\nবেশিরভাগ রাতে জোরে নাক ডাকলে, ঘুমের মধ্যে শ্বাস থেমে যায় বা হাঁসফাঁস করলে, যথেষ্ট ঘুমের পরও দিনে খুব ঘুমঘুম থাকলে, ঘনঘন নাইট টেরর বা ঘুমের মধ্যে হাঁটা হলে, অথবা ঘুমের সমস্যায় পরিবারের ওপর খুব চাপ পড়লে স্বাস্থ্যকর্মীকে দেখান।"}'::jsonb, '{}'::jsonb, 4, 730, 1461, '{}'::text[], 'any', ARRAY['sleep', 'bedtime', 'nap', 'routine', 'night waking', 'snoring']::text[], false, 'in_review'::lp_review_status, 5006),
  ('ec-speech-language', 'article', 'scientific', 'shared', 'important', 'guideline', '🗣️', '{"en":"Speech and language from two to four, and when to worry","bn":"দুই থেকে চার বছরের কথা বলা ও ভাষা — কখন চিন্তা করবেন"}'::jsonb, '{"en":"Between two and four, children go from short word pairs to full sentences and questions. Talk, read and sing every day, and see a health worker early if speech seems behind.","bn":"দুই থেকে চার বছরে শিশু দুই শব্দের বাক্য থেকে পুরো বাক্য আর প্রশ্নে পৌঁছায়। প্রতিদিন কথা বলুন, পড়ুন, ছড়া কাটুন — আর কথা বলায় পিছিয়ে আছে মনে হলে দেরি না করে স্বাস্থ্যকর্মীকে দেখান।"}'::jsonb, '{"en":"The years from two to four are a language explosion. Children learn new words almost every day, start joining them into sentences and begin asking endless questions. Every child goes at their own pace, but there are useful guides to what most children do.\n\n## What most children do\n\nThese are based on the CDC''s ''Learn the Signs. Act Early.'' milestones:\n\n- **By 2 years:** says at least two words together, such as ''more milk''; points to a few body parts when asked\n- **By 2½ years:** says about 50 words; follows two-step instructions such as ''Put the toy down and close the door''\n- **By 3 years:** talks with you in a back-and-forth conversation of at least two turns; asks who, what, where or why questions\n- **By 4 years:** says sentences of four or more words; talks about something that happened during the day\n\nUnderstanding usually comes before speaking: children understand much more than they can say.\n\n## Two or more languages\n\nMany Bangladeshi children hear Bangla, a regional dialect, English or another language at home. Growing up with more than one language does not cause speech delay. Speak the language you are most comfortable in, richly and often.\n\n## How to help every day\n\n- Talk about what you are doing: ''I am cutting the papaya. It is orange inside.''\n- Get down to your child''s level and wait. Give them time to answer.\n- Add a little to what they say. Child: ''Car!'' You: ''Yes, a big red car!''\n- If they say a word wrongly, repeat it correctly without correcting them: ''Yes, a banana.''\n- Read picture books and sing rhymes every day.\n- Ask open questions: ''What happened next?'' rather than only yes/no ones.\n- Keep screens off in the background. Real talk with people builds language; a TV playing all day reduces it.\n\n## When to talk to a health worker\n\nDon''t ''wait and see'' for too long. If you are worried, ask early; early help makes a real difference. Speak to a doctor or health worker if your child:\n\n- is not putting two words together by around 2 years\n- does not understand simple instructions\n- cannot be understood by family members by 3, or by most people by 4\n- does not ask questions or join a simple conversation by 3 or 4\n- does not respond to sounds or their name, or you wonder if they hear well\n- loses words or skills they used to have, at any age\n\nThe doctor may suggest a hearing test and a development check. In Bangladesh, child development centres in larger government hospitals, and speech and language therapists, can assess and help. Ask your doctor where the nearest service is.","bn":"দুই থেকে চার বছর হলো ভাষার ‘বিস্ফোরণের’ সময়। শিশু প্রায় প্রতিদিন নতুন শব্দ শেখে, শব্দ জুড়ে বাক্য বানাতে শুরু করে, আর অবিরাম প্রশ্ন করে। প্রতিটি শিশু নিজের গতিতে এগোয়, তবে বেশিরভাগ শিশু কী পারে তার একটা ধারণা থাকা উপকারী।\n\n## বেশিরভাগ শিশু যা পারে\n\nযুক্তরাষ্ট্রের CDC-র ‘Learn the Signs. Act Early.’ মাইলফলক অনুযায়ী:\n\n- **২ বছরে:** অন্তত দুটি শব্দ জুড়ে বলে, যেমন “আরো দুধ”; জিজ্ঞেস করলে শরীরের কয়েকটা অংশ দেখায়\n- **আড়াই বছরে:** প্রায় ৫০টি শব্দ বলে; দুই ধাপের নির্দেশ মানে, যেমন “খেলনাটা রাখো, তারপর দরজাটা বন্ধ করো”\n- **৩ বছরে:** আপনার সাথে অন্তত দুইবার আসা-যাওয়ার কথোপকথন চালায়; কে, কী, কোথায়, কেন — এমন প্রশ্ন করে\n- **৪ বছরে:** চার বা তার বেশি শব্দের বাক্য বলে; দিনে কী হয়েছে তা নিয়ে কিছু বলে\n\nসাধারণত বোঝা আগে আসে, বলা পরে — শিশু যতটা বলতে পারে, বোঝে তার চেয়ে অনেক বেশি।\n\n## দুই বা তার বেশি ভাষা\n\nঅনেক শিশু বাসায় শুদ্ধ বাংলা, আঞ্চলিক ভাষা, ইংরেজি বা অন্য ভাষা শোনে। একাধিক ভাষায় বড় হওয়া কথা বলায় দেরির কারণ নয়। যে ভাষায় আপনি সবচেয়ে স্বচ্ছন্দ, সেই ভাষায় প্রাণ খুলে, বেশি বেশি কথা বলুন।\n\n## প্রতিদিন যেভাবে সাহায্য করবেন\n\n- যা করছেন তা বলে বলে করুন: “আমি পেঁপে কাটছি। দেখো, ভেতরটা কমলা।”\n- শিশুর চোখের সমান হয়ে বসুন, তারপর অপেক্ষা করুন — উত্তর দেওয়ার সময় দিন।\n- শিশুর কথায় একটু যোগ করুন। শিশু: “গাড়ি!” আপনি: “হ্যাঁ, বড় একটা লাল গাড়ি!”\n- ভুল উচ্চারণ করলে শুধরে না দিয়ে ঠিকটা আবার বলুন: “হ্যাঁ, কলা।”\n- প্রতিদিন ছবির বই পড়ুন, ছড়া কাটুন।\n- শুধু হ্যাঁ-না নয়, খোলা প্রশ্ন করুন: “তারপর কী হলো?”\n- পেছনে টিভি চালিয়ে রাখবেন না। মানুষের সাথে সত্যিকারের কথা ভাষা গড়ে; সারাদিন টিভি চললে কথা কমে যায়।\n\n## কখন স্বাস্থ্যকর্মীর সাথে কথা বলবেন\n\n“দেখি, আরেকটু বড় হোক” বলে বেশি দিন অপেক্ষা করবেন না। চিন্তা থাকলে আগেভাগে জিজ্ঞেস করুন — আগে সাহায্য পেলে সত্যিই অনেক উপকার হয়। ডাক্তার বা স্বাস্থ্যকর্মীর সাথে কথা বলুন যদি শিশু:\n\n- মোটামুটি ২ বছরেও দুটি শব্দ জুড়ে না বলে\n- সহজ নির্দেশ বুঝতে না পারে\n- ৩ বছরে পরিবারের লোকেরাও তার কথা বুঝতে না পারে, বা ৪ বছরে বেশিরভাগ মানুষ না বোঝে\n- ৩-৪ বছরেও প্রশ্ন না করে বা সহজ কথোপকথনে অংশ না নেয়\n- শব্দে বা নাম ধরে ডাকলে সাড়া না দেয়, বা মনে হয় ঠিকমতো শুনছে না\n- যেকোনো বয়সে আগে বলা শব্দ বা শেখা দক্ষতা হারিয়ে ফেলে\n\nডাক্তার শ্রবণ পরীক্ষা (hearing test) আর বিকাশ যাচাইয়ের পরামর্শ দিতে পারেন। বাংলাদেশে বড় সরকারি হাসপাতালের শিশু বিকাশ কেন্দ্র আর স্পিচ অ্যান্ড ল্যাঙ্গুয়েজ থেরাপিস্টরা শিশুর মূল্যায়ন ও সাহায্য করতে পারেন। কাছের সেবা কোথায়, ডাক্তারের কাছে জেনে নিন।"}'::jsonb, '{}'::jsonb, 5, 730, 1461, '{}'::text[], 'any', ARRAY['speech', 'language', 'talking', 'late talker', 'words', 'hearing', 'bilingual']::text[], false, 'in_review'::lp_review_status, 5007),
  ('ec-development-concerns', 'article', 'scientific', 'shared', 'important', 'guideline', '🧩', '{"en":"Early signs to discuss with a doctor","bn":"যে লক্ষণগুলো নিয়ে ডাক্তারের সাথে কথা বলবেন"}'::jsonb, '{"en":"Some signs in how a child plays, talks and connects are worth checking early. Noticing them is not a diagnosis, and asking is never an overreaction. Early help works best.","bn":"শিশু কীভাবে খেলে, কথা বলে আর মানুষের সাথে মেশে — তার কিছু লক্ষণ আগেভাগে যাচাই করা ভালো। লক্ষণ দেখা মানেই রোগ নির্ণয় নয়, আর জিজ্ঞেস করা কখনো বাড়াবাড়ি নয়। আগে সাহায্য পেলেই সবচেয়ে বেশি উপকার।"}'::jsonb, '{"en":"Parents usually know their child best. If something about how your child plays, talks or connects with people worries you, it is worth asking about. Many worries turn out to be nothing. When there is a difference, such as a hearing problem, a language delay or autism, help that starts early makes a real difference to the child and the family.\n\n## Signs worth talking about\n\nThese are not a checklist for any condition. They are reasons to ask a doctor for a development check. Talk to a health worker if your child:\n\n- rarely looks at your face or shares a smile with you\n- does not respond when you call their name, though they seem to hear other sounds\n- does not point to show you things or to ask for something\n- does not bring things to show you or try to get your attention to share interest\n- has very few words, or does not put two words together by about 2 years\n- does not play pretend (feeding a doll, making a block into a car) by around 2½–3 years\n- lines up or spins objects for long periods and gets very upset if this is interrupted\n- repeats the same movements again and again, such as hand-flapping or rocking\n- is very upset by small changes in routine\n- reacts very strongly, or hardly at all, to sounds, textures, smells or pain\n- shows little interest in other children\n- has trouble walking, falls very often or uses one side of the body much more than the other\n- **loses** words or skills they used to have, at any age\n\nA child may show one of these signs and be developing well. What matters is the overall picture and whether it continues.\n\n## What to do\n\n1. Write down what you notice, with examples and the child''s age. A short phone video can help the doctor.\n2. Talk to a doctor or health worker. Ask for a development check and a hearing test.\n3. If needed, you may be referred to a child development centre, a paediatric neurologist, or a speech, occupational or physiotherapist. In Bangladesh, such services are available in many larger government and private hospitals; ask your doctor which is nearest.\n4. Keep talking, playing and reading with your child while you wait. That is never wasted.\n\n## Words that help, words that hurt\n\nAvoid labels such as ''slow'', ''stubborn'' or ''pagol'' in front of the child or anyone else. Children who develop differently are not caused by bad parenting, the mother''s sins, the evil eye or anything you did. Every child, with or without a diagnosis, can learn, grow and be loved.\n\n## Look after yourselves\n\nWaiting for answers is hard. Share the load between both parents, and let family members help. Support groups for parents of children with developmental differences exist in Bangladesh, and talking to other parents can be a great comfort.","bn":"সন্তানকে সাধারণত বাবা-মা-ই সবচেয়ে ভালো চেনেন। শিশু কীভাবে খেলে, কথা বলে বা মানুষের সাথে মেশে — এর কিছু নিয়ে চিন্তা হলে জিজ্ঞেস করা ভালো। অনেক চিন্তাই শেষে কিছু না হয়ে দাঁড়ায়। আর যদি কোনো ভিন্নতা থাকে — যেমন কানে কম শোনা, কথা বলায় দেরি বা অটিজম (autism) — তাহলে আগেভাগে সাহায্য শুরু হলে শিশু আর পরিবারের জন্য সত্যিই অনেক পার্থক্য হয়।\n\n## যে লক্ষণ নিয়ে কথা বলা উচিত\n\nএগুলো কোনো রোগ নির্ণয়ের তালিকা নয় — ডাক্তারের কাছে বিকাশ যাচাই করানোর কারণ মাত্র। স্বাস্থ্যকর্মীর সাথে কথা বলুন যদি শিশু:\n\n- আপনার মুখের দিকে খুব কম তাকায়, বা আপনার হাসির জবাবে হাসে না\n- অন্য শব্দ শুনলেও নাম ধরে ডাকলে সাড়া দেয় না\n- কিছু দেখাতে বা চাইতে আঙুল দিয়ে দেখায় না\n- মজার কিছু এনে আপনাকে দেখায় না, বা ভাগ করে নিতে আপনার মনোযোগ চায় না\n- খুব কম শব্দ বলে, বা মোটামুটি ২ বছরেও দুটি শব্দ জুড়ে বলে না\n- আড়াই-তিন বছরের মধ্যেও ভান-খেলা করে না (পুতুলকে খাওয়ানো, ব্লককে গাড়ি বানানো)\n- অনেকক্ষণ ধরে জিনিস সারি করে সাজায় বা ঘোরায়, আর বাধা দিলে খুব বেশি ভেঙে পড়ে\n- একই নড়াচড়া বারবার করে, যেমন হাত ঝাপটানো বা দোলা\n- রুটিনে ছোট পরিবর্তনেও খুব বেশি অস্থির হয়ে যায়\n- শব্দ, স্পর্শ, গন্ধ বা ব্যথায় খুব বেশি — বা প্রায় কোনো — প্রতিক্রিয়া দেখায় না\n- অন্য শিশুদের প্রতি খুব কম আগ্রহ দেখায়\n- হাঁটতে কষ্ট হয়, খুব ঘনঘন পড়ে যায়, বা শরীরের এক পাশ অন্য পাশের চেয়ে অনেক বেশি ব্যবহার করে\n- যেকোনো বয়সে আগে পারা শব্দ বা দক্ষতা **হারিয়ে ফেলে**\n\nএকটা লক্ষণ থাকলেও শিশু ঠিকঠাক বেড়ে উঠতে পারে। আসল বিষয় হলো সামগ্রিক চিত্র, আর লক্ষণটা চলতে থাকছে কি না।\n\n## কী করবেন\n\n১. যা দেখছেন, উদাহরণ আর শিশুর বয়সসহ লিখে রাখুন। ফোনে ছোট একটা ভিডিও ডাক্তারের কাজে আসতে পারে।\n২. ডাক্তার বা স্বাস্থ্যকর্মীর সাথে কথা বলুন। বিকাশ যাচাই আর শ্রবণ পরীক্ষার কথা বলুন।\n৩. দরকার হলে আপনাকে শিশু বিকাশ কেন্দ্র, শিশু নিউরোলজিস্ট, বা স্পিচ, অকুপেশনাল বা ফিজিওথেরাপিস্টের কাছে পাঠানো হতে পারে। বাংলাদেশে অনেক বড় সরকারি ও বেসরকারি হাসপাতালে এসব সেবা আছে; কাছের কোনটা, ডাক্তারের কাছে জেনে নিন।\n৪. অপেক্ষার সময়েও শিশুর সাথে কথা বলা, খেলা আর পড়া চালিয়ে যান। এর কিছুই বৃথা যায় না।\n\n## যে কথা সাহায্য করে, যে কথা কষ্ট দেয়\n\nশিশুর সামনে বা অন্য কারও কাছে ‘হাবা’, ‘জেদি’, ‘পাগল’ — এমন তকমা দেবেন না। শিশুর ভিন্নভাবে বেড়ে ওঠার কারণ খারাপ লালনপালন, মায়ের দোষ, নজর লাগা বা আপনার কোনো কাজ নয়। রোগ নির্ণয় হোক বা না হোক, প্রতিটি শিশু শিখতে, বাড়তে আর ভালোবাসা পেতে পারে।\n\n## নিজেদেরও যত্ন নিন\n\nউত্তরের অপেক্ষা কঠিন। বাবা-মা দুজনে মিলে ভার ভাগ করুন, পরিবারের অন্যদের সাহায্য করতে দিন। বাংলাদেশে বিকাশে ভিন্নতা আছে এমন শিশুদের বাবা-মায়েদের সহায়তা দল আছে; অন্য বাবা-মায়ের সাথে কথা বললে অনেক সান্ত্বনা মেলে।"}'::jsonb, '{}'::jsonb, 5, 730, 1461, '{}'::text[], 'any', ARRAY['development', 'autism', 'delay', 'red flags', 'early intervention', 'eye contact', 'regression']::text[], false, 'in_review'::lp_review_status, 5008),
  ('ec-pretend-play', 'article', 'scientific', 'shared', 'educational', 'consensus', '🧸', '{"en":"Pretend play and imagination","bn":"ভান-খেলা আর কল্পনার জগৎ"}'::jsonb, '{"en":"When your child cooks pretend rice or turns a box into a bus, they are building language, thinking and social skills. You need no expensive toys, just time and everyday things.","bn":"শিশু যখন মিছিমিছি ভাত রাঁধে বা একটা বাক্সকে বাস বানায়, তখন সে ভাষা, চিন্তা আর মেলামেশার দক্ষতা গড়ছে। দামি খেলনা লাগে না — লাগে সময় আর ঘরের সাধারণ জিনিস।"}'::jsonb, '{"en":"Somewhere around two, many children start to pretend: a block becomes a phone, a spoon feeds a doll, a cushion is a boat. By three and four, the play becomes richer: whole stories of shops, doctors, cooking, weddings and journeys by rickshaw or bus.\n\n## Why pretend play matters\n\nPretend play is serious work for a young child. While playing, they:\n\n- use new words and practise conversation\n- think in symbols, which later helps with reading and maths\n- try out how other people feel and behave (being Ammu, the doctor, the shopkeeper)\n- practise planning, taking turns and solving problems\n- work through worries, such as a visit to the doctor or a new baby\n\n## You don''t need expensive toys\n\nThe best props are everyday things: pots and spoons, an old phone without a battery, cloth for a saree or a cape, empty boxes and bottles, a small broom, a doll or soft toy, leaves and pebbles for ''food''. Children often prefer these to battery toys that do all the playing for them.\n\n## How parents can join in\n\n1. Follow your child''s lead. Ask, ''Who am I in this game?'' and play that part.\n2. Add a small twist to stretch the story: ''Oh no, the bus has a flat tyre! What shall we do?''\n3. Talk a lot, but leave space. Let your child decide what happens.\n4. Give play time every day, even 10–15 minutes of your full attention.\n5. Let the mess be part of it; tidy up together afterwards.\n\n## Fathers and pretend play\n\nFathers sometimes feel awkward joining a tea party or a pretend kitchen. Children don''t need an actor, just a willing playmate. Being the customer in a pretend shop or the patient at a pretend clinic is a wonderful way for Abbu to connect and to show that caring and cooking are for everyone.\n\n## Boys and girls\n\nLet boys play with dolls and cooking pots, and girls with cars and tools. Pretend play is how children try out the whole world; none of it is only for one gender.\n\n## When to ask\n\nIf your child shows no pretend play at all by around two and a half to three years, especially if there are also concerns about speech or how they connect with people, mention it to a health worker. It may be nothing, but an early check is always worth it.","bn":"দুই বছরের আশেপাশে অনেক শিশু ‘মিছিমিছি’ খেলা শুরু করে — ব্লক হয়ে যায় ফোন, চামচ দিয়ে পুতুলকে খাওয়ানো, কুশন হয়ে যায় নৌকা। তিন-চার বছরে খেলা আরও জমে ওঠে: দোকান, ডাক্তার, রান্না, বিয়েবাড়ি, রিকশা বা বাসে বেড়াতে যাওয়া — পুরো গল্প।\n\n## ভান-খেলা কেন জরুরি\n\nছোট শিশুর জন্য ভান-খেলা আসলে গুরুত্বপূর্ণ কাজ। খেলতে খেলতে সে:\n\n- নতুন শব্দ ব্যবহার করে, কথোপকথনের অভ্যাস করে\n- প্রতীক দিয়ে চিন্তা করে — যা পরে পড়া আর অঙ্কে কাজে লাগে\n- অন্যের অনুভূতি আর আচরণ বুঝে দেখে (আম্মু হওয়া, ডাক্তার হওয়া, দোকানদার হওয়া)\n- পরিকল্পনা, পালা করে খেলা আর সমস্যা সমাধানের চর্চা করে\n- দুশ্চিন্তা সামলায় — যেমন ডাক্তারের কাছে যাওয়া বা নতুন ভাই-বোন\n\n## দামি খেলনা লাগে না\n\nসবচেয়ে ভালো উপকরণ ঘরের সাধারণ জিনিস: হাঁড়ি-চামচ, ব্যাটারি খোলা পুরোনো ফোন, শাড়ি বা চাদর বানানোর মতো এক টুকরো কাপড়, খালি বাক্স আর বোতল, ছোট ঝাড়ু, পুতুল বা নরম খেলনা, ‘খাবার’ বানানোর জন্য পাতা আর নুড়ি। যে খেলনা ব্যাটারিতে নিজেই সব খেলে দেয়, তার চেয়ে শিশুরা প্রায়ই এগুলোই বেশি পছন্দ করে।\n\n## বাবা-মা কীভাবে যোগ দেবেন\n\n১. শিশুর পেছনে পেছনে চলুন। জিজ্ঞেস করুন, “এই খেলায় আমি কে?” — তারপর সেই চরিত্রটা করুন।\n২. গল্পে ছোট একটা মোড় দিন: “ওহ হো, বাসের চাকা পাংচার! এখন কী করি?”\n৩. অনেক কথা বলুন, কিন্তু জায়গা রাখুন — কী হবে, সেটা শিশুকে ঠিক করতে দিন।\n৪. প্রতিদিন খেলার সময় দিন, পুরো মনোযোগ দিয়ে ১০–১৫ মিনিট হলেও।\n৫. একটু এলোমেলো হলে হোক; পরে একসাথে গুছিয়ে নিন।\n\n## বাবা আর ভান-খেলা\n\nমিছিমিছি চা-পার্টি বা রান্নাবাটিতে যোগ দিতে অনেক বাবার একটু সংকোচ লাগে। শিশুর অভিনেতা লাগে না, লাগে একজন আগ্রহী খেলার সাথি। মিছিমিছি দোকানের খদ্দের বা মিছিমিছি ক্লিনিকের রোগী হওয়া — আব্বুর জন্য শিশুর কাছাকাছি আসার আর দেখানোর দারুণ উপায় যে যত্ন নেওয়া আর রান্না করা সবার কাজ।\n\n## ছেলে আর মেয়ে\n\nছেলেকে পুতুল আর হাঁড়ি-পাতিল নিয়ে খেলতে দিন, মেয়েকে গাড়ি আর যন্ত্রপাতি নিয়ে। ভান-খেলার মধ্য দিয়ে শিশু পুরো পৃথিবীটা চিনে দেখে — এর কিছুই শুধু ছেলে বা শুধু মেয়ের জন্য নয়।\n\n## কখন জিজ্ঞেস করবেন\n\nআড়াই থেকে তিন বছরের মধ্যেও শিশু যদি একেবারেই ভান-খেলা না করে — বিশেষ করে কথা বলা বা মানুষের সাথে মেশা নিয়েও যদি চিন্তা থাকে — স্বাস্থ্যকর্মীকে জানান। হয়তো কিছুই নয়, কিন্তু আগেভাগে একবার দেখিয়ে নেওয়া সবসময়ই ভালো।"}'::jsonb, '{}'::jsonb, 4, 730, 1461, '{}'::text[], 'any', ARRAY['pretend play', 'imagination', 'role play', 'toys', 'creativity']::text[], false, 'in_review'::lp_review_status, 5009),
  ('ec-reading-aloud', 'article', 'scientific', 'shared', 'educational', 'consensus', '📖', '{"en":"Reading aloud every day","bn":"প্রতিদিন জোরে জোরে পড়ে শোনানো"}'::jsonb, '{"en":"A few minutes of reading together each day builds words, attention and a love of books, and it is one of the warmest times you can share. You don''t need to be a great reader to do it.","bn":"প্রতিদিন কয়েক মিনিট একসাথে পড়লে শিশুর শব্দভান্ডার, মনোযোগ আর বইয়ের প্রতি ভালোবাসা বাড়ে — আর এটা একসাথে কাটানো সবচেয়ে উষ্ণ সময়গুলোর একটা। এর জন্য ভালো পাঠক হওয়ার দরকার নেই।"}'::jsonb, '{"en":"Reading aloud to your child is one of the simplest and most powerful things you can do for their development. Books bring words that rarely come up in daily talk, and the closeness of sharing a book helps your child feel safe and loved.\n\n## What reading together builds\n\n- A bigger vocabulary and longer sentences\n- Listening and attention, a little longer each month\n- Understanding of stories: beginnings, problems and endings\n- Early understanding that print carries meaning, which prepares them for school\n- A strong bond, especially when it becomes a daily ritual\n\n## How to read with a two- to four-year-old\n\n1. Choose a regular time, such as after lunch or at bedtime, so it becomes a habit.\n2. Sit close, with the book where your child can see the pictures.\n3. Let your child turn the pages, point and talk. You do not need to finish the book.\n4. Use voices, sounds and faces. A tiger can growl; a train can go ''jhik jhik''.\n5. Ask questions: ''What is the cat doing? What will happen next? How does she feel?''\n6. Read the same favourite book again and again. Repetition is how young children learn.\n7. Link stories to your child''s life: ''We saw a cow like this at Nanu''s house!''\n\n## Which books\n\n- Bangla and English picture books with clear, bright pictures\n- Books about everyday life: food, family, animals, the market, rain\n- Rhyme books and books with repeated lines that children can join in\n- Simple lift-the-flap or touch books for younger children\n\nBooks don''t have to be expensive. Look for low-cost children''s books at book fairs such as the Ekushey Boi Mela, local libraries, or swap books with other families. You can also make a book: stick family photos or drawings in a notebook and write a line under each.\n\n## If you are not a confident reader\n\nYou can still share books. Talk about the pictures in your own words, tell stories from your childhood, or ask an older sibling or grandparent to read. What matters most is time together and talk, not perfect reading.\n\n## Fathers, grandparents and siblings\n\nA bedtime story is a perfect daily job for a father, even after a long day. Grandparents are often wonderful storytellers. Older siblings feel proud reading to a little one.\n\n## A note on screens\n\nStories read from a phone, or watched as videos, are not the same as a person reading with the child. If you use an e-book, read it together and keep the sounds and animations off.","bn":"শিশুকে জোরে জোরে পড়ে শোনানো তার বিকাশের জন্য সবচেয়ে সহজ আর শক্তিশালী কাজগুলোর একটা। প্রতিদিনের কথাবার্তায় যে শব্দগুলো খুব কম আসে, বই সেগুলো নিয়ে আসে। আর একসাথে বই পড়ার ঘনিষ্ঠতায় শিশু নিরাপদ আর ভালোবাসা অনুভব করে।\n\n## একসাথে পড়ায় কী গড়ে ওঠে\n\n- বড় শব্দভান্ডার আর লম্বা বাক্য বলার ক্ষমতা\n- শোনা আর মনোযোগ — প্রতি মাসে একটু একটু করে বাড়ে\n- গল্প বোঝা: শুরু, সমস্যা আর শেষ\n- লেখার মধ্যে অর্থ থাকে — এই প্রাথমিক ধারণা, যা স্কুলের জন্য তৈরি করে\n- গভীর সম্পর্ক, বিশেষ করে যখন এটা রোজকার অভ্যাস হয়ে যায়\n\n## দুই থেকে চার বছরের শিশুর সাথে যেভাবে পড়বেন\n\n১. একটা নির্দিষ্ট সময় বেছে নিন — দুপুরের খাবারের পরে বা ঘুমের আগে — যাতে অভ্যাস হয়ে যায়।\n২. কাছে বসুন, বইটা এমনভাবে ধরুন যাতে শিশু ছবি দেখতে পায়।\n৩. শিশুকে পাতা উল্টাতে, আঙুল দিয়ে দেখাতে আর কথা বলতে দিন। বই শেষ করতেই হবে, এমন নয়।\n৪. গলা বদলান, শব্দ করুন, মুখভঙ্গি করুন। বাঘ গর্জন করবে, রেলগাড়ি চলবে ঝিক ঝিক।\n৫. প্রশ্ন করুন: “বিড়ালটা কী করছে? এরপর কী হবে? ওর কেমন লাগছে?”\n৬. প্রিয় বইটা বারবার পড়ুন। ছোট শিশুরা বারবার শুনেই শেখে।\n৭. গল্পকে শিশুর জীবনের সাথে মেলান: “নানুবাড়িতে আমরা এমন একটা গরু দেখেছিলাম না!”\n\n## কোন বই\n\n- পরিষ্কার, উজ্জ্বল ছবির বাংলা ও ইংরেজি ছবির বই\n- প্রতিদিনের জীবন নিয়ে বই — খাবার, পরিবার, পশুপাখি, বাজার, বৃষ্টি\n- ছড়ার বই, আর যে বইয়ে একই লাইন বারবার আসে, যাতে শিশুও সাথে বলতে পারে\n- ছোটদের জন্য ভাঁজ খোলা বা ছুঁয়ে দেখার সহজ বই\n\nবই দামি হতে হবে না। অমর একুশে বইমেলার মতো মেলায়, স্থানীয় পাঠাগারে কম দামের শিশুতোষ বই খুঁজুন, বা অন্য পরিবারের সাথে বই বদলাবদলি করুন। নিজেও বই বানাতে পারেন — খাতায় পরিবারের ছবি বা আঁকা লাগিয়ে প্রতিটার নিচে এক লাইন লিখে দিন।\n\n## পড়তে আত্মবিশ্বাস না থাকলে\n\nতবুও বই ভাগ করে নিতে পারেন। নিজের ভাষায় ছবিগুলো নিয়ে কথা বলুন, নিজের ছোটবেলার গল্প বলুন, বা বড় ভাই-বোন বা দাদা-দাদি, নানা-নানিকে পড়ে শোনাতে বলুন। নিখুঁত পড়া নয় — একসাথে সময় আর কথাবার্তাই আসল।\n\n## বাবা, দাদা-দাদি আর ভাই-বোন\n\nলম্বা দিনের পরেও ঘুমের আগের গল্পটা বাবার জন্য দারুণ একটা রোজকার দায়িত্ব। দাদা-দাদি, নানা-নানিরা প্রায়ই চমৎকার গল্পকথক। বড় ভাই-বোনও ছোটটাকে পড়ে শোনাতে পেরে গর্বিত হয়।\n\n## স্ক্রিন নিয়ে একটা কথা\n\nফোন থেকে গল্প পড়া বা ভিডিওতে গল্প দেখা — একজন মানুষের সাথে বসে পড়ার মতো নয়। ই-বুক ব্যবহার করলে একসাথে পড়ুন, আর শব্দ ও অ্যানিমেশন বন্ধ রাখুন।"}'::jsonb, '{}'::jsonb, 4, 730, 1461, '{}'::text[], 'any', ARRAY['reading', 'books', 'stories', 'read aloud', 'bedtime story', 'language']::text[], false, 'in_review'::lp_review_status, 5010),
  ('ec-screens-2-to-4', 'article', 'scientific', 'shared', 'important', 'guideline', '📱', '{"en":"Screens at two to four: less, better, together","bn":"দুই থেকে চার বছরে স্ক্রিন: কম, ভালো, একসাথে"}'::jsonb, '{"en":"WHO advises no screen time before two, and no more than one hour a day at two to four, with less being better. Choose good content, watch together, and keep phones away from meals and bedtime.","bn":"WHO-র পরামর্শ: দুই বছরের আগে স্ক্রিন নয়, আর দুই থেকে চার বছরে দিনে এক ঘণ্টার বেশি নয় — যত কম, তত ভালো। ভালো কিছু বেছে নিন, একসাথে দেখুন, আর খাওয়া ও ঘুমের সময় ফোন দূরে রাখুন।"}'::jsonb, '{"en":"Phones, TVs and tablets are part of family life. Used with care, a little screen time can be fine. But young children learn best from real people, play and movement, and too much screen time takes those away.\n\n## What the guidelines say\n\nThe World Health Organization''s guideline for children under five says:\n\n- **Under two years:** screen time is not recommended.\n- **Two to four years:** no more than **one hour a day** of sitting screen time, and **less is better**.\n\nWHO also advises that when young children are sitting, reading and storytelling with a caregiver is the better choice. The American Academy of Pediatrics adds: choose high-quality programmes and watch them with your child. Video calls with family, such as with a father working abroad, are different: they are a real conversation, so enjoy them together.\n\n## Why it matters\n\n- Time on screens is time not spent talking, playing, moving or sleeping.\n- Fast, noisy videos and endless auto-play can make it harder for a child to settle and focus.\n- Screens before bed can delay sleep.\n- A TV left on in the background reduces how much adults talk with children.\n\n## Making it work at home\n\n1. **Choose the content.** Slow, gentle programmes with simple stories, songs and real-life topics. Avoid fighting, frightening scenes and adverts.\n2. **Watch together.** Talk about it: ''What is the duck doing? Have you seen a duck at the pond?''\n3. **Set times and places.** For example, one short programme after the afternoon nap, on the TV in the main room, not on a phone in bed.\n4. **No screens at meals.** Eating while watching makes children ignore hunger and fullness, and takes away family talk.\n5. **Screens off at least an hour before bed,** and no screens in the bedroom.\n6. **Warn before ending:** ''When this song ends, the TV goes off.'' Then switch off calmly, even if there are tears.\n7. **Have other things ready:** books, blocks, crayons, a ball, outdoor play.\n\n## The phone as a babysitter\n\nIt is very tempting to hand over a phone so you can cook, rest or talk. Every parent does this sometimes. Try to save it for real need and keep it short. Busy boxes of safe household things, a corner with books, or giving your child a small job beside you can often fill the same gap.\n\n## Look at your own screen use\n\nChildren copy what they see. Try phone-free times for the whole family, such as meals and the first half-hour after coming home. Fathers and mothers can agree on this together, and explain it kindly to grandparents and other carers.\n\n## When to seek help\n\nTalk to a health worker if your child becomes very distressed whenever screens stop, if screen use is crowding out sleep, play or eating, or if there are concerns about speech or how your child connects with people.","bn":"ফোন, টিভি, ট্যাব এখন পরিবারের জীবনেরই অংশ। যত্ন নিয়ে ব্যবহার করলে অল্প একটু স্ক্রিন সমস্যা নয়। কিন্তু ছোট শিশু সবচেয়ে ভালো শেখে সত্যিকারের মানুষ, খেলা আর নড়াচড়া থেকে — আর বেশি স্ক্রিন এগুলোর সময় কেড়ে নেয়।\n\n## নির্দেশিকা কী বলে\n\nপাঁচ বছরের কম শিশুদের জন্য বিশ্ব স্বাস্থ্য সংস্থার (WHO) নির্দেশিকা:\n\n- **দুই বছরের নিচে:** স্ক্রিন দেখার পরামর্শ দেওয়া হয় না।\n- **দুই থেকে চার বছর:** বসে বসে স্ক্রিন দেখা দিনে **এক ঘণ্টার বেশি নয়**, আর **যত কম, তত ভালো**।\n\nWHO আরও বলে, শিশু যখন বসে থাকে, তখন বড়দের সাথে বই পড়া আর গল্প বলাই ভালো বিকল্প। আমেরিকান একাডেমি অব পেডিয়াট্রিক্স (AAP) যোগ করে: মানসম্মত অনুষ্ঠান বেছে নিন আর শিশুর সাথে বসে দেখুন। পরিবারের সাথে ভিডিও কল — যেমন বিদেশে কর্মরত বাবার সাথে — আলাদা বিষয়; এটা সত্যিকারের কথোপকথন, তাই একসাথে উপভোগ করুন।\n\n## কেন জরুরি\n\n- স্ক্রিনের সময় মানে কথা বলা, খেলা, দৌড়ানো বা ঘুমের সময় কমে যাওয়া।\n- দ্রুত, হইচইয়ের ভিডিও আর একটার পর একটা নিজে নিজে চলতে থাকা ভিডিও শিশুর শান্ত হওয়া আর মনোযোগ দেওয়া কঠিন করে।\n- ঘুমের আগে স্ক্রিন ঘুম দেরি করিয়ে দেয়।\n- পেছনে টিভি চলতে থাকলে বড়রা শিশুর সাথে কম কথা বলে।\n\n## ঘরে যেভাবে মানবেন\n\n১. **কী দেখবে, বেছে দিন।** ধীর, শান্ত অনুষ্ঠান — সহজ গল্প, ছড়া-গান, বাস্তব জীবনের বিষয়। মারামারি, ভয়ের দৃশ্য আর বিজ্ঞাপন এড়িয়ে চলুন।\n২. **একসাথে দেখুন।** কথা বলুন: “হাঁসটা কী করছে? পুকুরে হাঁস দেখেছ না?”\n৩. **সময় আর জায়গা ঠিক করুন।** যেমন, দুপুরের ঘুমের পর বসার ঘরের টিভিতে একটা ছোট অনুষ্ঠান — বিছানায় শুয়ে ফোনে নয়।\n৪. **খাওয়ার সময় স্ক্রিন নয়।** দেখতে দেখতে খেলে শিশু ক্ষুধা আর পেট ভরার অনুভূতি টের পায় না, পরিবারের গল্পগুজবও হারিয়ে যায়।\n৫. **ঘুমের অন্তত এক ঘণ্টা আগে স্ক্রিন বন্ধ,** আর শোবার ঘরে স্ক্রিন নয়।\n৬. **বন্ধ করার আগে জানিয়ে দিন:** “এই গানটা শেষ হলে টিভি বন্ধ।” তারপর শান্তভাবে বন্ধ করুন — কান্না হলেও।\n৭. **বিকল্প হাতের কাছে রাখুন:** বই, ব্লক, রং পেনসিল, বল, বাইরে খেলা।\n\n## ফোন যখন ‘দেখাশোনার লোক’\n\nরান্না, বিশ্রাম বা কথা বলার জন্য শিশুর হাতে ফোন ধরিয়ে দিতে খুব ইচ্ছে করে। সব বাবা-মা-ই মাঝে মাঝে এটা করেন। চেষ্টা করুন সত্যিকারের দরকারে আর অল্প সময়ের জন্য দিতে। ঘরের নিরাপদ জিনিস ভরা একটা ‘খেলার বাক্স’, বইয়ের একটা কোণ, বা আপনার পাশে বসে ছোট্ট একটা কাজ — প্রায়ই একই কাজ করে দেয়।\n\n## নিজের স্ক্রিন ব্যবহারও দেখুন\n\nশিশু যা দেখে, তাই শেখে। পুরো পরিবারের জন্য কিছু ফোনমুক্ত সময় রাখুন — যেমন খাওয়ার সময় আর বাসায় ফেরার পর প্রথম আধা ঘণ্টা। বাবা-মা মিলে এটা ঠিক করুন, আর দাদা-দাদি, নানা-নানি ও অন্য যারা দেখাশোনা করেন, তাঁদের নরমভাবে বুঝিয়ে বলুন।\n\n## কখন সাহায্য নেবেন\n\nস্ক্রিন বন্ধ করলেই শিশু খুব বেশি ভেঙে পড়লে, স্ক্রিনের কারণে ঘুম, খেলা বা খাওয়া কমে গেলে, অথবা কথা বলা বা মানুষের সাথে মেশা নিয়ে চিন্তা থাকলে স্বাস্থ্যকর্মীর সাথে কথা বলুন।"}'::jsonb, '{}'::jsonb, 4, 730, 1461, '{}'::text[], 'any', ARRAY['screen time', 'phone', 'tv', 'cartoons', 'youtube', 'mealtime', 'video call']::text[], false, 'in_review'::lp_review_status, 5011),
  ('ec-sharing-playing', 'article', 'scientific', 'shared', 'educational', 'consensus', '🧑‍🤝‍🧑', '{"en":"Sharing and playing with other children","bn":"ভাগ করে নেওয়া আর অন্য শিশুদের সাথে খেলা"}'::jsonb, '{"en":"Sharing is hard for two-year-olds and grows slowly. Start with taking turns, give lots of chances to play with others, and show sharing yourself.","bn":"দুই বছরের শিশুর জন্য ভাগ করা কঠিন — এটা ধীরে ধীরে আসে। পালা করে খেলা দিয়ে শুরু করুন, অন্যদের সাথে খেলার অনেক সুযোগ দিন, আর নিজে ভাগ করে দেখান।"}'::jsonb, '{"en":"''Mine!'' may be one of your two-year-old''s favourite words. This is normal. Young children are only just learning that other people have feelings and wishes too. Sharing is a skill that grows over several years, with practice and kind guidance.\n\n## How play changes from two to four\n\n- **Around two:** children often play next to each other rather than with each other. They watch and copy, but grab toys easily.\n- **Around two and a half to three:** they start to join in, play simple games together and take turns with help.\n- **Around three to four:** they play together more, invent games, and begin to comfort a friend who is upset. Real sharing becomes easier, though not every time.\n\n## Teach turn-taking first\n\nTaking turns is easier to understand than ''sharing'' because the toy comes back.\n\n1. Use simple words: ''Rafi''s turn, then your turn.''\n2. Keep turns short at first. Count to ten together, or sing a short rhyme.\n3. Help the waiting child: ''It is hard to wait. Let''s watch Rafi, then it is you.''\n4. Make sure the toy really does come back, so your child learns to trust turns.\n5. Praise it: ''You gave Tania a turn. Look how happy she is!''\n\n## Before visitors or a trip to cousins\n\nLet your child choose two or three very special toys to put away. Bring out things that are easy to share: blocks, balls, crayons and paper, cooking pots. This prevents many battles.\n\n## Show sharing yourself\n\nChildren learn by watching. Share your food: ''Would you like half of my guava?'' Let them see adults taking turns, offering, saying thank you. Ask for a taste of their snack and thank them warmly if they give one.\n\n## Don''t force it\n\nGrabbing a toy from your child to give to a guest teaches that the bigger person takes things. Instead, help both children: ''Ayesha wants the car. When you finish, can you give it to her?'' Sometimes a child may keep something truly theirs, and that is okay too.\n\n## Chances to play\n\nRegular play with cousins, neighbours'' children, or at a playground helps more than any lesson. Brothers and sisters, a mosque or community courtyard, a pre-school or a daycare can all be places to practise. If your child has few chances to meet other children, try to make some.\n\n## When to ask\n\nMost children who struggle with sharing are simply young. Mention it to a health worker if your child shows little interest in other children at all, very often hurts others, or if there are other concerns about speech or development.","bn":"“আমার!” — দুই বছরের শিশুর প্রিয় শব্দগুলোর একটা হতে পারে এটা। এটা স্বাভাবিক। ছোট শিশু সবে শিখছে যে অন্যদেরও অনুভূতি আর চাওয়া আছে। ভাগ করে নেওয়া এমন একটা দক্ষতা, যা অনুশীলন আর নরম দিকনির্দেশনায় কয়েক বছর ধরে গড়ে ওঠে।\n\n## দুই থেকে চার বছরে খেলা কীভাবে বদলায়\n\n- **দুই বছরের দিকে:** শিশুরা প্রায়ই একে অপরের সাথে নয়, পাশাপাশি খেলে। দেখে, নকল করে, কিন্তু খেলনা সহজেই কেড়ে নেয়।\n- **আড়াই থেকে তিন বছরে:** একসাথে খেলায় যোগ দিতে শুরু করে, সহজ খেলা খেলে, সাহায্য পেলে পালা করে খেলে।\n- **তিন থেকে চার বছরে:** বেশি একসাথে খেলে, নতুন খেলা বানায়, মন খারাপ বন্ধুকে সান্ত্বনা দিতে শুরু করে। সত্যিকারের ভাগ করা সহজ হয় — যদিও সবসময় নয়।\n\n## আগে শেখান পালা করে খেলা\n\n‘ভাগ করা’র চেয়ে ‘পালা’ বোঝা সহজ, কারণ খেলনাটা আবার ফিরে আসে।\n\n১. সহজ শব্দ ব্যবহার করুন: “আগে রাফির পালা, তারপর তোমার।”\n২. শুরুতে পালা ছোট রাখুন। একসাথে দশ পর্যন্ত গুনুন, বা ছোট একটা ছড়া বলুন।\n৩. অপেক্ষা করা শিশুকে সাহায্য করুন: “অপেক্ষা করা কঠিন, তাই না? চলো রাফিকে দেখি, তারপর তুমি।”\n৪. খেলনাটা যেন সত্যিই ফিরে আসে — তাহলে শিশু পালায় ভরসা করতে শেখে।\n৫. প্রশংসা করুন: “তুমি তানিয়াকে খেলতে দিলে। দেখো, ও কত খুশি!”\n\n## মেহমান আসার আগে বা চাচাতো-মামাতো ভাই-বোনদের বাসায় যাওয়ার আগে\n\nশিশুকে খুব প্রিয় দু-তিনটা খেলনা বেছে তুলে রাখতে দিন। সহজে ভাগ করা যায় এমন জিনিস বের করুন — ব্লক, বল, রং পেনসিল আর কাগজ, হাঁড়ি-পাতিল। এতে অনেক ঝগড়া আগেই এড়ানো যায়।\n\n## নিজে ভাগ করে দেখান\n\nশিশু দেখে দেখে শেখে। নিজের খাবার ভাগ করুন: “আমার পেয়ারার অর্ধেক খাবে?” বড়রা পালা করছে, এগিয়ে দিচ্ছে, ধন্যবাদ বলছে — এগুলো শিশুকে দেখতে দিন। ওর নাশতা থেকে একটু চেয়ে নিন, দিলে আন্তরিকভাবে ধন্যবাদ দিন।\n\n## জোর করবেন না\n\nশিশুর হাত থেকে খেলনা কেড়ে মেহমানকে দিলে সে শেখে — যে বড়, সে কেড়ে নেয়। বরং দুজনকেই সাহায্য করুন: “আয়েশা গাড়িটা চাইছে। তোমার খেলা শেষ হলে ওকে দেবে?” কখনো কখনো শিশু নিজের খুব আপন কিছু নিজের কাছে রাখতে চাইলে, সেটাও ঠিক আছে।\n\n## খেলার সুযোগ\n\nকোনো উপদেশের চেয়ে চাচাতো-মামাতো ভাই-বোন, প্রতিবেশীর বাচ্চা বা খেলার মাঠে নিয়মিত খেলা অনেক বেশি কাজে দেয়। নিজের ভাই-বোন, পাড়ার উঠান, প্রি-স্কুল বা ডে-কেয়ার — সবই অনুশীলনের জায়গা হতে পারে। শিশুর অন্য শিশুদের সাথে দেখা হওয়ার সুযোগ কম হলে কিছু সুযোগ তৈরি করুন।\n\n## কখন জিজ্ঞেস করবেন\n\nযেসব শিশু ভাগ করতে পারে না, তাদের বেশিরভাগই আসলে শুধু ছোট। তবে শিশু অন্য শিশুদের প্রতি একেবারেই আগ্রহ না দেখালে, খুব ঘনঘন অন্যদের আঘাত করলে, বা কথা বলা বা বিকাশ নিয়ে অন্য চিন্তা থাকলে স্বাস্থ্যকর্মীকে জানান।"}'::jsonb, '{}'::jsonb, 4, 730, 1461, '{}'::text[], 'any', ARRAY['sharing', 'turn taking', 'friends', 'playdate', 'cousins', 'social skills']::text[], false, 'in_review'::lp_review_status, 5012),
  ('ec-manners-kindness', 'article', 'general', 'shared', 'educational', 'consensus', '🌷', '{"en":"Manners and kindness: small habits, big hearts","bn":"আদব-কায়দা আর দয়া: ছোট অভ্যাস, বড় মন"}'::jsonb, '{"en":"Young children learn manners and kindness mostly by copying the adults around them. Show it, name it, practise it in play, and praise it when you see it.","bn":"ছোট শিশু আদব-কায়দা আর দয়া শেখে মূলত আশেপাশের বড়দের দেখে। নিজে করে দেখান, নাম দিন, খেলায় অনুশীলন করান, আর চোখে পড়লেই প্রশংসা করুন।"}'::jsonb, '{"en":"Every family hopes for a child who is polite, respectful and kind. At two to four, children are ready to start learning these habits, but they learn far more from what you do than from what you say.\n\n## Start with a few simple words\n\n- ''Please'' and ''thank you'' (or ''dhonnobad'')\n- ''Sorry'' when they hurt someone or break something\n- Greeting family and guests in the way your family does\n- ''Excuse me'' or waiting for a turn to speak\n\nSay these words to your child too. ''Please pass me the cup. Thank you!'' A child who is spoken to politely learns to speak politely.\n\n## Kindness grows from feeling understood\n\nChildren who feel their own feelings are understood find it easier to understand others. When your child is sad and you comfort them, they learn what comfort looks like. Over time, many three- and four-year-olds begin to comfort others themselves.\n\n- Point out others'' feelings: ''Nanu is tired. Shall we bring her water?''\n- Notice kind acts out loud: ''You gave Tuni your umbrella. That was kind.''\n- Talk about kindness in stories: ''How did the rabbit help his friend?''\n\n## Small daily ways to practise\n\n1. Give your child a small job that helps the family, such as putting shoes in place or giving plates out.\n2. Let them give something to a guest, a neighbour or a person in need, with you beside them.\n3. Treat animals gently together: water for birds, no hitting cats or dogs.\n4. Practise in pretend play: the doll says thank you, the teddy says sorry.\n5. Respect elders and look after younger children, as a family value you live every day.\n\n## About ''sorry''\n\nA forced ''sorry'' often teaches a child to say the word without meaning it. Instead, help them notice the other child (''Look, Rafi is crying. His arm hurts.'') and make it better: a gentle touch, fetching a cloth, or saying sorry when they are ready.\n\n## A note on hugs and kisses\n\nIt is kind to greet guests, but don''t force a child to hug or kiss anyone, even relatives. Let them choose another way, such as waving or saying salam or hello. This teaches respect for others and that their own body belongs to them.\n\n## Be patient\n\nTwo-year-olds forget, three-year-olds argue, and four-year-olds may show off rudeness to see what happens. This is normal. Calm reminders, lots of good examples and warm praise will build manners slowly. Shaming or hitting teaches the opposite of kindness.","bn":"প্রতিটি পরিবার চায় সন্তান হোক ভদ্র, শ্রদ্ধাশীল আর দয়ালু। দুই থেকে চার বছর বয়সে শিশু এই অভ্যাসগুলো শিখতে শুরু করার জন্য তৈরি — তবে আপনি যা বলেন তার চেয়ে অনেক বেশি শেখে আপনি যা করেন তা থেকে।\n\n## কয়েকটা সহজ শব্দ দিয়ে শুরু\n\n- “দয়া করে” আর “ধন্যবাদ”\n- কাউকে ব্যথা দিলে বা কিছু ভেঙে ফেললে “দুঃখিত” বা “সরি”\n- পরিবারে যেভাবে সালাম বা সম্ভাষণ দেওয়া হয়, সেভাবে বড়দের আর মেহমানদের সম্ভাষণ\n- কথার মাঝে না ঢুকে নিজের পালার অপেক্ষা করা\n\nশিশুকেও এই শব্দগুলো বলুন: “কাপটা একটু দাও তো। ধন্যবাদ!” যে শিশুর সাথে ভদ্রভাবে কথা বলা হয়, সে ভদ্রভাবে কথা বলতে শেখে।\n\n## বোঝা পেলে দয়া জন্মায়\n\nযে শিশু মনে করে তার অনুভূতি কেউ বোঝে, অন্যকে বোঝা তার জন্য সহজ হয়। শিশুর মন খারাপ হলে আপনি যখন সান্ত্বনা দেন, সে শেখে সান্ত্বনা দেখতে কেমন। সময়ের সাথে অনেক তিন-চার বছরের শিশু নিজেই অন্যদের সান্ত্বনা দিতে শুরু করে।\n\n- অন্যের অনুভূতি দেখিয়ে দিন: “নানু ক্লান্ত। চলো ওনাকে পানি দিয়ে আসি।”\n- দয়ার কাজ জোরে বলে খেয়াল করুন: “তুমি তুনিকে তোমার ছাতাটা দিলে — কী সুন্দর কাজ!”\n- গল্পে দয়া নিয়ে কথা বলুন: “খরগোশটা বন্ধুকে কীভাবে সাহায্য করল?”\n\n## প্রতিদিন অনুশীলনের ছোট উপায়\n\n১. পরিবারের কাজে লাগে এমন ছোট একটা দায়িত্ব দিন — জুতা জায়গামতো রাখা, সবার থালা দেওয়া।\n২. আপনার পাশে থেকে মেহমান, প্রতিবেশী বা অভাবী কাউকে কিছু দিতে দিন।\n৩. একসাথে পশুপাখির প্রতি নরম হোন — পাখির জন্য পানি রাখা, বিড়াল-কুকুরকে না মারা।\n৪. ভান-খেলায় অনুশীলন করুন — পুতুল ধন্যবাদ বলছে, টেডি সরি বলছে।\n৫. বড়দের সম্মান আর ছোটদের যত্ন — এটা পরিবারের এমন মূল্যবোধ হোক, যা আপনি প্রতিদিন করে দেখান।\n\n## “সরি” নিয়ে একটা কথা\n\nজোর করে “সরি” বলালে অনেক সময় শিশু মানে না বুঝেই শব্দটা বলতে শেখে। বরং অন্য শিশুটাকে খেয়াল করতে সাহায্য করুন (“দেখো, রাফি কাঁদছে। ওর হাতে ব্যথা লেগেছে।”), আর ঠিক করে দেওয়ার সুযোগ দিন — আলতো করে হাত বুলিয়ে দেওয়া, একটা কাপড় এনে দেওয়া, বা মন তৈরি হলে সরি বলা।\n\n## জড়িয়ে ধরা আর চুমু নিয়ে\n\nমেহমানকে সম্ভাষণ জানানো ভালো, কিন্তু আত্মীয় হলেও কাউকে জড়িয়ে ধরতে বা চুমু দিতে শিশুকে জোর করবেন না। হাত নাড়া বা সালাম দেওয়ার মতো অন্য উপায় বেছে নিতে দিন। এতে শিশু অন্যকে সম্মান করতে শেখে, আর শেখে — তার শরীর তার নিজের।\n\n## ধৈর্য রাখুন\n\nদুই বছরের শিশু ভুলে যায়, তিন বছরের শিশু তর্ক করে, আর চার বছরের শিশু কী হয় দেখতে ইচ্ছে করে বেয়াদবি দেখায়। এটা স্বাভাবিক। শান্তভাবে মনে করিয়ে দেওয়া, অনেক ভালো উদাহরণ আর আন্তরিক প্রশংসা — এতেই ধীরে ধীরে আদব গড়ে ওঠে। লজ্জা দেওয়া বা মারা দয়ার ঠিক উল্টোটা শেখায়।"}'::jsonb, '{}'::jsonb, 4, 730, 1461, '{}'::text[], 'any', ARRAY['manners', 'kindness', 'please', 'thank you', 'sorry', 'respect', 'empathy', 'greeting']::text[], false, 'in_review'::lp_review_status, 5013),
  ('ec-handwashing-hygiene', 'article', 'scientific', 'shared', 'important', 'guideline', '🧼', '{"en":"Handwashing and everyday hygiene habits","bn":"হাত ধোয়া আর প্রতিদিনের পরিচ্ছন্নতার অভ্যাস"}'::jsonb, '{"en":"Washing hands with soap at the right times is one of the best ways to protect your child from diarrhoea and chest infections. Make it a fun daily habit now and it will last for life.","bn":"ঠিক সময়ে সাবান দিয়ে হাত ধোয়া ডায়রিয়া আর বুকের সংক্রমণ থেকে শিশুকে বাঁচানোর সবচেয়ে ভালো উপায়গুলোর একটা। এখনই এটাকে মজার রোজকার অভ্যাস বানান — সারাজীবন থেকে যাবে।"}'::jsonb, '{"en":"Young children touch everything, then put their hands in their mouths. Germs that cause diarrhoea and chest infections such as pneumonia spread easily this way. The World Health Organization lists handwashing with soap among the key ways to prevent these illnesses. Between two and four, children can learn to wash their own hands, with your help and example.\n\n## When to wash hands with soap\n\n- Before eating, and before touching food\n- After using the toilet or potty\n- After playing outside, or with soil, sand or animals\n- After coughing, sneezing or blowing the nose\n- When coming home from outside\n\nAdults should also wash before cooking or feeding the child, and after cleaning a child''s bottom.\n\n## How to wash, step by step\n\n1. Wet hands with clean water.\n2. Rub with soap to make bubbles.\n3. Scrub palms, backs of hands, between fingers, thumbs and under nails.\n4. Keep scrubbing for about 20 seconds, the length of a short rhyme sung twice.\n5. Rinse well under running water or water poured from a jug.\n6. Dry on a clean cloth, or shake dry in the air.\n\n## Making it easy and fun\n\n- Put a small stool or a step by the basin or tubewell, so your child can reach.\n- Keep soap where your child can reach it. Any ordinary bar soap works; a bottle of soapy water made with a little detergent powder is a cheaper option many families use.\n- Sing a hand-washing song together.\n- Let your child wash a doll''s hands, or make bubbles.\n- Wash your own hands at the same time. Children copy.\n\n## Other daily habits\n\n- **Nails:** keep them short and clean; trim them weekly.\n- **Bath:** a daily bath or wash is good in Bangladesh''s heat. Dry well between skin folds.\n- **Shoes or sandals outside:** they protect the feet from cuts and from worms in the soil.\n- **Coughs and sneezes:** teach your child to cough into the elbow, then wash hands.\n- **Clean water:** give drinking water that is boiled, filtered or from a safe source, and cover stored water.\n- **Toilet use:** use a latrine or toilet, and wash hands after.\n- **Teeth:** brush twice a day.\n\nAsk your health worker whether your child needs a deworming tablet, and when.\n\n## When to see a health worker\n\nGet help quickly if your child has diarrhoea with blood, signs of dehydration (very thirsty or unable to drink, sunken eyes, very little wee, unusually sleepy), fast or difficult breathing, or a fever that does not settle. For loose stools, give ORS and continue feeding, as your health worker advises.","bn":"ছোট শিশুরা সবকিছু ছোঁয়, তারপর হাত মুখে দেয়। ডায়রিয়া আর নিউমোনিয়ার মতো বুকের সংক্রমণের জীবাণু এভাবে সহজেই ছড়ায়। বিশ্ব স্বাস্থ্য সংস্থা (WHO) সাবান দিয়ে হাত ধোয়াকে এসব রোগ প্রতিরোধের প্রধান উপায়গুলোর মধ্যে রেখেছে। দুই থেকে চার বছরে শিশু আপনার সাহায্য আর উদাহরণ দেখে নিজের হাত নিজে ধুতে শিখতে পারে।\n\n## কখন সাবান দিয়ে হাত ধোবে\n\n- খাওয়ার আগে, আর খাবার ধরার আগে\n- টয়লেট বা পটি ব্যবহারের পরে\n- বাইরে খেলার পরে, মাটি, বালি বা পশুপাখি ধরার পরে\n- কাশি, হাঁচি বা নাক ঝাড়ার পরে\n- বাইরে থেকে বাসায় ফিরে\n\nবড়রাও রান্নার আগে বা শিশুকে খাওয়ানোর আগে, আর শিশুর পায়খানা পরিষ্কার করার পরে হাত ধোবেন।\n\n## ধাপে ধাপে হাত ধোয়া\n\n১. পরিষ্কার পানি দিয়ে হাত ভেজান।\n২. সাবান ঘষে ফেনা তুলুন।\n৩. হাতের তালু, হাতের পিঠ, আঙুলের ফাঁক, বুড়ো আঙুল আর নখের নিচে ঘষুন।\n৪. মোটামুটি ২০ সেকেন্ড ঘষতে থাকুন — একটা ছোট ছড়া দুইবার বলতে যতক্ষণ লাগে।\n৫. কলের পানিতে বা মগ দিয়ে ঢেলে ভালো করে ধুয়ে ফেলুন।\n৬. পরিষ্কার কাপড়ে মুছুন, বা বাতাসে ঝেড়ে শুকান।\n\n## সহজ আর মজার করতে\n\n- বেসিন বা টিউবওয়েলের পাশে ছোট একটা টুল বা পিঁড়ি রাখুন, যাতে শিশু নাগাল পায়।\n- সাবান শিশুর হাতের নাগালে রাখুন। যেকোনো সাধারণ সাবানই চলে; অল্প ডিটারজেন্ট পাউডার গুলে বানানো সাবান-পানির বোতল — অনেক পরিবার এই সস্তা উপায় ব্যবহার করে।\n- একসাথে হাত ধোয়ার একটা গান গান।\n- শিশুকে পুতুলের হাত ধোয়াতে দিন, বা ফেনার বুদবুদ বানাতে দিন।\n- একই সময়ে নিজের হাতও ধুয়ে নিন — শিশু দেখে শেখে।\n\n## আরও কিছু রোজকার অভ্যাস\n\n- **নখ:** ছোট আর পরিষ্কার রাখুন, সপ্তাহে একবার কাটুন।\n- **গোসল:** আমাদের গরমে প্রতিদিন গোসল বা গা ধোয়া ভালো। চামড়ার ভাঁজগুলো ভালো করে মুছে শুকান।\n- **বাইরে জুতা বা স্যান্ডেল:** পা কাটা থেকে আর মাটির কৃমি থেকে বাঁচায়।\n- **কাশি-হাঁচি:** কনুইয়ের ভাঁজে কাশতে শেখান, তারপর হাত ধোয়া।\n- **নিরাপদ পানি:** ফোটানো, ছাঁকা বা নিরাপদ উৎসের পানি খাওয়ান, জমানো পানি ঢেকে রাখুন।\n- **টয়লেট:** স্যানিটারি ল্যাট্রিন বা টয়লেট ব্যবহার, তারপর হাত ধোয়া।\n- **দাঁত:** দিনে দুইবার ব্রাশ।\n\nশিশুর কৃমিনাশক ওষুধ লাগবে কি না, কখন লাগবে — স্বাস্থ্যকর্মীর কাছে জেনে নিন।\n\n## কখন স্বাস্থ্যকর্মীর কাছে যাবেন\n\nপায়খানায় রক্ত গেলে, পানিশূন্যতার লক্ষণ থাকলে (খুব পিপাসা বা পান করতেই না পারা, চোখ বসে যাওয়া, প্রস্রাব খুব কম, অস্বাভাবিক ঘুমঘুম ভাব), শ্বাস দ্রুত বা কষ্টের হলে, বা জ্বর না কমলে দেরি না করে সাহায্য নিন। পাতলা পায়খানা হলে স্বাস্থ্যকর্মীর পরামর্শমতো খাবার স্যালাইন (ORS) দিন আর খাওয়ানো চালিয়ে যান।"}'::jsonb, '{}'::jsonb, 4, 730, 1461, '{}'::text[], 'any', ARRAY['handwashing', 'soap', 'hygiene', 'diarrhoea', 'nails', 'bath', 'cough', 'germs']::text[], false, 'in_review'::lp_review_status, 5014),
  ('ec-teeth-and-sugar', 'article', 'scientific', 'shared', 'important', 'guideline', '🦷', '{"en":"Healthy teeth: brushing, fluoride and sugar","bn":"সুস্থ দাঁত: ব্রাশ, ফ্লোরাইড আর চিনি"}'::jsonb, '{"en":"Brush twice a day with fluoride toothpaste: a smear the size of a rice grain until three, then a pea-sized amount. Keep sweets and sugary drinks rare and with meals.","bn":"দিনে দুইবার ফ্লোরাইডযুক্ত টুথপেস্ট দিয়ে ব্রাশ করান: তিন বছর পর্যন্ত চালের দানার সমান সামান্য একটু, তারপর মটরদানার সমান। মিষ্টি আর চিনিযুক্ত পানীয় কম দিন, আর দিলে খাবারের সাথে দিন।"}'::jsonb, '{"en":"Baby teeth matter. They help children chew, speak clearly and smile with confidence, and they hold space for the adult teeth. Tooth decay is very common in young children, painful, and largely preventable.\n\n## Brushing, the simple way\n\n- **Twice a day:** in the morning, and last thing at night before sleep.\n- **Fluoride toothpaste:** a family toothpaste that contains fluoride protects teeth from decay.\n- **How much:** for children under three, a thin smear about the size of a grain of rice. From three, a pea-sized amount.\n- **Spit, don''t rinse:** teach your child to spit out the extra paste. A big rinse with water washes the fluoride away.\n- **An adult brushes:** let your child have a go, then brush properly yourself. Most children need an adult''s help until around seven or eight.\n- **A soft, small toothbrush,** replaced when the bristles spread out.\n\nTry sitting or standing behind your child, tilting their head gently back, and brushing in small circles on every surface, including along the gums. Make it part of the bedtime routine, with a song or counting.\n\n## Sugar is the main cause of decay\n\nThe World Health Organization links tooth decay to frequent sugar. It is not just how much sugar, but how often teeth are bathed in it.\n\n- Keep sweet foods, mishti, biscuits, chocolates and lozenges for special times, and give them with a meal rather than between meals.\n- Avoid soft drinks, packaged juice and sweetened tea for young children. Water and plain milk are the best drinks.\n- Do not let your child sleep with a bottle of milk or sweet drink, or sip sweet drinks all day.\n- Choose tooth-friendly snacks: fruit, muri, boiled egg, chira with yoghurt, cucumber.\n- Don''t use sweets as a reward or to stop crying.\n\nGrandparents and relatives often bring sweets as a sign of love. Kindly suggest fruit or a small toy, or keep the sweets for after a meal.\n\n## Look for early signs\n\nOnce a month, lift your child''s lip and look at the teeth. Early decay may look like white chalky lines near the gums, then brown or black spots or holes.\n\n## When to see a dentist or health worker\n\nTake your child to a dentist or health worker if you see spots, holes or broken teeth, if your child has toothache, swelling of the gum or face, bad breath that does not go away, or pain when eating sweet, hot or cold food. Swelling of the face with fever needs care the same day. If you can, take your child for a dental check-up even without problems, so the first visit is a calm one.","bn":"দুধদাঁতেরও গুরুত্ব আছে। এগুলো দিয়ে শিশু চিবায়, স্পষ্ট কথা বলে, আত্মবিশ্বাস নিয়ে হাসে — আর স্থায়ী দাঁতের জন্য জায়গা ধরে রাখে। ছোট শিশুদের দাঁতে পোকা বা ক্ষয় (tooth decay) খুব সাধারণ, কষ্টকর — আর বেশিরভাগই প্রতিরোধ করা যায়।\n\n## সহজভাবে ব্রাশ করা\n\n- **দিনে দুইবার:** সকালে, আর রাতে ঘুমানোর ঠিক আগে।\n- **ফ্লোরাইডযুক্ত টুথপেস্ট:** ফ্লোরাইড আছে এমন সাধারণ পারিবারিক টুথপেস্ট দাঁতকে ক্ষয় থেকে রক্ষা করে।\n- **কতটুকু:** তিন বছরের কম শিশুর জন্য চালের দানার সমান পাতলা একটু প্রলেপ। তিন বছর থেকে মটরদানার সমান।\n- **থুতু ফেলবে, কুলি নয়:** বাড়তি পেস্ট থুতু করে ফেলতে শেখান। বেশি পানি দিয়ে কুলি করলে ফ্লোরাইড ধুয়ে চলে যায়।\n- **বড়রা ব্রাশ করে দেবেন:** শিশুকে একবার নিজে চেষ্টা করতে দিন, তারপর নিজে ভালো করে করে দিন। বেশিরভাগ শিশুর সাত-আট বছর পর্যন্ত বড়দের সাহায্য লাগে।\n- **নরম, ছোট ব্রাশ,** লোম ছড়িয়ে গেলে বদলে দিন।\n\nশিশুর পেছনে বসে বা দাঁড়িয়ে মাথাটা আলতো করে একটু পেছনে হেলিয়ে নিন, তারপর মাড়ির ধারসহ দাঁতের প্রতিটি দিকে ছোট ছোট গোল করে ব্রাশ করুন। গান গেয়ে বা গুনে গুনে এটাকে ঘুমের রুটিনের অংশ বানান।\n\n## দাঁতের ক্ষয়ের মূল কারণ চিনি\n\nবিশ্ব স্বাস্থ্য সংস্থা (WHO) দাঁতের ক্ষয়কে ঘনঘন চিনি খাওয়ার সাথে যুক্ত করে। শুধু কতটা চিনি নয় — দাঁত কতবার চিনিতে ভেজে, সেটাও জরুরি।\n\n- মিষ্টি খাবার, মিষ্টি, বিস্কুট, চকলেট আর লজেন্স বিশেষ সময়ের জন্য রাখুন, আর দুই খাবারের মাঝে না দিয়ে খাবারের সাথে দিন।\n- ছোট শিশুকে কোমল পানীয়, প্যাকেটের জুস আর চিনি দেওয়া চা দেবেন না। পানি আর চিনি ছাড়া দুধই সবচেয়ে ভালো পানীয়।\n- দুধ বা মিষ্টি পানীয়ের ফিডার মুখে নিয়ে ঘুমাতে দেবেন না, বা সারাদিন চুমুক দিয়ে মিষ্টি পানীয় খেতে দেবেন না।\n- দাঁতের জন্য ভালো নাশতা দিন: ফল, মুড়ি, সেদ্ধ ডিম, দই-চিড়া, শসা।\n- পুরস্কার হিসেবে বা কান্না থামাতে মিষ্টি দেবেন না।\n\nদাদা-দাদি, নানা-নানি আর আত্মীয়রা প্রায়ই ভালোবেসে মিষ্টি নিয়ে আসেন। নরমভাবে ফল বা ছোট একটা খেলনার কথা বলুন, অথবা মিষ্টিটা খাবারের পরে দেওয়ার জন্য রেখে দিন।\n\n## শুরুর লক্ষণ খেয়াল করুন\n\nমাসে একবার শিশুর ঠোঁট উল্টে দাঁতগুলো দেখুন। ক্ষয়ের শুরুতে মাড়ির কাছে চকের মতো সাদা দাগ দেখা যেতে পারে, পরে বাদামি বা কালো দাগ বা গর্ত।\n\n## কখন দাঁতের ডাক্তার বা স্বাস্থ্যকর্মীর কাছে যাবেন\n\nদাঁতে দাগ, গর্ত বা ভাঙা দেখলে, দাঁতে ব্যথা, মাড়ি বা মুখ ফুলে গেলে, মুখে দুর্গন্ধ না সারলে, বা মিষ্টি, গরম বা ঠান্ডা খেলে ব্যথা হলে দাঁতের ডাক্তার বা স্বাস্থ্যকর্মীকে দেখান। জ্বরসহ মুখ ফুলে গেলে সেদিনই চিকিৎসা নিন। সম্ভব হলে সমস্যা ছাড়াও একবার দাঁতের চেকআপ করান, যাতে প্রথম সাক্ষাৎটা শান্তভাবে হয়।"}'::jsonb, '{}'::jsonb, 4, 730, 1461, '{}'::text[], 'any', ARRAY['teeth', 'brushing', 'fluoride toothpaste', 'tooth decay', 'sugar', 'sweets', 'dentist']::text[], false, 'in_review'::lp_review_status, 5015),
  ('ec-home-and-road-safety', 'article', 'scientific', 'family', 'important', 'guideline', '🛡️', '{"en":"Keeping your child safe: water, fire, poisons, falls and roads","bn":"শিশুকে নিরাপদ রাখা: পানি, আগুন, বিষ, পড়ে যাওয়া আর রাস্তা"}'::jsonb, '{"en":"Two- to four-year-olds are fast, curious and fearless. Most serious injuries happen at or near home and can be prevented with barriers, safe storage and an adult always watching near water.","bn":"দুই থেকে চার বছরের শিশু দ্রুত, কৌতূহলী আর ভয়হীন। বেশিরভাগ গুরুতর দুর্ঘটনা ঘটে বাড়িতে বা বাড়ির কাছে — বেড়া, নিরাপদে জিনিস রাখা আর পানির কাছে সবসময় একজন বড় মানুষের নজর দিয়ে এগুলো ঠেকানো যায়।"}'::jsonb, '{"en":"At this age children can run, climb and open things, but cannot yet understand danger. The World Health Organization''s work on child injury shows that most serious injuries in young children can be prevented. Rules alone are not enough at this age; the safest homes make dangers hard to reach.\n\n## Water: the biggest danger\n\nDrowning is one of the leading causes of death for young children in Bangladesh. It often happens close to home, in a pond, ditch, bucket or water tank, within minutes, and silently, while adults are busy with daily work.\n\n- Never leave your child alone near water, not even for a minute. Name one adult who is watching.\n- Fence ponds and ditches near the house, or put a barrier or gate across the doorway.\n- Empty buckets and tubs after use, and cover water drums, tanks and wells.\n- Use a safe play area or a playpen while you cook or wash, or ask another adult to watch.\n- In the rainy season and floods, keep extra watch, as water comes closer.\n- When your child is older, around school age, find a safe swimming programme with trained teachers.\n\n## Burns and fire\n\n- Keep your child out of the kitchen while you cook, or behind a barrier. Cook on a raised stove if you can, not on the floor.\n- Turn pot handles inward. Keep hot rice water (phyan), tea, dal and oil out of reach.\n- Keep kerosene stoves, lamps, candles, matches, lighters and mosquito coils high and away from cloth.\n- Keep irons and their cords out of reach. Cover electric sockets.\n\n**First aid for burns:** cool the burn under cool running water for at least 20 minutes, remove tight clothes or bangles nearby (not anything stuck), and cover loosely with clean cloth. Do not put toothpaste, oil, ghee, egg, turmeric or ice on a burn. Go to a health facility for any burn bigger than your child''s palm, any burn on the face, hands, feet or private parts, any blisters, or any electrical burn.\n\n## Medicines and chemicals\n\n- Store all medicines, including iron tablets and vitamins, up high in a closed box or cupboard.\n- Keep kerosene, phenyl, toilet cleaner, bleach, insect spray and rat poison in their original containers, locked or up high. Never put kerosene or chemicals in a water or soft drink bottle.\n- Keep button batteries and small magnets away from children.\n\nIf your child may have swallowed something harmful, do not make them vomit. Go to the nearest hospital at once, or call 999, and take the bottle or packet with you.\n\n## Falls\n\n- Fit grills or bars on windows and balconies, and keep beds, chairs and boxes away from them.\n- Do not let young children go on a roof (chhad) alone, especially one without a wall around it.\n- Block stairs with a gate, and keep stairs free of clutter.\n- Fix heavy furniture and TVs so they cannot tip over.\n\n## Roads and vehicles\n\n- Hold your child''s hand near roads, every time. Young children cannot judge speed and are hard for drivers to see.\n- Do not let children play near the road or where vehicles reverse.\n- In a car, use a child car seat in the back. In a rickshaw or CNG, keep your child seated between adults and held firmly, never at the edge.\n- Try not to carry young children on motorbikes. If it cannot be avoided, the child needs a properly fitting child helmet.\n\n## Everyone has a role\n\nAgree as a family who watches the child at busy times, especially mornings and cooking time. Fathers can fix grills, fences and high shelves. Grandparents and older siblings can help watch, but a small child should not be left in the sole care of another young child near water or fire.","bn":"এই বয়সে শিশু দৌড়াতে, বেয়ে উঠতে আর জিনিস খুলতে পারে, কিন্তু বিপদ বোঝে না। শিশুর দুর্ঘটনা নিয়ে বিশ্ব স্বাস্থ্য সংস্থার (WHO) কাজ দেখায়, ছোট শিশুদের বেশিরভাগ গুরুতর দুর্ঘটনা প্রতিরোধযোগ্য। এই বয়সে শুধু নিয়ম শিখিয়ে লাভ কম; সবচেয়ে নিরাপদ ঘর হলো যেখানে বিপদের নাগাল পাওয়াই কঠিন।\n\n## পানি: সবচেয়ে বড় বিপদ\n\nবাংলাদেশে ছোট শিশুদের মৃত্যুর প্রধান কারণগুলোর একটা পানিতে ডোবা। এটা প্রায়ই ঘটে বাড়ির খুব কাছে — পুকুর, ডোবা, বালতি বা পানির ট্যাংকে — কয়েক মিনিটের মধ্যে, নিঃশব্দে, যখন বড়রা সংসারের কাজে ব্যস্ত।\n\n- শিশুকে কখনো পানির কাছে একা রাখবেন না — এক মিনিটের জন্যও না। কে নজর রাখছেন, একজনকে নির্দিষ্ট করে দিন।\n- বাড়ির কাছের পুকুর-ডোবায় বেড়া দিন, বা দরজায় বাধা বা গেট লাগান।\n- ব্যবহারের পর বালতি আর গামলা খালি করুন; পানির ড্রাম, ট্যাংক আর কুয়া ঢেকে রাখুন।\n- রান্না বা কাপড় ধোয়ার সময় শিশুকে নিরাপদ ঘেরা জায়গায় রাখুন, বা অন্য একজন বড় মানুষকে দেখতে বলুন।\n- বর্ষা আর বন্যার সময় পানি কাছে চলে আসে — তখন বাড়তি নজর রাখুন।\n- শিশু আরেকটু বড় হলে, স্কুলে যাওয়ার বয়সের দিকে, প্রশিক্ষিত শিক্ষকের কাছে নিরাপদভাবে সাঁতার শেখান।\n\n## পোড়া আর আগুন\n\n- রান্নার সময় শিশুকে রান্নাঘরের বাইরে রাখুন, বা বাধার ওপাশে। পারলে মেঝেতে না রেখে উঁচু চুলায় রান্না করুন।\n- হাঁড়ির হাতল ভেতরের দিকে ঘুরিয়ে রাখুন। গরম ভাতের মাড় (ফ্যান), চা, ডাল আর তেল নাগালের বাইরে রাখুন।\n- কেরোসিনের চুলা, কুপি-হারিকেন, মোমবাতি, ম্যাচ, লাইটার আর মশার কয়েল উঁচুতে, কাপড় থেকে দূরে রাখুন।\n- ইস্ত্রি আর তার নাগালের বাইরে রাখুন। বিদ্যুতের সকেট ঢেকে দিন।\n\n**পোড়ার প্রাথমিক চিকিৎসা:** পোড়া জায়গাটা অন্তত ২০ মিনিট কলের ঠান্ডা (বরফ-ঠান্ডা নয়) পানির নিচে রাখুন, আশেপাশের আঁটসাঁট কাপড় বা চুড়ি খুলে দিন (চামড়ায় লেগে থাকা কিছু টেনে খুলবেন না), তারপর পরিষ্কার কাপড় দিয়ে আলগা করে ঢেকে দিন। পোড়ায় টুথপেস্ট, তেল, ঘি, ডিম, হলুদ বা বরফ দেবেন না। শিশুর হাতের তালুর চেয়ে বড় পোড়া, মুখ, হাত, পা বা গোপনাঙ্গে পোড়া, ফোসকা পড়া, বা বিদ্যুতে পোড়া হলে স্বাস্থ্যকেন্দ্রে নিয়ে যান।\n\n## ওষুধ আর রাসায়নিক\n\n- আয়রন ট্যাবলেট আর ভিটামিনসহ সব ওষুধ উঁচুতে, বন্ধ বাক্স বা আলমারিতে রাখুন।\n- কেরোসিন, ফিনাইল, টয়লেট ক্লিনার, ব্লিচ, কীটনাশক স্প্রে আর ইঁদুরের বিষ নিজের বোতলেই, তালাবদ্ধ করে বা উঁচুতে রাখুন। কেরোসিন বা রাসায়নিক কখনো পানির বা কোমল পানীয়ের বোতলে রাখবেন না।\n- বোতাম ব্যাটারি আর ছোট চুম্বক শিশুর কাছ থেকে দূরে রাখুন।\n\nশিশু ক্ষতিকর কিছু গিলে ফেলেছে মনে হলে বমি করাবেন না। সাথে সাথে কাছের হাসপাতালে যান বা ৯৯৯-এ ফোন করুন, আর বোতল বা প্যাকেটটা সাথে নিন।\n\n## পড়ে যাওয়া\n\n- জানালা আর বারান্দায় গ্রিল লাগান, আর খাট, চেয়ার, বাক্স সেখান থেকে দূরে রাখুন।\n- ছোট শিশুকে একা ছাদে যেতে দেবেন না, বিশেষ করে রেলিং বা দেয়ালহীন ছাদে।\n- সিঁড়ির মুখে গেট দিন, সিঁড়িতে জিনিসপত্র রাখবেন না।\n- ভারী আসবাব আর টিভি এমনভাবে আটকে দিন যাতে উল্টে না পড়ে।\n\n## রাস্তা আর যানবাহন\n\n- রাস্তার কাছে প্রতিবার শিশুর হাত ধরে রাখুন। ছোট শিশু গাড়ির গতি বোঝে না, আর চালকেরাও তাদের দেখতে পান না।\n- রাস্তার পাশে বা যেখানে গাড়ি পেছনে যায়, সেখানে খেলতে দেবেন না।\n- গাড়িতে পেছনের সিটে শিশুদের কার সিট ব্যবহার করুন। রিকশা বা সিএনজিতে শিশুকে দুজন বড় মানুষের মাঝে বসিয়ে শক্ত করে ধরে রাখুন — কখনো কিনারে নয়।\n- ছোট শিশুকে মোটরসাইকেলে না নেওয়ার চেষ্টা করুন। একেবারে এড়ানো না গেলে শিশুর মাপমতো হেলমেট লাগবে।\n\n## সবারই ভূমিকা আছে\n\nব্যস্ত সময়ে — বিশেষ করে সকালে আর রান্নার সময় — কে শিশুকে দেখবেন, পরিবারে ঠিক করে নিন। বাবা গ্রিল, বেড়া আর উঁচু তাক লাগাতে পারেন। দাদা-দাদি, নানা-নানি আর বড় ভাই-বোন নজর রাখতে সাহায্য করতে পারে, কিন্তু পানি বা আগুনের কাছে ছোট শিশুকে কখনো শুধু আরেকটা ছোট শিশুর দায়িত্বে রাখবেন না।"}'::jsonb, '{}'::jsonb, 6, 730, 1461, '{}'::text[], 'any', ARRAY['safety', 'drowning', 'pond', 'burns', 'kerosene', 'poisoning', 'medicines', 'falls', 'roof', 'road safety']::text[], false, 'in_review'::lp_review_status, 5016),
  ('ec-new-baby-sibling', 'article', 'scientific', 'family', 'educational', 'consensus', '👶', '{"en":"A new baby in the family: preparing your older child","bn":"পরিবারে নতুন শিশু: বড় সন্তানকে প্রস্তুত করা"}'::jsonb, '{"en":"A new brother or sister is a big change for a two- to four-year-old. Prepare them gently, keep routines steady, give them special time, and expect some jealousy and going backwards for a while.","bn":"নতুন ভাই বা বোন দুই থেকে চার বছরের শিশুর জন্য বড় পরিবর্তন। নরমভাবে প্রস্তুত করুন, রুটিন ঠিক রাখুন, আলাদা সময় দিন — আর কিছুদিন হিংসা বা আগের অভ্যাসে ফিরে যাওয়া আশা করেই রাখুন।"}'::jsonb, '{"en":"For a young child, a new baby can feel like a great gift and a great loss at the same time. Suddenly Ammu is tired and busy, visitors crowd around the baby, and everyone says ''Be quiet!'' Feelings of jealousy, sadness or anger are normal, and they usually ease with time and care.\n\n## During the pregnancy\n\n- Tell your child a few months before the birth, in simple words: ''A baby is growing in Ammu''s tummy. It will come when the weather is cold.''\n- Read picture books about new babies, and look at your child''s own baby photos together.\n- Let them help get ready: choosing a small cloth or toy for the baby.\n- Make big changes early, or wait until later: moving to a new bed, starting toilet training or pre-school are best not done right around the birth.\n- Plan who will care for your older child during the birth, and introduce that person if needed.\n\n## When the baby arrives\n\n1. When your older child first meets the baby, let the baby be in someone else''s arms so Ammu''s arms are free for a hug.\n2. Ask visitors to greet the older child first. Keep a small gift ready for them too.\n3. Let them help in small ways: fetching a nappy, singing to the baby, choosing a cloth. Praise them: ''You are such a kind big brother.''\n4. Keep their routine as normal as possible: meals, sleep, play, the bedtime story.\n5. Give at least a few minutes of special one-to-one time every day with each parent, without the baby.\n\n## Expect some going backwards\n\nMany children start wanting a bottle again, speaking like a baby, wanting to be carried, or having toilet accidents. This is a way of asking, ''Do you still love me like a baby?'' Respond calmly and warmly, without scolding. It usually passes within weeks to a few months.\n\n## Name the feelings\n\nIt''s fine to say: ''Sometimes it is hard having a baby in the house. Ammu has to hold her so much. You can always tell me how you feel.'' Let them say they don''t like the baby without punishment. Then guide the action: we are gentle with the baby.\n\n## Safety\n\nYoung children can hurt a baby without meaning to, by hugging too hard, poking, or trying to feed or lift them. Never leave a toddler alone with a baby, even for a minute.\n\n## The father''s big role\n\nWhile the mother is recovering and breastfeeding, the father can become the older child''s main companion: taking them out, doing bath and bedtime, playing, and reading stories. This protects the older child''s sense of being loved, and gives the mother rest. Grandparents and relatives can help in the same way.\n\n## When to seek help\n\nTalk to a health worker if your child''s distress is very strong or lasts many months, if they repeatedly try to hurt the baby, or if they stop eating, sleeping or playing well.","bn":"ছোট শিশুর কাছে নতুন ভাই-বোন একই সাথে বড় উপহার আর বড় হারানোর মতো লাগতে পারে। হঠাৎ আম্মু ক্লান্ত আর ব্যস্ত, মেহমানেরা শুধু ছোটটাকে ঘিরে থাকে, সবাই বলে “চুপ, বাবু ঘুমাচ্ছে!” হিংসা, মন খারাপ বা রাগ — এগুলো স্বাভাবিক, আর সময় ও যত্নে সাধারণত কমে যায়।\n\n## গর্ভাবস্থার সময়ে\n\n- জন্মের কয়েক মাস আগে সহজ ভাষায় বলুন: “আম্মুর পেটে একটা ছোট্ট বাবু বড় হচ্ছে। শীত এলে বাবু আসবে।”\n- নতুন শিশু নিয়ে ছবির বই পড়ুন, আর একসাথে ওর নিজের ছোটবেলার ছবি দেখুন।\n- প্রস্তুতিতে সাথে রাখুন — বাবুর জন্য ছোট একটা কাপড় বা খেলনা বেছে দিতে দিন।\n- বড় পরিবর্তনগুলো আগেই সেরে ফেলুন, বা পরে করুন: নতুন বিছানায় সরানো, টয়লেট শেখানো বা প্রি-স্কুল শুরু — জন্মের ঠিক আশেপাশে না করাই ভালো।\n- প্রসবের সময় বড় সন্তানকে কে দেখবেন, আগে থেকে ঠিক করুন, দরকার হলে তাঁর সাথে পরিচয় করিয়ে দিন।\n\n## বাবু আসার পর\n\n১. বড় সন্তান প্রথমবার বাবুকে দেখার সময় বাবু অন্য কারও কোলে থাকুক, যাতে আম্মুর হাত খালি থাকে জড়িয়ে ধরার জন্য।\n২. মেহমানদের অনুরোধ করুন আগে বড়টার সাথে কথা বলতে। ওর জন্যও ছোট একটা উপহার রেখে দিন।\n৩. ছোট ছোট কাজে সাহায্য করতে দিন — ডায়াপার এনে দেওয়া, বাবুকে গান শোনানো, কাপড় বেছে দেওয়া। প্রশংসা করুন: “তুমি কী দারুণ বড় ভাইয়া!”\n৪. ওর রুটিন যতটা পারেন স্বাভাবিক রাখুন — খাওয়া, ঘুম, খেলা, ঘুমের আগের গল্প।\n৫. প্রতিদিন বাবা-মা দুজনেই অন্তত কয়েক মিনিট বাবুকে ছাড়া শুধু ওর সাথে আলাদা সময় কাটান।\n\n## কিছুটা পিছিয়ে যাওয়া স্বাভাবিক\n\nঅনেক শিশু আবার ফিডার চায়, বাবুর মতো করে কথা বলে, কোলে উঠতে চায়, বা কাপড়ে প্রস্রাব করে ফেলে। এটা আসলে জিজ্ঞেস করার একটা উপায়: “আমাকে কি এখনো বাবুর মতো ভালোবাসো?” বকা না দিয়ে শান্ত আর উষ্ণভাবে সাড়া দিন। সাধারণত কয়েক সপ্তাহ থেকে কয়েক মাসে এটা কেটে যায়।\n\n## অনুভূতির নাম দিন\n\nবলতে পারেন: “ঘরে ছোট বাবু থাকলে মাঝে মাঝে কঠিন লাগে, তাই না? আম্মুকে ওকে অনেক কোলে রাখতে হয়। তোমার কেমন লাগে, আমাকে সবসময় বলতে পারো।” “বাবুকে ভালো লাগে না” বললে শাস্তি দেবেন না। তারপর কাজটা ঠিক করে দিন: বাবুর সাথে আমরা আলতো করে থাকি।\n\n## নিরাপত্তা\n\nছোট শিশু না বুঝেই বাবুকে ব্যথা দিতে পারে — জোরে জড়িয়ে ধরে, খোঁচা দিয়ে, বা খাওয়াতে বা কোলে তুলতে গিয়ে। এক মিনিটের জন্যও ছোট শিশুকে বাবুর সাথে একা রাখবেন না।\n\n## বাবার বড় ভূমিকা\n\nমা যখন সেরে উঠছেন আর বুকের দুধ খাওয়াচ্ছেন, তখন বাবা বড় সন্তানের প্রধান সাথি হয়ে উঠতে পারেন — বাইরে নিয়ে যাওয়া, গোসল আর ঘুম পাড়ানো, খেলা, গল্প পড়া। এতে বড় সন্তানের ভালোবাসা পাওয়ার অনুভূতি অটুট থাকে, মা-ও বিশ্রাম পান। দাদা-দাদি, নানা-নানি আর আত্মীয়রাও এভাবে সাহায্য করতে পারেন।\n\n## কখন সাহায্য নেবেন\n\nশিশুর কষ্ট খুব তীব্র হলে বা অনেক মাস ধরে চললে, বারবার বাবুকে আঘাত করার চেষ্টা করলে, বা খাওয়া, ঘুম বা খেলা ঠিকমতো না করলে স্বাস্থ্যকর্মীর সাথে কথা বলুন।"}'::jsonb, '{}'::jsonb, 5, 730, 1461, '{}'::text[], 'any', ARRAY['new baby', 'sibling', 'jealousy', 'big brother', 'big sister', 'regression', 'pregnancy']::text[], false, 'in_review'::lp_review_status, 5017),
  ('ec-father-playmate-teacher', 'article', 'scientific', 'father', 'educational', 'consensus', '👨‍👧', '{"en":"The father as playmate and teacher","bn":"বাবা যখন খেলার সাথি আর শিক্ষক"}'::jsonb, '{"en":"Fathers are not helpers; they are parents. Daily play, talk and care from Abbu builds a child''s confidence, language and sense of safety, even when time is short.","bn":"বাবা ‘সাহায্যকারী’ নন — তিনিও বাবা-মায়েরই একজন। আব্বুর সাথে প্রতিদিনের খেলা, কথা আর যত্ন শিশুর আত্মবিশ্বাস, ভাষা আর নিরাপত্তাবোধ গড়ে — সময় কম হলেও।"}'::jsonb, '{"en":"In many Bangladeshi families, fathers work long hours, and caring for young children is seen as the mother''s job. But nurturing care, as the World Health Organization describes it, comes from all the important adults in a child''s life. Children whose fathers are warmly involved gain a great deal, and so do fathers.\n\n## What fathers bring\n\nEvery father is different, but fathers often bring their own style: more physical play, new words from their work and world, and gentle challenges (''Can you climb one more step?''). This variety helps children grow confident, curious and able to handle a little risk safely.\n\n## Play every day\n\n- **Active play:** chasing, ball games, piggy-back rides, dancing. Keep it safe and stop when the child says stop.\n- **Rough-and-tumble:** gentle wrestling on a bed or mat teaches children to manage strength and excitement. Teach clear rules: no hitting faces, stop means stop.\n- **Pretend play:** be the customer, the patient or the passenger. It doesn''t need to be perfect.\n- **Outdoor time:** a walk to the shop, the field, the riverside or the park, naming birds, trees and vehicles.\n\n## Teach through daily life\n\n1. Count steps, oranges at the market, or cars on the road.\n2. Name colours and shapes: ''Find something red.''\n3. Let your child help with simple jobs: watering plants, carrying a light bag, fixing something together.\n4. Talk about your work in simple words: ''Today I drove a lot,'' ''Today I helped a customer.''\n5. Read a bedtime story or tell a story from your own childhood.\n\n## Care, not just play\n\nFeeding, bathing, changing, comforting at night and taking the child to the doctor are all fathering too. Doing these jobs builds trust: your child learns that Abbu is someone who comforts as well as someone who plays. It also gives the mother real rest.\n\n## When time is short\n\n- Ten minutes of full attention a day, phone away, matters more than an hour half-distracted.\n- Take over one daily routine, such as morning wash or bedtime, as ''your'' job.\n- On weekends or days off, plan one special outing or activity.\n\n## Fathers working away or abroad\n\nMany Bangladeshi fathers work in another city or country. Regular video calls at a set time, reading a story on video, sending voice messages, and asking about the child''s day all keep the bond alive. When home, spend unhurried time together.\n\n## Discipline as a father\n\nAvoid being ''the one who punishes''. A father who stays calm, holds limits kindly and repairs after anger teaches his child far more than one who is feared.","bn":"আমাদের অনেক পরিবারে বাবারা লম্বা সময় কাজ করেন, আর ছোট শিশুর দেখাশোনাকে মায়ের কাজ ধরা হয়। কিন্তু বিশ্ব স্বাস্থ্য সংস্থার (WHO) ভাষায় ‘যত্নময় পরিচর্যা’ আসে শিশুর জীবনের সব গুরুত্বপূর্ণ বড় মানুষের কাছ থেকে। যে শিশুর বাবা আন্তরিকভাবে পাশে থাকেন, সে অনেক কিছু পায় — আর বাবারাও পান।\n\n## বাবা কী নিয়ে আসেন\n\nপ্রত্যেক বাবা আলাদা, তবে বাবারা প্রায়ই নিজের একটা ধরন নিয়ে আসেন — বেশি দৌড়ঝাঁপের খেলা, নিজের কাজ আর জগৎ থেকে নতুন শব্দ, আর ছোট ছোট চ্যালেঞ্জ (“আরেক ধাপ উঠতে পারবে?”)। এই বৈচিত্র্য শিশুকে আত্মবিশ্বাসী, কৌতূহলী আর নিরাপদভাবে একটু ঝুঁকি সামলাতে সক্ষম করে তোলে।\n\n## প্রতিদিন খেলা\n\n- **দৌড়ঝাঁপের খেলা:** ছোঁয়াছুঁয়ি, বল খেলা, পিঠে চড়ানো, নাচ। নিরাপদ রাখুন, আর শিশু “থামো” বললে থামুন।\n- **হুটোপুটি:** খাট বা মাদুরে আলতো কুস্তি শিশুকে শক্তি আর উত্তেজনা সামলাতে শেখায়। পরিষ্কার নিয়ম শেখান: মুখে মারা নয়, “থামো” মানে থামা।\n- **ভান-খেলা:** খদ্দের, রোগী বা যাত্রী হোন। নিখুঁত হওয়ার দরকার নেই।\n- **বাইরে সময়:** দোকানে, মাঠে, নদীর ধারে বা পার্কে হাঁটা — পাখি, গাছ আর গাড়ির নাম বলতে বলতে।\n\n## রোজকার জীবন দিয়ে শেখানো\n\n১. সিঁড়ির ধাপ, বাজারের কমলা বা রাস্তার গাড়ি গুনুন।\n২. রং আর আকারের নাম বলুন: “লাল কিছু খুঁজে বের করো তো।”\n৩. সহজ কাজে সাথে নিন — গাছে পানি দেওয়া, হালকা ব্যাগ বয়ে আনা, একসাথে কিছু সারানো।\n৪. নিজের কাজের কথা সহজ করে বলুন: “আজ অনেক গাড়ি চালিয়েছি,” “আজ একজন ক্রেতাকে সাহায্য করেছি।”\n৫. ঘুমের আগে একটা গল্প পড়ুন, বা নিজের ছোটবেলার গল্প বলুন।\n\n## শুধু খেলা নয়, যত্নও\n\nখাওয়ানো, গোসল করানো, জামা বদলানো, রাতে শান্ত করা, ডাক্তারের কাছে নেওয়া — এসবও বাবার কাজ। এগুলো করলে শিশু শেখে, আব্বু শুধু খেলার মানুষ নন, কষ্টে সান্ত্বনা দেওয়ার মানুষও। এতে মা-ও সত্যিকারের বিশ্রাম পান।\n\n## সময় যখন কম\n\n- ফোন দূরে রেখে দিনে ১০ মিনিটের পূর্ণ মনোযোগ — আধা-মনোযোগের এক ঘণ্টার চেয়ে বেশি মূল্যবান।\n- একটা রোজকার রুটিন, যেমন সকালে হাতমুখ ধোয়ানো বা রাতে ঘুম পাড়ানো, ‘নিজের’ দায়িত্ব হিসেবে নিন।\n- ছুটির দিনে একটা বিশেষ বেড়ানো বা কাজের পরিকল্পনা করুন।\n\n## যে বাবারা দূরে বা বিদেশে কাজ করেন\n\nআমাদের অনেক বাবা অন্য শহরে বা বিদেশে কাজ করেন। নির্দিষ্ট সময়ে নিয়মিত ভিডিও কল, ভিডিওতে গল্প পড়ে শোনানো, ভয়েস মেসেজ পাঠানো আর শিশুর দিনটা কেমন গেল জিজ্ঞেস করা — এগুলো সম্পর্ক জীবন্ত রাখে। বাড়ি এলে তাড়াহুড়া ছাড়া একসাথে সময় কাটান।\n\n## বাবা হিসেবে শাসন\n\n‘যিনি শাস্তি দেন’ — এই ভূমিকা এড়িয়ে চলুন। যে বাবা শান্ত থাকেন, নরমভাবে সীমা রাখেন আর রাগের পরে সম্পর্ক জোড়া লাগান, তিনি ভয় পাওয়ানো বাবার চেয়ে সন্তানকে অনেক বেশি শেখান।"}'::jsonb, '{}'::jsonb, 4, 730, 1461, '{}'::text[], 'any', ARRAY['father', 'abbu', 'play', 'rough and tumble', 'teaching', 'working father', 'father abroad']::text[], false, 'in_review'::lp_review_status, 5018),
  ('ec-story-mitus-mangoes', 'story', 'general', 'child', 'educational', NULL, '🥭', '{"en":"Mitu and the Mango Basket","bn":"মিতু আর আমের ঝুড়ি"}'::jsonb, '{"en":"A read-aloud story about Mitu, her cousin Rafi and a basket of sweet mangoes at Nanu''s house, and how sharing made the afternoon better.","bn":"নানুবাড়িতে মিতু, ওর মামাতো ভাই রাফি আর এক ঝুড়ি মিষ্টি আমের গল্প — ভাগ করে খেলে বিকেলটা কীভাবে আরও মজার হলো।"}'::jsonb, '{"en":"It was summer, and Mitu was at Nanu''s house in the village.\n\nThe sun was hot. The chickens were sleeping in the shade. And under the big mango tree, Nanu put down a basket full of yellow mangoes.\n\n''Mangoes!'' shouted Mitu. She ran to the basket and put her arms around it. ''These are all mine!''\n\nHer cousin Rafi came running too. He was small, smaller than Mitu. He looked at the mangoes. He looked at Mitu. His lip went wobbly.\n\n''I want a mango too,'' said Rafi quietly.\n\nMitu held the basket tighter. Her tummy said, keep them all. But then she looked at Rafi''s face. His eyes were wet, like when Mitu fell down and scraped her knee.\n\n''Rafi is sad,'' Mitu thought. ''I don''t like being sad.''\n\nNanu sat down on the mat. ''Mitu, there are many mangoes,'' she said gently. ''What could we do?''\n\nMitu thought and thought. Then she picked out the biggest, roundest mango. She held it out to Rafi.\n\n''This one is for you,'' she said.\n\nRafi''s face opened up like a flower. ''Thank you, Mitu Apu!''\n\nNanu washed the mangoes at the tubewell and cut them into pieces. Mitu and Rafi sat side by side. They ate mango until juice ran down their chins and onto their elbows. Rafi laughed. Mitu laughed. Even Nanu laughed.\n\n''Look,'' said Mitu. ''There are still mangoes left!''\n\n''Shall we take some to Nana and the neighbours?'' asked Nanu.\n\nSo they did. Everyone said thank you, and everyone smiled.\n\nThat night, as Mitu lay under the mosquito net, Nanu stroked her hair.\n\n''Mangoes are sweet,'' Mitu whispered. ''But sharing mangoes is sweeter.''\n\nAnd she fell fast asleep.\n\n**Talk together:** How did Rafi feel when Mitu held all the mangoes? How did he feel when she gave him one? What do you like to share?","bn":"গরমের ছুটি। মিতু গেছে গ্রামে, নানুবাড়িতে।\n\nরোদ খুব কড়া। মুরগিগুলো ছায়ায় ঘুমাচ্ছে। আর বড় আমগাছটার নিচে নানু নামিয়ে রাখলেন এক ঝুড়ি হলুদ আম।\n\n“আম!” চিৎকার করে উঠল মিতু। দৌড়ে গিয়ে দুই হাতে ঝুড়িটা জড়িয়ে ধরল। “এগুলো সব আমার!”\n\nমামাতো ভাই রাফিও দৌড়ে এল। রাফি ছোট, মিতুর চেয়েও ছোট। সে আমগুলোর দিকে তাকাল। তারপর মিতুর দিকে। তার ঠোঁট কাঁপতে লাগল।\n\n“আমিও একটা আম খাব,” আস্তে করে বলল রাফি।\n\nমিতু ঝুড়িটা আরও শক্ত করে ধরল। মন বলছে, সবগুলো আমার কাছেই থাকুক। কিন্তু তারপর সে রাফির মুখের দিকে তাকাল। রাফির চোখ ছলছল করছে — ঠিক যেমন মিতু পড়ে গিয়ে হাঁটু ছিলে গেলে হয়।\n\nমিতু ভাবল, “রাফির মন খারাপ। মন খারাপ হলে তো আমারও ভালো লাগে না।”\n\nনানু মাদুরে বসলেন। নরম গলায় বললেন, “মিতু, আম তো অনেকগুলো। কী করা যায় বলো তো?”\n\nমিতু ভাবল, অনেকক্ষণ ভাবল। তারপর সবচেয়ে বড়, সবচেয়ে গোল আমটা বেছে রাফির দিকে বাড়িয়ে দিল।\n\n“এটা তোমার জন্য,” বলল মিতু।\n\nরাফির মুখটা ফুলের মতো ফুটে উঠল। “থ্যাংক ইউ, মিতু আপু!”\n\nনানু টিউবওয়েলে আমগুলো ধুয়ে টুকরো টুকরো করে কাটলেন। মিতু আর রাফি পাশাপাশি বসল। আম খেতে খেতে রস গড়িয়ে পড়ল থুতনি বেয়ে, কনুই পর্যন্ত। রাফি হাসল। মিতু হাসল। নানুও হেসে ফেললেন।\n\n“দেখো,” বলল মিতু, “এখনো আম বাকি আছে!”\n\n“চলো, কয়েকটা নানাভাই আর প্রতিবেশীদের দিয়ে আসি?” বললেন নানু।\n\nতারা তাই করল। সবাই ধন্যবাদ দিল, সবাই হাসল।\n\nরাতে মশারির নিচে শুয়ে মিতু, নানু তার চুলে হাত বুলিয়ে দিচ্ছেন।\n\nমিতু ফিসফিস করে বলল, “আম মিষ্টি। কিন্তু ভাগ করে খাওয়া আম আরও মিষ্টি।”\n\nতারপর সে গভীর ঘুমে তলিয়ে গেল।\n\n**একসাথে কথা বলুন:** মিতু যখন সব আম ধরে রেখেছিল, রাফির কেমন লেগেছিল? মিতু যখন একটা আম দিল, তখন কেমন লাগল? তুমি কী ভাগ করে নিতে ভালোবাসো?"}'::jsonb, '{}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['story', 'sharing', 'mango', 'cousin', 'village', 'bedtime story']::text[], false, 'in_review'::lp_review_status, 5019),
  ('ec-story-brave-at-doctor', 'story', 'general', 'child', 'educational', NULL, '🩺', '{"en":"Ayaan Visits the Doctor","bn":"আয়ান গেল ডাক্তারের কাছে"}'::jsonb, '{"en":"Ayaan has a cough and goes with Abbu to the health complex. A gentle story about feeling scared, holding a hand and being brave.","bn":"আয়ানের কাশি হয়েছে, তাই আব্বুর সাথে গেল স্বাস্থ্য কমপ্লেক্সে। ভয় পাওয়া, হাত ধরা আর সাহসী হওয়ার একটা নরম গল্প।"}'::jsonb, '{"en":"Ayaan had a cough. ''Khuk, khuk,'' went Ayaan, all morning long.\n\n''Let''s see the doctor,'' said Abbu. ''The doctor will listen to your chest and help you feel better.''\n\nAyaan''s tummy felt fluttery, like a little bird was inside it. ''Will it hurt?'' he asked.\n\n''The doctor will look and listen,'' said Abbu. ''If something needs to be done, I will tell you before. And I will hold your hand the whole time.''\n\nThey took a rickshaw to the health complex. There were many people waiting. A baby was crying. A grandmother was fanning herself. Ayaan sat close to Abbu and counted the fans on the ceiling. One, two, three.\n\n''Ayaan!'' called a nurse. Ayaan''s tummy fluttered again.\n\nThe doctor was a kind lady with a white coat. ''Assalamu alaikum, Ayaan,'' she said. ''I''m Doctor Apa. Do you want to see my special listening tool?''\n\nShe showed him the stethoscope. It was cold and shiny. ''It helps me hear your heart,'' she said. ''Shall I listen to Abbu first?''\n\nShe listened to Abbu''s chest. Abbu smiled. Then Ayaan was ready.\n\nThe stethoscope felt cold. Ayaan squeezed Abbu''s hand. ''Take a big breath,'' said Doctor Apa, ''like blowing out a birthday candle.'' Ayaan breathed in, and blew out. In, and out.\n\n''Dhuk-dhuk, dhuk-dhuk,'' said Doctor Apa. ''You have a strong heart!''\n\nThen she looked in his mouth. ''Say aaaaah, like a big lion!'' Ayaan roared, ''AAAAAH!'' Everyone laughed.\n\n''You need lots of water and rest,'' said Doctor Apa. ''You were very brave today.''\n\n''But I was scared,'' said Ayaan.\n\n''Being brave doesn''t mean you are not scared,'' said Abbu. ''Brave means you are scared, and you hold a hand, and you breathe, and you do it anyway.''\n\nAt home, Ayaan made a stethoscope from a string and a bottle cap. He listened to his teddy''s chest.\n\n''Big breath, Teddy,'' he said. ''You are very brave.''\n\n**Talk together:** What made Ayaan feel scared? What helped him? What can you do when you feel scared?","bn":"আয়ানের কাশি হয়েছে। সারা সকাল আয়ান শুধু করছে, “খুক, খুক।”\n\n“চলো, ডাক্তারের কাছে যাই,” বললেন আব্বু। “ডাক্তার তোমার বুকের শব্দ শুনবেন, তোমাকে ভালো হতে সাহায্য করবেন।”\n\nআয়ানের পেটের ভেতর কেমন ফড়ফড় করতে লাগল, যেন একটা ছোট্ট পাখি ঢুকে বসে আছে। “ব্যথা লাগবে?” জিজ্ঞেস করল সে।\n\n“ডাক্তার দেখবেন আর শুনবেন,” বললেন আব্বু। “কিছু করার দরকার হলে আমি আগেই তোমাকে বলব। আর পুরোটা সময় আমি তোমার হাত ধরে থাকব।”\n\nতারা রিকশায় চড়ে গেল স্বাস্থ্য কমপ্লেক্সে। সেখানে অনেক মানুষ অপেক্ষা করছে। একটা বাবু কাঁদছে। একজন দাদু হাতপাখা দিয়ে বাতাস করছেন। আয়ান আব্বুর গা ঘেঁষে বসে ছাদের ফ্যানগুলো গুনল। এক, দুই, তিন।\n\n“আয়ান!” ডাকলেন একজন নার্স। আয়ানের পেটের ভেতর আবার ফড়ফড় করে উঠল।\n\nডাক্তার একজন সাদা অ্যাপ্রন পরা হাসিখুশি আপা। “আসসালামু আলাইকুম, আয়ান,” বললেন তিনি। “আমি ডাক্তার আপা। আমার বিশেষ শোনার যন্ত্রটা দেখবে?”\n\nতিনি আয়ানকে স্টেথোস্কোপটা দেখালেন। ঠান্ডা আর চকচকে। “এটা দিয়ে আমি তোমার হৃদয়ের শব্দ শুনি,” বললেন তিনি। “আগে আব্বুরটা শুনে দেখি?”\n\nতিনি আব্বুর বুকে কান পাতার যন্ত্রটা রাখলেন। আব্বু হাসলেন। এবার আয়ান তৈরি।\n\nস্টেথোস্কোপটা ঠান্ডা লাগল। আয়ান আব্বুর হাত শক্ত করে চেপে ধরল। “একটা বড় শ্বাস নাও,” বললেন ডাক্তার আপা, “জন্মদিনের মোমবাতি ফুঁ দিয়ে নেভানোর মতো।” আয়ান শ্বাস নিল, তারপর ফুঁ দিল। নিল, আর ছাড়ল।\n\n“ধুক-ধুক, ধুক-ধুক,” বললেন ডাক্তার আপা। “তোমার হৃদয়টা খুব শক্তিশালী!”\n\nতারপর তিনি মুখের ভেতর দেখলেন। “বড় সিংহের মতো বলো তো, আ-আ-আ!” আয়ান গর্জন করল, “আ-আ-আ-আ!” সবাই হেসে উঠল।\n\n“তোমাকে অনেক পানি খেতে হবে আর বিশ্রাম নিতে হবে,” বললেন ডাক্তার আপা। “আজ তুমি অনেক সাহসী ছিলে।”\n\n“কিন্তু আমি তো ভয় পেয়েছিলাম,” বলল আয়ান।\n\n“সাহসী মানে ভয় না পাওয়া নয়,” বললেন আব্বু। “সাহসী মানে ভয় লাগছে, তবু হাত ধরছ, শ্বাস নিচ্ছ, আর কাজটা করে ফেলছ।”\n\nবাসায় ফিরে আয়ান একটা সুতো আর বোতলের ছিপি দিয়ে স্টেথোস্কোপ বানাল। তারপর টেডির বুকের শব্দ শুনল।\n\n“বড় শ্বাস নাও, টেডি,” বলল সে। “তুমি খুব সাহসী।”\n\n**একসাথে কথা বলুন:** আয়ান কেন ভয় পেয়েছিল? কী তাকে সাহায্য করল? ভয় পেলে তুমি কী করতে পারো?"}'::jsonb, '{}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['story', 'doctor', 'brave', 'fear', 'check-up', 'hospital', 'bedtime story']::text[], false, 'in_review'::lp_review_status, 5020),
  ('ec-story-angry-words', 'story', 'general', 'child', 'educational', NULL, '🧱', '{"en":"Tuni''s Tall Tower","bn":"তুনির উঁচু টাওয়ার"}'::jsonb, '{"en":"Tuni''s little brother knocks down her tower and a big angry feeling comes. A read-aloud story about stamping, breathing and using words instead of hands.","bn":"তুনির ছোট ভাই ওর টাওয়ার ভেঙে দেয়, আর বিশাল একটা রাগ চলে আসে। হাতের বদলে পা ধপধপ, শ্বাস আর মুখের কথা ব্যবহারের একটা গল্প।"}'::jsonb, '{"en":"Tuni was building a tower. A blue block. A red block. A yellow block. A green block.\n\n''It''s as tall as me!'' said Tuni. ''It''s the tallest tower in all of Dhaka!''\n\nJust then, her little brother Nayeem crawled over. He was only one year old. He saw the tower. He giggled. And he swiped it with his chubby hand.\n\nCRASH!\n\nAll the blocks fell down. Blue, red, yellow, green, everywhere.\n\nTuni felt something hot inside her. Her face got hot. Her hands squeezed into fists. Her arm went up. She wanted to hit!\n\nBut then Tuni remembered what Ammu had taught her: when the angry feeling comes, stop, stamp, breathe, and say it.\n\nSo Tuni **stopped**.\n\nShe **stamped** her feet. Stamp! Stamp! Stamp!\n\nShe **breathed** a big breath, in through her nose, and out like a balloon going down. Whooooosh.\n\nAnd she **said it**, loud and clear:\n\n''I AM ANGRY! You broke my tower!''\n\nAmmu came running. She knelt down and looked at Tuni.\n\n''You are very angry,'' said Ammu. ''Your tall tower fell down. And you didn''t hit. You used your words. I am so proud of you.''\n\nTuni''s angry feeling began to get smaller. Like a big wave going back into the sea.\n\nNayeem looked at the blocks. His lip went wobbly. He didn''t know he had done something wrong. He was just a baby.\n\n''Nayeem likes to knock things down,'' said Ammu. ''What could we do?''\n\nTuni thought. Then she had an idea. ''I''ll build one big tower for me, up on the table. And a little tower for Nayeem, on the floor. He can knock down his one!''\n\nSo that''s what they did. Tuni built. Nayeem knocked. CRASH! Nayeem laughed and laughed. Tuni laughed too.\n\nThat night, Tuni told Abbu, ''When the angry feeling comes, I can stop, stamp, breathe, and say it.''\n\n''That,'' said Abbu, ''is a very grown-up thing to do.''\n\n**Talk together:** What made Tuni angry? What did she do instead of hitting? Let''s practise together: stop, stamp, breathe, and say it!","bn":"তুনি একটা টাওয়ার বানাচ্ছিল। একটা নীল ব্লক। একটা লাল ব্লক। একটা হলুদ ব্লক। একটা সবুজ ব্লক।\n\n“এটা আমার সমান উঁচু!” বলল তুনি। “পুরো ঢাকা শহরের সবচেয়ে উঁচু টাওয়ার!”\n\nঠিক তখনই হামাগুড়ি দিয়ে এল ছোট ভাই নাঈম। নাঈমের বয়স মাত্র এক বছর। সে টাওয়ারটা দেখল। খিলখিল করে হাসল। তারপর নাদুসনুদুস হাত দিয়ে দিল এক ধাক্কা।\n\nধপাস!\n\nসব ব্লক পড়ে গেল। নীল, লাল, হলুদ, সবুজ — চারদিকে ছড়িয়ে।\n\nতুনির ভেতরে কেমন গরম লাগতে লাগল। মুখটা গরম হয়ে গেল। হাত দুটো মুঠি হয়ে গেল। হাতটা ওপরে উঠে গেল। ওর মারতে ইচ্ছে করছিল!\n\nকিন্তু তখনই তুনির মনে পড়ল আম্মু কী শিখিয়েছিল: রাগ এলে — থামো, পা ধপধপ করো, শ্বাস নাও, আর মুখে বলো।\n\nতাই তুনি **থামল**।\n\nপা দিয়ে **ধপধপ** করল। ধপ! ধপ! ধপ!\n\nএকটা বড় **শ্বাস নিল** — নাক দিয়ে ভেতরে, আর বেলুনের বাতাস বের হওয়ার মতো বাইরে। ফুউউউস।\n\nতারপর জোরে, স্পষ্ট করে **মুখে বলল**:\n\n“আমার খুব রাগ লাগছে! তুমি আমার টাওয়ার ভেঙে দিয়েছ!”\n\nআম্মু দৌড়ে এলেন। হাঁটু গেড়ে বসে তুনির চোখের দিকে তাকালেন।\n\n“তোমার খুব রাগ লাগছে,” বললেন আম্মু। “তোমার উঁচু টাওয়ারটা পড়ে গেছে। আর তুমি মারোনি। তুমি মুখে বলেছ। আমার খুব গর্ব হচ্ছে।”\n\nতুনির রাগটা ছোট হতে লাগল — যেন বড় একটা ঢেউ আবার সাগরে ফিরে যাচ্ছে।\n\nনাঈম ব্লকগুলোর দিকে তাকাল। ওর ঠোঁট কাঁপতে লাগল। ও তো জানত না যে ভুল কিছু করেছে। ও তো একদম ছোট্ট বাবু।\n\n“নাঈম জিনিস ফেলে দিতে ভালোবাসে,” বললেন আম্মু। “কী করা যায় বলো তো?”\n\nতুনি ভাবল। তারপর ওর মাথায় একটা বুদ্ধি এল। “আমি টেবিলের ওপরে আমার জন্য একটা বড় টাওয়ার বানাব। আর মেঝেতে নাঈমের জন্য একটা ছোট টাওয়ার। নাঈম ওরটা ভাঙবে!”\n\nতারা ঠিক তাই করল। তুনি বানায়, নাঈম ভাঙে। ধপাস! নাঈম হেসে গড়াগড়ি। তুনিও হাসল।\n\nরাতে তুনি আব্বুকে বলল, “রাগ এলে আমি থামতে পারি, পা ধপধপ করতে পারি, শ্বাস নিতে পারি, আর মুখে বলতে পারি।”\n\nআব্বু বললেন, “এটা তো একদম বড়দের মতো কাজ!”\n\n**একসাথে কথা বলুন:** তুনির রাগ হয়েছিল কেন? মারার বদলে সে কী করল? চলো একসাথে অনুশীলন করি — থামো, পা ধপধপ, শ্বাস নাও, আর মুখে বলো!"}'::jsonb, '{}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['story', 'anger', 'use your words', 'sibling', 'blocks', 'bedtime story']::text[], false, 'in_review'::lp_review_status, 5021),
  ('ec-act-kitchen-helper', 'activity', 'general', 'shared', 'routine', 'consensus', '🥕', '{"en":"Little kitchen helper","bn":"রান্নাঘরের ছোট্ট সাহায্যকারী"}'::jsonb, '{"en":"Give your child a safe, real job while you prepare food. They learn words, counting and pride in helping, and are often more willing to taste what they made.","bn":"খাবার তৈরির সময় শিশুকে নিরাপদ, সত্যিকারের একটা কাজ দিন। এতে শব্দ শেখে, গুনতে শেখে, সাহায্য করার গর্ব পায় — আর নিজের বানানো খাবার চেখে দেখতেও বেশি রাজি হয়।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Young children love to do what adults do. Helping in the kitchen builds hand skills, language (soft, hard, wet, more, less), early maths and a sense of being useful to the family. Children who help prepare food are often more curious to try it.","bn":"ছোট শিশুরা বড়দের মতো কাজ করতে ভালোবাসে। রান্নাঘরে সাহায্য করলে হাতের দক্ষতা, ভাষা (নরম, শক্ত, ভেজা, বেশি, কম), প্রাথমিক গণিত আর পরিবারের কাজে লাগার অনুভূতি তৈরি হয়। যে শিশু খাবার বানাতে হাত লাগায়, সে প্রায়ই সেটা চেখে দেখতে বেশি আগ্রহী হয়।"},"items":{"en":["A plastic bowl and a small basin of clean water","Vegetables to wash, such as potatoes, carrots or tomatoes","Shak (leafy greens) to pick from the stems","A banana or boiled egg to peel","A spoon for mixing","Plates and spoons to set out","A small stool or a mat on the floor, away from the stove"],"bn":["একটা প্লাস্টিকের বাটি আর ছোট এক গামলা পরিষ্কার পানি","ধোয়ার মতো সবজি — আলু, গাজর বা টমেটো","ডাঁটা থেকে বাছার জন্য শাক","খোসা ছাড়ানোর জন্য কলা বা সেদ্ধ ডিম","মেশানোর জন্য একটা চামচ","সাজানোর জন্য থালা আর চামচ","চুলা থেকে দূরে একটা ছোট টুল বা মেঝেতে একটা মাদুর"]},"steps":{"en":["Wash hands together with soap first.","Set your child up at a table or on a mat well away from the stove, hot pots and knives.","Give one job at a time: wash the potatoes, pick the shak leaves, peel the banana.","Talk as you work: ''This tomato is red and round. How many potatoes did you wash? Let''s count.''","Let your child mix something simple, such as chira with doi, or dry ingredients in a bowl.","Ask them to set out plates and spoons for the family.","At the meal, tell everyone what your child helped make, and thank them."],"bn":["প্রথমে একসাথে সাবান দিয়ে হাত ধুয়ে নিন।","চুলা, গরম হাঁড়ি আর বঁটি-ছুরি থেকে অনেক দূরে টেবিলে বা মাদুরে শিশুকে বসান।","একবারে একটা কাজ দিন: আলু ধোয়া, শাক বাছা, কলার খোসা ছাড়ানো।","কাজ করতে করতে কথা বলুন: “এই টমেটোটা লাল আর গোল। তুমি কয়টা আলু ধুলে? চলো গুনি।”","সহজ কিছু মেশাতে দিন — যেমন দই-চিড়া, বা বাটিতে শুকনো উপকরণ।","পরিবারের সবার জন্য থালা আর চামচ সাজাতে বলুন।","খাওয়ার সময় সবাইকে বলুন শিশু কী বানাতে সাহায্য করেছে, আর ধন্যবাদ দিন।"]},"avoid":{"en":["Knives, bonti, graters and the stove: these stay adult-only","Hot water, hot oil and hot rice water (phyan) anywhere near the child","Raw egg or raw meat for tasting","Expecting a neat result: mess is part of learning"],"bn":["ছুরি, বঁটি, গ্রেটার আর চুলা — এগুলো শুধু বড়দের জন্য","গরম পানি, গরম তেল আর গরম ভাতের মাড় (ফ্যান) শিশুর ধারেকাছে","কাঁচা ডিম বা কাঁচা মাংস চেখে দেখতে দেওয়া","সুন্দর গোছানো কাজ আশা করা — এলোমেলো হওয়াটাও শেখার অংশ"]}}'::jsonb, 2, 730, 1461, '{}'::text[], 'any', ARRAY['activity', 'kitchen', 'cooking', 'helping', 'food', 'chores']::text[], false, 'in_review'::lp_review_status, 5022),
  ('ec-act-colour-sorting', 'activity', 'general', 'shared', 'routine', 'consensus', '🎨', '{"en":"Colour sorting game","bn":"রং মিলিয়ে সাজানোর খেলা"}'::jsonb, '{"en":"Sort everyday things into groups by colour. A simple, free game that builds colour words, matching and early thinking skills.","bn":"ঘরের সাধারণ জিনিস রং অনুযায়ী আলাদা করে সাজান। সহজ, খরচহীন একটা খেলা — রঙের নাম, মেলানো আর চিন্তার প্রাথমিক দক্ষতা গড়ে তোলে।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Sorting by colour teaches children to notice what is the same and what is different, which is an early maths and thinking skill. It also builds colour words; many children can name a few colours by around four.","bn":"রং দিয়ে আলাদা করতে গিয়ে শিশু শেখে কোনটা একই আর কোনটা আলাদা — এটা গণিত আর চিন্তার প্রাথমিক দক্ষতা। এতে রঙের নামও শেখা হয়; অনেক শিশু চার বছরের দিকে কয়েকটা রঙের নাম বলতে পারে।"},"items":{"en":["Three or four bowls, cups or pieces of coloured paper","Large everyday objects in matching colours: socks, plastic cups, blocks, big bottle caps, clothes pegs","Fruit and vegetables also work: a tomato, a banana, a cucumber, an aubergine"],"bn":["তিন-চারটা বাটি, কাপ বা রঙিন কাগজের টুকরো","মিলিয়ে রাখার মতো বড় আকারের ঘরের জিনিস — মোজা, প্লাস্টিকের কাপ, ব্লক, বড় বোতলের ছিপি, কাপড়ের ক্লিপ","ফল-সবজিও চলে — টমেটো, কলা, শসা, বেগুন"]},"steps":{"en":["Start with just two colours, such as red and yellow. Put one bowl for each.","Show one object and name it: ''This sock is red. It goes in the red bowl.''","Hand your child the next one and ask, ''Where does this go?''","If they choose wrongly, don''t say ''wrong''. Hold it next to both: ''Is it the same as this one, or this one?''","Add more colours as your child gets confident.","Turn it into a hunt: ''Can you find three yellow things in this room?''","Finish by tidying up together, colour by colour."],"bn":["মাত্র দুটি রং দিয়ে শুরু করুন — যেমন লাল আর হলুদ, প্রতিটার জন্য একটা বাটি।","একটা জিনিস দেখিয়ে নাম বলুন: “এই মোজাটা লাল। এটা লাল বাটিতে যাবে।”","পরেরটা শিশুর হাতে দিয়ে জিজ্ঞেস করুন: “এটা কোথায় যাবে?”","ভুল জায়গায় রাখলে “ভুল” বলবেন না। দুটোর পাশে ধরে জিজ্ঞেস করুন: “এটার মতো, নাকি ওটার মতো?”","শিশু আত্মবিশ্বাসী হলে আরও রং যোগ করুন।","খোঁজার খেলা বানান: “এই ঘরে তিনটা হলুদ জিনিস খুঁজে বের করতে পারবে?”","শেষে একসাথে রং ধরে ধরে সব গুছিয়ে রাখুন।"]},"avoid":{"en":["Small objects such as buttons, beads, beans or coins, which can be swallowed or choked on, especially under three","Leaving your child alone with the objects","Testing or quizzing too much: keep it a game"],"bn":["বোতাম, পুঁতি, ডাল-বীজ বা পয়সার মতো ছোট জিনিস — গিলে ফেলা বা গলায় আটকানোর ঝুঁকি আছে, বিশেষ করে তিন বছরের নিচে","জিনিসগুলোর সাথে শিশুকে একা রেখে যাওয়া","বেশি পরীক্ষা নেওয়া বা প্রশ্ন করা — খেলাটা খেলাই থাকুক"]}}'::jsonb, 2, 730, 1461, '{}'::text[], 'any', ARRAY['activity', 'colours', 'sorting', 'matching', 'early maths', 'game']::text[], false, 'in_review'::lp_review_status, 5023),
  ('ec-act-nature-hunt', 'activity', 'general', 'shared', 'routine', 'consensus', '🍃', '{"en":"Outdoor nature hunt","bn":"বাইরে প্রকৃতি খোঁজার খেলা"}'::jsonb, '{"en":"Go outside with a small bag and look for leaves, flowers, stones and feathers. It gets your child moving, talking and noticing the world.","bn":"ছোট একটা ব্যাগ নিয়ে বাইরে বেরিয়ে পড়ুন — পাতা, ফুল, পাথর আর পালক খুঁজুন। এতে শিশু নড়াচড়া করে, কথা বলে আর চারপাশটা খেয়াল করতে শেখে।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"WHO advises that children aged one to four spend at least 180 minutes a day in physical activity of any kind, spread through the day. A nature hunt adds walking, bending, climbing and running, along with new words, counting and curiosity.","bn":"WHO-র পরামর্শ: এক থেকে চার বছরের শিশু দিনে অন্তত ১৮০ মিনিট যেকোনো ধরনের শারীরিক সক্রিয়তায় কাটাবে, সারাদিনে ভাগ করে। প্রকৃতি খোঁজার খেলায় হাঁটা, নিচু হওয়া, বেয়ে ওঠা আর দৌড়ানোর সাথে নতুন শব্দ, গোনা আর কৌতূহলও যোগ হয়।"},"items":{"en":["A small cloth bag, basket or paper bag","A short list, drawn as pictures: a leaf, a flower, a stone, a stick, a feather, something round","Sandals or shoes","Water to drink, and a cap in the sun"],"bn":["ছোট একটা কাপড়ের ব্যাগ, ঝুড়ি বা কাগজের ঠোঙা","ছবি এঁকে বানানো ছোট একটা তালিকা — পাতা, ফুল, পাথর, কাঠি, পালক, গোল কিছু","স্যান্ডেল বা জুতা","খাওয়ার পানি, আর রোদে একটা টুপি"]},"steps":{"en":["Choose a safe place: a courtyard, a park, a field edge or a quiet lane, away from roads and water.","Show your child the picture list and say what you are looking for.","Walk slowly and point things out: ''Look, a big green leaf! Can you find a small one?''","Let your child pick up and carry what they find. Count the treasures together.","Talk about colour, size and feel: rough, smooth, soft, prickly.","At home, lay the treasures out, sort them or stick leaves on paper to make a picture.","Wash hands with soap when you get back."],"bn":["নিরাপদ একটা জায়গা বেছে নিন — উঠান, পার্ক, মাঠের ধার বা নিরিবিলি গলি, রাস্তা আর পানি থেকে দূরে।","শিশুকে ছবির তালিকাটা দেখিয়ে বলুন কী কী খুঁজবেন।","ধীরে হাঁটুন, দেখিয়ে দিন: “দেখো, বড় একটা সবুজ পাতা! একটা ছোট পাতা খুঁজে পাবে?”","যা পায়, শিশুকে তুলে নিজে বয়ে নিতে দিন। একসাথে ‘গুপ্তধন’ গুনুন।","রং, আকার আর ছোঁয়া নিয়ে কথা বলুন — খসখসে, মসৃণ, নরম, কাঁটাওয়ালা।","বাসায় ফিরে গুপ্তধনগুলো সাজান, রং বা আকার ধরে আলাদা করুন, বা কাগজে পাতা লাগিয়ে ছবি বানান।","ফিরে এসে সাবান দিয়ে হাত ধুয়ে নিন।"]},"avoid":{"en":["Ponds, ditches, drains and roadsides: hold hands and keep away","Putting anything found in the mouth, including berries, seeds and mushrooms","Tall grass, bushes and holes where snakes or insects may hide","The hottest part of the day in summer"],"bn":["পুকুর, ডোবা, নালা আর রাস্তার ধার — হাত ধরে দূরে থাকুন","পাওয়া কোনো কিছু মুখে দেওয়া — ফল, বীজ, ব্যাঙের ছাতাসহ","লম্বা ঘাস, ঝোপঝাড় আর গর্ত, যেখানে সাপ বা পোকামাকড় লুকিয়ে থাকতে পারে","গরমকালে দিনের সবচেয়ে রোদের সময়"]}}'::jsonb, 2, 730, 1461, '{}'::text[], 'any', ARRAY['activity', 'outdoor', 'nature', 'walk', 'leaves', 'physical activity']::text[], false, 'in_review'::lp_review_status, 5024),
  ('ec-act-flour-playdough', 'activity', 'general', 'shared', 'routine', 'consensus', '🫓', '{"en":"Homemade flour playdough","bn":"আটা দিয়ে ঘরে বানানো খেলার মাটি"}'::jsonb, '{"en":"Make soft playdough from atta or maida, salt and water, and let your child squeeze, roll and shape it. Great for hand strength, creativity and calm.","bn":"আটা বা ময়দা, লবণ আর পানি দিয়ে নরম খেলার মাটি বানান, আর শিশুকে চাপতে, গড়াতে আর আকার দিতে দিন। হাতের শক্তি, সৃজনশীলতা আর মন শান্ত করার জন্য দারুণ।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Squeezing, rolling and pinching dough strengthens the small muscles in the hands that children will later use to hold a pencil and button clothes. Shaping roti, fruits or animals also fuels pretend play and new words, and the soft feel can calm an upset child.","bn":"মাটি চাপা, গড়ানো আর চিমটি দিয়ে ধরা হাতের ছোট পেশিগুলো শক্ত করে — যেগুলো দিয়ে পরে শিশু পেনসিল ধরবে আর জামার বোতাম লাগাবে। রুটি, ফল বা পশুপাখি বানাতে গিয়ে ভান-খেলা আর নতুন শব্দও আসে, আর নরম ছোঁয়া মন খারাপ শিশুকে শান্তও করতে পারে।"},"items":{"en":["2 cups atta or maida","Half a cup of salt","About three-quarters of a cup of water, added little by little","1 tablespoon cooking oil","Colour if you like: a pinch of turmeric for yellow, beetroot juice for pink, or food colouring","A mat or tray, and a rolling pin, cup or bottle caps for shaping"],"bn":["২ কাপ আটা বা ময়দা","আধা কাপ লবণ","প্রায় পৌনে এক কাপ পানি, অল্প অল্প করে দিতে হবে","১ টেবিল চামচ রান্নার তেল","চাইলে রং: হলুদের জন্য এক চিমটি হলুদ গুঁড়া, গোলাপির জন্য বিটের রস, বা খাবারের রং","একটা মাদুর বা ট্রে, আর আকার দেওয়ার জন্য বেলুনি, কাপ বা বোতলের ছিপি"]},"steps":{"en":["An adult mixes the flour and salt in a big bowl.","Add the oil and colour, then add water slowly while mixing, until it forms a soft dough that doesn''t stick.","Let your child knead it with you. Add a little flour if sticky, a little water if dry.","Play together: roll snakes and balls, make roti, fruits or a family of animals.","Name what you make and count the pieces.","Store in a closed box or bag in a cool place; it keeps for several days.","Wash hands afterwards."],"bn":["একজন বড় মানুষ বড় একটা বাটিতে আটা আর লবণ মেশাবেন।","তেল আর রং দিন, তারপর নাড়তে নাড়তে অল্প অল্প পানি দিন, যতক্ষণ না নরম, হাতে না লেগে থাকা মণ্ড হয়।","শিশুকে আপনার সাথে মাখতে দিন। আঠালো হলে একটু আটা, শুকনো হলে একটু পানি দিন।","একসাথে খেলুন — সাপ আর বল গড়ান, রুটি, ফল বা পশুপাখির পরিবার বানান।","যা বানাচ্ছেন তার নাম বলুন, টুকরোগুলো গুনুন।","ঢাকনা দেওয়া বাক্সে বা ব্যাগে ঠান্ডা জায়গায় রাখুন; কয়েক দিন ভালো থাকে।","শেষে হাত ধুয়ে নিন।"]},"avoid":{"en":["Letting your child eat the dough: it is very salty and can make a small child ill if a lot is eaten","Leaving the dough where young children or pets can eat it","Using it if your child has a known wheat allergy","Playing near the stove or with hot water"],"bn":["শিশুকে মাটিটা খেতে দেওয়া — এটা খুব লবণাক্ত, বেশি খেলে ছোট শিশু অসুস্থ হতে পারে","ছোট শিশু বা পোষা প্রাণী খেয়ে ফেলতে পারে এমন জায়গায় ফেলে রাখা","শিশুর গমে অ্যালার্জি জানা থাকলে ব্যবহার করা","চুলার কাছে বা গরম পানি নিয়ে খেলা"]}}'::jsonb, 2, 730, 1461, '{}'::text[], 'any', ARRAY['activity', 'playdough', 'clay', 'flour', 'hand skills', 'creativity']::text[], false, 'in_review'::lp_review_status, 5025),
  ('ec-act-action-rhymes', 'activity', 'general', 'shared', 'routine', 'consensus', '🎶', '{"en":"Singing rhymes with actions","bn":"অঙ্গভঙ্গি করে ছড়া বলা"}'::jsonb, '{"en":"Sing the rhymes you grew up with, adding claps, hand moves and stamps. Rhythm and repetition help language, memory and movement, and it''s pure fun.","bn":"নিজের ছোটবেলার ছড়াগুলো বলুন বা গান, সাথে তালি, হাতের ভঙ্গি আর পা ধপধপ। ছন্দ আর বারবার বলা ভাষা, স্মৃতি আর নড়াচড়ায় সাহায্য করে — আর পুরোটাই আনন্দ।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Rhymes break words into beats and sounds, which helps speech and later reading. Doing actions with the words links language to movement and memory. Sharing the rhymes that parents and grandparents knew also passes on family and cultural heritage.","bn":"ছড়া শব্দকে তালে আর ধ্বনিতে ভাগ করে — যা কথা বলা আর পরে পড়তে শেখায় সাহায্য করে। শব্দের সাথে অঙ্গভঙ্গি করলে ভাষা, নড়াচড়া আর স্মৃতি একসাথে জুড়ে যায়। বাবা-মা আর দাদা-দাদি, নানা-নানির জানা ছড়া ভাগ করে নিলে পারিবারিক আর সাংস্কৃতিক ঐতিহ্যও এগিয়ে যায়।"},"items":{"en":["Nothing but your voice and hands","Rhymes you know, for example traditional Bangla chhora such as ''Ay ay chand mama'', ''Ata gachhe tota pakhi'', ''Notun notun payraguli'' or ''Khokon khokon kore may''","English rhymes such as ''Twinkle, Twinkle, Little Star'', ''Head, Shoulders, Knees and Toes'' or ''Row, Row, Row Your Boat''","Optional: a spoon and a pot as a drum"],"bn":["শুধু আপনার গলা আর হাত","জানা ছড়া — যেমন প্রচলিত বাংলা ছড়া ‘আয় আয় চাঁদ মামা’, ‘আতা গাছে তোতা পাখি’, ‘নোটন নোটন পায়রাগুলি’ বা ‘খোকন খোকন করে মায়’","ইংরেজি ছড়া — যেমন ‘Twinkle, Twinkle, Little Star’, ‘Head, Shoulders, Knees and Toes’ বা ‘Row, Row, Row Your Boat’","চাইলে ঢোল হিসেবে একটা হাঁড়ি আর চামচ"]},"steps":{"en":["Sit facing your child, or stand if the rhyme has big moves.","Say or sing the rhyme slowly, with a clear beat.","Add simple actions: point to the moon, flap arms like birds, clap on the beat, touch head and toes.","Repeat the same rhyme on many days. Soon your child will join in the actions, then the last word of each line, then whole lines.","Pause before a familiar word and let your child fill it in.","Try it fast and slow, loud and whispering.","Ask grandparents to teach the rhymes they remember, and use a short rhyme as a hand-washing or tidy-up song."],"bn":["শিশুর মুখোমুখি বসুন, আর ছড়ায় বড় অঙ্গভঙ্গি থাকলে দাঁড়িয়ে নিন।","পরিষ্কার তালে, ধীরে ধীরে ছড়াটা বলুন বা গান।","সহজ ভঙ্গি যোগ করুন — চাঁদের দিকে আঙুল দেখানো, পাখির মতো হাত ঝাপটানো, তালে তালি, মাথা আর পায়ের আঙুল ছোঁয়া।","একই ছড়া অনেক দিন ধরে বারবার বলুন। শিশু প্রথমে ভঙ্গিতে যোগ দেবে, তারপর প্রতিটি লাইনের শেষ শব্দ, তারপর পুরো লাইন।","চেনা শব্দের আগে থামুন, শিশুকে শব্দটা বলতে দিন।","কখনো দ্রুত, কখনো ধীরে, কখনো জোরে, কখনো ফিসফিস করে বলুন।","দাদা-দাদি, নানা-নানিকে তাঁদের মনে থাকা ছড়া শেখাতে বলুন; হাত ধোয়া বা গোছানোর সময় ছোট একটা ছড়াকে গান বানিয়ে নিন।"]}}'::jsonb, 2, 730, 1461, '{}'::text[], 'any', ARRAY['activity', 'rhymes', 'chhora', 'songs', 'music', 'movement', 'language']::text[], false, 'in_review'::lp_review_status, 5026),
  ('ec-sc-tantrum-in-public', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '🛒', '{"en":"My child has a tantrum in the shop or in front of guests","bn":"দোকানে বা মেহমানদের সামনে শিশু রেগে কান্নাকাটি করছে"}'::jsonb, '{"en":"A tantrum in public feels worse because people are watching. Focus on your child, not the audience: stay calm, keep them safe and hold the limit kindly.","bn":"সবার সামনে রেগে কান্নাকাটি বেশি খারাপ লাগে, কারণ মানুষ তাকিয়ে থাকে। দর্শকের দিকে নয়, শিশুর দিকে মন দিন — শান্ত থাকুন, নিরাপদ রাখুন, আর নরমভাবে সীমা ধরে রাখুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Your child is not trying to embarrass you. Shops, markets, weddings and visits are full of noise, people and things they want, and they are often hungry or tired. The feeling grows faster than their ability to calm down.","bn":"শিশু আপনাকে লজ্জা দিতে চাইছে না। দোকান, বাজার, বিয়েবাড়ি আর বেড়াতে যাওয়া — সবখানে শব্দ, মানুষ আর পছন্দের জিনিসে ভরা, আর শিশু প্রায়ই ক্ষুধার্ত বা ক্লান্ত থাকে। আবেগটা শান্ত হওয়ার ক্ষমতার চেয়ে দ্রুত বেড়ে যায়।"},"why":{"en":"Busy places overload a young child''s senses. They are also hearing ''no'' more often (''Don''t touch that'', ''We''re not buying it''). Without words for big feelings, the body takes over.","bn":"ভিড়ের জায়গায় ছোট শিশুর ইন্দ্রিয়ের ওপর চাপ পড়ে। সেখানে সে বারবার ‘না’ শোনে (“ধরো না”, “এটা কিনব না”)। বড় অনুভূতি বোঝানোর শব্দ না থাকায় শরীরই নিয়ন্ত্রণ নিয়ে নেয়।"},"normal":{"en":"Public tantrums are very common between two and four, and most parents have faced one. They become less frequent as language and self-control grow.","bn":"দুই থেকে চার বছর বয়সে সবার সামনে রেগে কান্নাকাটি খুব সাধারণ — বেশিরভাগ বাবা-মা-ই এর মুখোমুখি হয়েছেন। ভাষা আর নিজেকে সামলানোর ক্ষমতা বাড়লে এটা কমে আসে।"},"do_now":{"en":["Take a slow breath yourself. Remind yourself: my child is having a hard time, not giving me a hard time.","Make sure your child is safe; move them gently to a quieter corner or outside if needed.","Get down to their level and use few words: ''You really wanted the chips. You are upset. I''m here.''","Don''t buy the thing to stop the crying, if you had already said no.","Wait calmly nearby. Ignore stares; most parents watching have been there.","When calm returns, hug, give water and carry on or head home."],"bn":["নিজে একটা ধীর শ্বাস নিন। মনে মনে বলুন: শিশু আমাকে কষ্ট দিচ্ছে না, ও নিজে কষ্টে আছে।","শিশু নিরাপদ আছে কি না দেখুন; দরকার হলে আলতো করে নিরিবিলি কোণে বা বাইরে নিয়ে যান।","শিশুর সমান হয়ে বসুন, কম কথা বলুন: “তুমি চিপসটা খুব চাইছিলে। তোমার মন খারাপ। আমি আছি।”","আগেই ‘না’ বলে থাকলে কান্না থামাতে জিনিসটা কিনে দেবেন না।","পাশে শান্তভাবে অপেক্ষা করুন। লোকের চাহনি পাত্তা দেবেন না — যাঁরা দেখছেন, তাঁদের বেশিরভাগই এমন সময় পার করেছেন।","শান্ত হলে জড়িয়ে ধরুন, পানি দিন, তারপর কাজ চালিয়ে যান বা বাসায় ফিরুন।"]},"steps":{"en":["Plan outings after a nap and a snack, not when your child is tired or hungry.","Tell your child the plan before you go: ''We are buying rice and dal. We are not buying sweets today.''","Give them a job: holding the list, putting potatoes in the bag, counting eggs.","Bring a small snack and a toy or book for waiting.","Praise calm behaviour during the trip: ''You''re being such a good helper.''","Keep trips short when you can, and leave early if your child is getting tired.","Agree with your partner and family on how you will all respond, so the message is the same."],"bn":["দুপুরের ঘুম আর নাশতার পরে বাইরে যাওয়ার পরিকল্পনা করুন, শিশু ক্লান্ত বা ক্ষুধার্ত থাকার সময় নয়।","বের হওয়ার আগে পরিকল্পনাটা বলে দিন: “আমরা চাল আর ডাল কিনব। আজ মিষ্টি কিনব না।”","একটা কাজ দিন — তালিকা ধরে রাখা, ব্যাগে আলু রাখা, ডিম গোনা।","সাথে ছোট একটা নাশতা আর অপেক্ষার জন্য একটা খেলনা বা বই রাখুন।","পথে শান্ত আচরণের প্রশংসা করুন: “তুমি আজ কত ভালো সাহায্যকারী!”","সম্ভব হলে অল্প সময়ে কাজ সারুন, আর শিশু ক্লান্ত হতে থাকলে আগেভাগেই ফিরুন।","সঙ্গী আর পরিবারের সাথে ঠিক করে নিন সবাই কীভাবে সাড়া দেবেন, যাতে বার্তা একই থাকে।"]},"avoid":{"en":["Hitting, pinching or shouting to stop it quickly","Threats such as ''I''ll leave you here'' or ''That uncle will take you away''","Giving in after saying no, which teaches that public tantrums work","Long explanations in the middle of the storm","Shaming your child later in front of others"],"bn":["তাড়াতাড়ি থামাতে মারা, চিমটি কাটা বা চিৎকার","ভয় দেখানো — “তোমাকে এখানে রেখে চলে যাব” বা “ওই আংকেল তোমাকে নিয়ে যাবে”","‘না’ বলার পরে হার মেনে নেওয়া — এতে শিশু শেখে, সবার সামনে কাঁদলে কাজ হয়","ঝড়ের মাঝখানে লম্বা বোঝানো","পরে অন্যদের সামনে শিশুকে লজ্জা দেওয়া"]},"example":{"en":"At the bazaar, three-year-old Sami threw himself down when his father said no to a toy car. Abbu crouched beside him, moved him away from the walkway and said quietly, ''You really want that car. It''s hard to hear no.'' He waited without arguing. After a few minutes Sami climbed into his lap. Abbu said, ''Let''s go and choose the bananas together. You can carry them.'' They finished the shopping, and Abbu thanked him for helping.","bn":"বাজারে খেলনা গাড়ি কিনে দিতে আব্বু ‘না’ বলায় তিন বছরের সামি মাটিতে শুয়ে পড়ল। আব্বু পাশে বসে ওকে হাঁটার পথ থেকে একপাশে সরিয়ে নিলেন, আস্তে বললেন, “তুমি গাড়িটা খুব চাইছ। ‘না’ শুনতে কষ্ট লাগে।” তর্ক না করে অপেক্ষা করলেন। কয়েক মিনিট পর সামি আব্বুর কোলে উঠে এল। আব্বু বললেন, “চলো, একসাথে কলা বেছে নিই। তুমি বয়ে নেবে।” বাজার শেষ হলো, আর আব্বু ওকে সাহায্যের জন্য ধন্যবাদ দিলেন।"},"seek_help":{"en":["Tantrums happen many times every day or last a very long time","Your child often hurts themselves or others during tantrums","Tantrums are still very frequent after age five","You also have concerns about speech, hearing or development","You feel you are losing control or close to hitting often"],"bn":["প্রতিদিন অনেকবার রেগে কান্নাকাটি হয়, বা খুব লম্বা সময় ধরে চলে","এ সময় শিশু প্রায়ই নিজেকে বা অন্যকে আঘাত করে","পাঁচ বছরের পরেও খুব ঘনঘন হয়","কথা বলা, শোনা বা বিকাশ নিয়েও চিন্তা আছে","আপনার মনে হয় প্রায়ই নিয়ন্ত্রণ হারিয়ে ফেলছেন বা মেরে ফেলার কাছাকাছি চলে যাচ্ছেন"]}}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['tantrum', 'public', 'shop', 'market', 'embarrassed', 'meltdown']::text[], false, 'in_review'::lp_review_status, 5027),
  ('ec-sc-hitting-biting', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '✋', '{"en":"My child hits or bites other children","bn":"শিশু অন্য বাচ্চাদের মারে বা কামড়ায়"}'::jsonb, '{"en":"Hitting and biting are common at this age when feelings are bigger than words. Step in calmly every time, care for the hurt child, and teach what to do instead. Never hit back.","bn":"অনুভূতি যখন শব্দের চেয়ে বড়, তখন এই বয়সে মারা আর কামড়ানো সাধারণ। প্রতিবার শান্তভাবে থামান, আঘাত পাওয়া শিশুর যত্ন নিন, আর বিকল্প শেখান। কখনো পাল্টা মারবেন না।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"When a two- or three-year-old hits or bites, it usually means ''I''m frustrated'', ''That''s mine'' or ''I''m overwhelmed'', not that they are cruel. They have not yet learned other ways to get what they need.","bn":"দুই-তিন বছরের শিশু যখন মারে বা কামড়ায়, সাধারণত এর মানে “আমি বিরক্ত”, “এটা আমার” বা “আমার আর সহ্য হচ্ছে না” — শিশু নিষ্ঠুর, এমন নয়। চাওয়া পূরণের অন্য উপায় সে এখনো শেখেনি।"},"why":{"en":"Common triggers are fights over toys, crowding, tiredness, hunger, teething in younger toddlers, and wanting attention. Children who are hit at home are more likely to hit others, because they copy what they see.","bn":"সাধারণ কারণ — খেলনা নিয়ে ঝগড়া, গাদাগাদি ভিড়, ক্লান্তি, ক্ষুধা, আর মনোযোগ চাওয়া। যে শিশুকে বাসায় মারা হয়, সে অন্যকে মারার সম্ভাবনা বেশি — কারণ সে যা দেখে, তাই শেখে।"},"normal":{"en":"Some hitting, pushing or biting is common between two and three and usually decreases by four as children learn words and self-control.","bn":"দুই থেকে তিন বছরে মাঝে মাঝে মারা, ধাক্কা দেওয়া বা কামড়ানো সাধারণ; শব্দ আর নিজেকে সামলানো শিখলে চার বছরের দিকে সাধারণত কমে আসে।"},"do_now":{"en":["Step in straight away and calmly separate the children.","Comfort and check the hurt child first. Your child sees that hurting does not bring attention.","Say a short, firm rule at eye level: ''No hitting. Hitting hurts.''","Name the feeling: ''You were angry because he took your truck.''","Show what to do instead: ''You can say, Stop! My turn!'' or come and get me.","If your child is too upset, take them aside to calm down with you, then return to play.","If a bite breaks the skin, wash it well with soap and water and get it checked by a health worker."],"bn":["সাথে সাথে গিয়ে শান্তভাবে দুজনকে আলাদা করুন।","আগে আঘাত পাওয়া শিশুকে দেখুন আর সান্ত্বনা দিন। আপনার শিশু বোঝে, আঘাত করলে মনোযোগ মেলে না।","চোখের সমান হয়ে ছোট, দৃঢ় নিয়মটা বলুন: “মারা যাবে না। মারলে ব্যথা লাগে।”","অনুভূতির নাম দিন: “ও তোমার ট্রাকটা নিয়ে নিয়েছিল, তাই তোমার রাগ হয়েছিল।”","বিকল্প দেখান: “তুমি বলতে পারো, ‘থামো! আমার পালা!’ বা আমার কাছে চলে আসতে পারো।”","খুব বেশি উত্তেজিত থাকলে একপাশে নিয়ে আপনার সাথে শান্ত হতে দিন, তারপর আবার খেলায় ফিরুন।","কামড়ে চামড়া কেটে গেলে সাবান-পানি দিয়ে ভালো করে ধুয়ে স্বাস্থ্যকর্মীকে দেখান।"]},"steps":{"en":["Watch for patterns: when, where and with whom it happens. Step in early when you see the warning signs.","Teach feeling words and safe ways to show anger: stamping, squeezing a pillow, saying ''I''m angry''.","Practise turn-taking and ''Stop!'' in pretend play with dolls.","Keep play groups small and supervised, with enough toys to go round.","Praise gentle play often: ''You gave her a turn. Gentle hands!''","Make sure no one at home hits the child or each other, including older siblings.","Make sure your child gets enough sleep and regular meals."],"bn":["ধরন খেয়াল করুন — কখন, কোথায়, কার সাথে হয়। সতর্ক লক্ষণ দেখলেই আগেভাগে থামান।","অনুভূতির শব্দ আর রাগ দেখানোর নিরাপদ উপায় শেখান — পা ধপধপ, বালিশ চাপা, “আমার রাগ লাগছে” বলা।","পুতুল নিয়ে ভান-খেলায় পালা আর “থামো!” বলার অনুশীলন করুন।","খেলার দল ছোট রাখুন, চোখে চোখে রাখুন, আর যথেষ্ট খেলনা রাখুন।","নরম খেলার প্রশংসা করুন: “তুমি ওকে পালা দিলে। কী সুন্দর নরম হাত!”","নিশ্চিত করুন বাসায় কেউ শিশুকে বা একে অপরকে মারে না — বড় ভাই-বোনসহ।","শিশু যেন যথেষ্ট ঘুমায় আর নিয়মিত খায়।"]},"avoid":{"en":["Hitting or biting your child back ''so they know how it feels'': it teaches that hurting is how big people solve problems","Long lectures or shaming in front of other children","Labelling: ''He is a naughty boy'', ''She is so wild''","Forcing an immediate ''sorry'' before your child is calm"],"bn":["“বুঝুক কেমন লাগে” ভেবে পাল্টা মারা বা কামড়ানো — এতে শেখে, বড়রা ব্যথা দিয়েই সমস্যা মেটায়","অন্য বাচ্চাদের সামনে লম্বা উপদেশ বা লজ্জা দেওয়া","তকমা দেওয়া: “ও খুব দুষ্টু”, “ও একদম বুনো”","শান্ত হওয়ার আগেই জোর করে “সরি” বলানো"]},"example":{"en":"At a cousin''s house, two-year-old Riya bit her cousin when he grabbed her doll. Her mother quickly lifted Riya away, then turned to comfort the cousin and checked his arm. Back with Riya, she said, ''No biting. Biting hurts. You were cross that he took your doll. Next time say, Mine! Stop!'' Later, she watched closely and stepped in early when another tussle started, helping them take turns.","bn":"খালাতো ভাইয়ের বাসায় দুই বছরের রিয়া পুতুল কেড়ে নেওয়ায় ভাইটাকে কামড়ে দিল। আম্মু দ্রুত রিয়াকে কোলে সরিয়ে নিলেন, তারপর ভাইটাকে সান্ত্বনা দিয়ে ওর হাত দেখলেন। রিয়ার কাছে ফিরে বললেন, “কামড়ানো যাবে না। কামড়ালে ব্যথা লাগে। ও তোমার পুতুল নিয়ে নিয়েছিল, তাই রাগ হয়েছিল। পরের বার বলবে, ‘আমার! থামো!’” এরপর তিনি কাছ থেকে নজর রাখলেন, আর আবার টানাটানি শুরু হতেই আগেভাগে গিয়ে দুজনকে পালা করে খেলতে সাহায্য করলেন।"},"seek_help":{"en":["Hitting or biting is very frequent, getting worse, or still common after age four","Your child seriously hurts others or seems to enjoy hurting","There are also concerns about speech, hearing or development","Your child may be seeing violence at home or elsewhere","A bite has broken the skin and looks red, swollen or infected"],"bn":["মারা বা কামড়ানো খুব ঘনঘন হয়, বাড়ছে, বা চার বছরের পরেও প্রায়ই হয়","শিশু অন্যদের গুরুতর আঘাত করে, বা আঘাত করে মজা পায় বলে মনে হয়","কথা বলা, শোনা বা বিকাশ নিয়েও চিন্তা আছে","শিশু হয়তো বাসায় বা অন্য কোথাও সহিংসতা দেখছে","কামড়ে চামড়া কেটে লাল হয়ে গেছে, ফুলে গেছে বা সংক্রমণ মনে হচ্ছে"]}}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['hitting', 'biting', 'aggression', 'pushing', 'other children', 'behaviour']::text[], false, 'in_review'::lp_review_status, 5028),
  ('ec-sc-refuses-food-wants-snacks', 'scenario', 'scientific', 'shared', 'important', 'guideline', '🍟', '{"en":"My child refuses meals and only wants chips or sweets","bn":"শিশু ভাত খেতে চায় না, শুধু চিপস বা মিষ্টি চায়"}'::jsonb, '{"en":"If chips, biscuits and sweets are easy to get, rice and dal can''t compete. Keep them out of the house as everyday food, set regular meal and snack times, and stay calm at the table.","bn":"চিপস, বিস্কুট আর মিষ্টি হাতের কাছে থাকলে ভাত-ডাল পেরে ওঠে না। এগুলোকে রোজকার খাবার হিসেবে ঘরে রাখবেন না, খাবার আর নাশতার নির্দিষ্ট সময় রাখুন, আর খাওয়ার সময় শান্ত থাকুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Packaged snacks and sweets are made to taste very salty or sweet, so home food can seem dull by comparison. A child who fills up on them between meals simply isn''t hungry at mealtime.","bn":"প্যাকেটের নাশতা আর মিষ্টি এমনভাবে বানানো যে খুব নোনতা বা খুব মিষ্টি লাগে, তাই তুলনায় ঘরের খাবার পানসে মনে হয়। দুই খাবারের মাঝে এসব খেয়ে পেট ভরালে খাওয়ার সময় শিশুর আর ক্ষুধা থাকে না।"},"why":{"en":"Common causes are frequent snacks or milk between meals, chips or sweets given to stop crying or as a reward, relatives or shops nearby offering treats, and pressure at mealtimes that makes the table a battle.","bn":"সাধারণ কারণ — দুই খাবারের মাঝে ঘনঘন নাশতা বা দুধ, কান্না থামাতে বা পুরস্কার হিসেবে চিপস-মিষ্টি দেওয়া, আত্মীয়রা বা পাশের দোকান থেকে হাতে হাতে খাবার, আর খাওয়ার সময় চাপাচাপি, যাতে খাবার টেবিলটা যুদ্ধক্ষেত্র হয়ে যায়।"},"normal":{"en":"Appetite naturally varies from day to day at this age, and preferring sweet and salty tastes is normal. It becomes a problem when snacks replace real meals day after day.","bn":"এই বয়সে ক্ষুধা দিন দিন ওঠানামা করে, আর মিষ্টি ও নোনতা স্বাদ পছন্দ করা স্বাভাবিক। সমস্যা হয় যখন দিনের পর দিন নাশতা আসল খাবারের জায়গা নিয়ে নেয়।"},"do_now":{"en":["Stay calm. Don''t argue, beg or force at the table.","Serve the family meal with one food your child usually accepts.","If they don''t eat, calmly clear the plate after about 20–30 minutes.","Don''t offer chips, biscuits or sweets instead. Offer the next planned meal or snack at its usual time.","Give water, not juice or soft drinks, between meals."],"bn":["শান্ত থাকুন। খাবার নিয়ে তর্ক, অনুনয় বা জোর করবেন না।","পরিবারের খাবারের সাথে শিশু সাধারণত খায় এমন একটা খাবার রাখুন।","না খেলে মোটামুটি ২০–৩০ মিনিট পর শান্তভাবে থালা তুলে নিন।","বদলে চিপস, বিস্কুট বা মিষ্টি দেবেন না। পরের নির্ধারিত খাবার বা নাশতা তার সময়মতো দিন।","দুই খাবারের মাঝে জুস বা কোমল পানীয় নয়, পানি দিন।"]},"steps":{"en":["Set a daily rhythm: three meals and one or two planned snacks at roughly the same times.","Stop buying packaged chips, chanachur, sweets and soft drinks for everyday use; keep them for occasional treats.","Offer healthy snacks: fruit, boiled egg, muri, chira with doi, a piece of roti, roasted chickpeas (crushed for younger children).","Eat together without screens, and let your child serve and feed themselves.","Make food fun: let them help wash vegetables, choose between two vegetables, or shape rice into small balls.","Agree with grandparents and relatives on treats, and ask shopkeepers nearby not to give your child sweets.","Keep going to growth checks so you know your child is growing well."],"bn":["প্রতিদিনের একটা ছন্দ ঠিক করুন — মোটামুটি একই সময়ে তিন বেলা খাবার আর এক-দুইবার পরিকল্পিত নাশতা।","রোজকার জন্য প্যাকেটের চিপস, চানাচুর, মিষ্টি আর কোমল পানীয় কেনা বন্ধ করুন; মাঝেমধ্যের জন্য রাখুন।","স্বাস্থ্যকর নাশতা দিন — ফল, সেদ্ধ ডিম, মুড়ি, দই-চিড়া, এক টুকরো রুটি, ভাজা ছোলা (ছোটদের জন্য ভেঙে)।","স্ক্রিন ছাড়া একসাথে খান, শিশুকে নিজে নিয়ে নিজে খেতে দিন।","খাবারকে মজার করুন — সবজি ধুতে দিন, দুটো সবজির মধ্যে বেছে নিতে দিন, ভাতের ছোট ছোট গোল্লা বানাতে দিন।","দাদা-দাদি, নানা-নানি আর আত্মীয়দের সাথে মিষ্টি-নাশতা নিয়ে একমত হোন, পাশের দোকানদারকে অনুরোধ করুন শিশুকে মিষ্টি না দিতে।","নিয়মিত ওজন-উচ্চতা মাপাতে যান, যাতে জানেন শিশু ঠিকমতো বাড়ছে।"]},"avoid":{"en":["Giving chips or sweets when a meal is refused, which teaches that refusing works","Using sweets as a reward or bribe (''Eat your rice and you''ll get chocolate'')","Force-feeding, holding the nose, or feeding while the child cries","Feeding in front of a phone or TV to get food in","Lots of milk or juice between meals"],"bn":["ভাত না খেলে চিপস বা মিষ্টি দেওয়া — এতে শেখে, না খেলেই কাজ হয়","পুরস্কার বা ঘুষ হিসেবে মিষ্টি (“ভাত খেলে চকলেট পাবে”)","জোর করে খাওয়ানো, নাক চেপে ধরা, বা কাঁদতে থাকা অবস্থায় খাওয়ানো","খাবার পেটে ঢোকাতে ফোন বা টিভি দেখিয়ে খাওয়ানো","দুই খাবারের মাঝে বেশি দুধ বা জুস"]},"example":{"en":"Three-year-old Arif ate chips from the corner shop most afternoons, then refused his dinner. His parents agreed to stop buying chips except on Fridays, and asked Dadu to bring bananas instead. At dinner they served rice, dal and his favourite egg, ate together with the TV off, and said nothing about how much he ate. For a few days he ate little; by the second week he was coming to the table hungry.","bn":"তিন বছরের আরিফ প্রায় প্রতি বিকেলে মোড়ের দোকানের চিপস খেত, তারপর রাতের খাবার খেত না। বাবা-মা ঠিক করলেন শুক্রবার ছাড়া চিপস কিনবেন না, আর দাদুকে বললেন চিপসের বদলে কলা আনতে। রাতে তাঁরা ভাত, ডাল আর ওর প্রিয় ডিম দিলেন, টিভি বন্ধ করে একসাথে খেলেন, আর কতটুকু খেল তা নিয়ে কিছু বললেন না। প্রথম কয়েক দিন সে কম খেল; দ্বিতীয় সপ্তাহে ক্ষুধা নিয়ে খেতে বসতে লাগল।"},"seek_help":{"en":["Your child is losing weight, not gaining, or falling on the growth chart","Your child eats only a very small number of foods","Mealtimes cause great distress for the child or family","You notice any of the warning signs below"],"bn":["শিশুর ওজন কমছে, বাড়ছে না, বা গ্রোথ চার্টে নিচে নামছে","শিশু খুব অল্প কয়েকটা খাবার ছাড়া কিছুই খায় না","খাওয়ার সময় শিশু বা পরিবারের খুব কষ্ট হয়","নিচের কোনো সতর্ক লক্ষণ দেখলে"]},"warning_signs":{"en":["Very thin, or swelling of both feet","Unusually tired, pale or weak","Often gagging, choking or vomiting with food","Pain when swallowing or eating","Refuses all food and drink, or is unwell with fever or diarrhoea"],"bn":["খুব রোগা, বা দুই পা ফুলে যাওয়া","অস্বাভাবিক ক্লান্ত, ফ্যাকাশে বা দুর্বল","খাবার খেতে গিয়ে প্রায়ই ওয়াক তোলা, গলায় আটকানো বা বমি","গিলতে বা খেতে ব্যথা","সব খাবার আর পানীয় খেতে না চাওয়া, বা জ্বর বা ডায়রিয়ায় অসুস্থ থাকা"]}}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['refuses food', 'chips', 'sweets', 'junk food', 'picky eating', 'appetite', 'snacks']::text[], false, 'in_review'::lp_review_status, 5029),
  ('ec-sc-bedtime-battles', 'scenario', 'scientific', 'shared', 'routine', 'guideline', '🛏️', '{"en":"Bedtime battles and won''t sleep alone","bn":"ঘুমাতে যেতে যুদ্ধ, একা ঘুমাতে চায় না"}'::jsonb, '{"en":"Many young children resist bedtime or want a parent close. A calm, predictable routine, a regular time and gentle, consistent steps work better than threats.","bn":"অনেক ছোট শিশু ঘুমাতে যেতে চায় না, বা বাবা-মাকে কাছে চায়। ভয় দেখানোর চেয়ে শান্ত, নিয়মিত রুটিন, নির্দিষ্ট সময় আর নরম, ধারাবাহিক ধাপ বেশি কাজ করে।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Bedtime means separation from you and from the fun of the day. Young children also test limits (''One more story!''), and many feel safer with a parent close. Whether your child sleeps in their own bed or with family is your choice; the aim is calm, enough sleep.","bn":"ঘুমাতে যাওয়া মানে আপনার থেকে আর সারাদিনের মজা থেকে আলাদা হওয়া। ছোট শিশুরা সীমাও পরীক্ষা করে (“আরেকটা গল্প!”), আর অনেকে বাবা-মা কাছে থাকলে বেশি নিরাপদ বোধ করে। শিশু নিজের বিছানায় ঘুমাবে নাকি পরিবারের সাথে — সেটা আপনার সিদ্ধান্ত; লক্ষ্য হলো শান্তভাবে যথেষ্ট ঘুম।"},"why":{"en":"Common causes include no fixed bedtime, screens or exciting play late in the evening, a long or late afternoon nap, visitors and noise, and changes such as a new sibling, a move or illness.","bn":"সাধারণ কারণ — ঘুমের নির্দিষ্ট সময় না থাকা, সন্ধ্যার পরে স্ক্রিন বা উত্তেজনার খেলা, দুপুরে লম্বা বা দেরিতে ঘুম, মেহমান আর শব্দ, আর নতুন ভাই-বোন, বাসা বদল বা অসুখের মতো পরিবর্তন।"},"normal":{"en":"Stalling at bedtime and occasional night waking are very common between two and four. WHO advises 11–14 hours of sleep for two-year-olds and 10–13 hours for three- and four-year-olds, naps included.","bn":"দুই থেকে চার বছরে ঘুমের সময় টালবাহানা আর মাঝে মাঝে রাতে জেগে ওঠা খুব সাধারণ। WHO-র পরামর্শ: দুপুরের ঘুমসহ দুই বছরের শিশুর ১১–১৪ ঘণ্টা, আর তিন-চার বছরের শিশুর ১০–১৩ ঘণ্টা ঘুম।"},"do_now":{"en":["Pick a bedtime that suits your family and keep it most nights.","Switch off screens at least an hour before.","Do the same short routine every night: wash, teeth, toilet, story, cuddle, lights off.","Build the ''extras'' into the routine: one drink of water, one last toilet visit, one or two stories.","Say goodnight warmly and clearly, and keep your voice low and boring if your child gets up."],"bn":["পরিবারের জন্য সুবিধাজনক একটা ঘুমের সময় ঠিক করুন, আর বেশিরভাগ রাতে সেটা মানুন।","অন্তত এক ঘণ্টা আগে স্ক্রিন বন্ধ করুন।","প্রতি রাতে একই ছোট রুটিন: হাতমুখ ধোয়া, দাঁত ব্রাশ, টয়লেট, গল্প, আদর, বাতি বন্ধ।","‘বাড়তি’ চাওয়াগুলো রুটিনেই রাখুন — একবার পানি, শেষবার টয়লেট, এক-দুটো গল্প।","উষ্ণভাবে, স্পষ্ট করে শুভরাত্রি বলুন; শিশু উঠে এলে গলা নিচু আর একঘেয়ে রাখুন।"]},"steps":{"en":["Get your child outside and active in the day, and keep the afternoon nap from running too late.","Give a 10-minute warning before the routine starts.","Let your child make small choices: which story, which night clothes.","If you want your child to fall asleep more independently, go step by step: sit next to the bed until asleep for a few nights, then sit a little further away, then near the door.","If they come out, walk them back calmly with few words, as many times as needed.","Praise in the morning: ''You stayed in bed all night. Well done!''","Share bedtime between parents, so both can settle the child."],"bn":["দিনে শিশুকে বাইরে নিয়ে সক্রিয় রাখুন, আর দুপুরের ঘুম যেন খুব দেরি পর্যন্ত না গড়ায়।","রুটিন শুরুর ১০ মিনিট আগে জানিয়ে দিন।","ছোট পছন্দ দিন — কোন গল্প, কোন রাতের জামা।","শিশুকে আরেকটু নিজে নিজে ঘুমাতে শেখাতে চাইলে ধাপে ধাপে এগোন: কয়েক রাত ঘুম না আসা পর্যন্ত বিছানার পাশে বসুন, তারপর একটু দূরে, তারপর দরজার কাছে।","উঠে এলে কম কথায়, শান্তভাবে ফিরিয়ে নিয়ে যান — যতবার দরকার।","সকালে প্রশংসা করুন: “তুমি সারারাত বিছানায় ছিলে। দারুণ!”","বাবা-মা দুজনে ঘুম পাড়ানোর দায়িত্ব ভাগ করুন, যাতে দুজনেই পারেন।"]},"avoid":{"en":["Frightening stories to make children sleep, such as ghosts, jinn or ''the beggar will take you''","Screens or a phone to fall asleep with","Shouting, smacking or locking the door","A different bedtime every night","Sweet drinks or a bottle of milk in bed, which harm teeth"],"bn":["ঘুম পাড়াতে ভয়ের গল্প — ভূত, জিন বা “ছেলেধরা নিয়ে যাবে”","ঘুম পাড়াতে স্ক্রিন বা ফোন","চিৎকার, মারা বা দরজা বন্ধ করে দেওয়া","প্রতি রাতে আলাদা সময়ে ঘুমানো","বিছানায় মিষ্টি পানীয় বা দুধের ফিডার — দাঁতের ক্ষতি করে"]},"example":{"en":"Four-year-old Nabila kept getting up for water, the toilet and ''one more question'' until almost midnight. Her parents moved TV time to the afternoon, set bedtime at 9, and made a picture chart: wash, teeth, toilet, water, two stories, cuddle. On nights when she got up, Abbu walked her back saying only, ''It''s sleep time. I love you.'' Within two weeks she was asleep by 9:30 most nights.","bn":"চার বছরের নাবিলা পানি, টয়লেট আর “আরেকটা প্রশ্ন” নিয়ে প্রায় মাঝরাত পর্যন্ত বারবার উঠে আসত। বাবা-মা টিভির সময় বিকেলে সরিয়ে দিলেন, ঘুমের সময় রাত ৯টা ঠিক করলেন, আর ছবি দিয়ে একটা তালিকা বানালেন: হাতমুখ ধোয়া, দাঁত, টয়লেট, পানি, দুটো গল্প, আদর। যে রাতে উঠে আসত, আব্বু শুধু বলতেন, “এখন ঘুমের সময়। তোমাকে ভালোবাসি,” আর ফিরিয়ে দিয়ে আসতেন। দুই সপ্তাহের মধ্যে বেশিরভাগ রাতে সে সাড়ে ৯টার মধ্যে ঘুমিয়ে পড়তে লাগল।"},"seek_help":{"en":["Your child snores loudly most nights, or stops breathing or gasps in sleep","Your child is very sleepy or irritable in the day despite enough time in bed","Frequent night terrors, sleepwalking or very frightening dreams","Sleep problems are causing great strain on the family","Your child is unwell, in pain or itchy at night"],"bn":["বেশিরভাগ রাতে জোরে নাক ডাকে, বা ঘুমের মধ্যে শ্বাস থেমে যায় বা হাঁসফাঁস করে","বিছানায় যথেষ্ট সময় থাকার পরও দিনে খুব ঘুমঘুম বা খিটখিটে","ঘনঘন নাইট টেরর, ঘুমের মধ্যে হাঁটা বা খুব ভয়ের স্বপ্ন","ঘুমের সমস্যায় পরিবারের ওপর খুব চাপ পড়ছে","রাতে শিশু অসুস্থ, ব্যথায় বা চুলকানিতে কষ্ট পায়"]}}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['bedtime', 'won''t sleep', 'sleep alone', 'night waking', 'routine', 'stalling']::text[], false, 'in_review'::lp_review_status, 5030),
  ('ec-sc-nappies-at-three', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '🧷', '{"en":"My child is three and still in nappies","bn":"তিন বছর হয়ে গেল, এখনো ডায়াপার ছাড়েনি"}'::jsonb, '{"en":"Many children are still learning at three, especially at night. Look for readiness, take the pressure off, check for constipation, and start with small, relaxed steps.","bn":"তিন বছরেও অনেক শিশু শিখছে — বিশেষ করে রাতে। প্রস্তুতির লক্ষণ দেখুন, চাপ সরিয়ে নিন, কোষ্ঠকাঠিন্য আছে কি না দেখুন, আর ছোট, স্বস্তির ধাপে শুরু করুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Children become toilet-ready at different ages. Comparisons with cousins or neighbours (''Her daughter was dry at two!'') add pressure but don''t change your child''s pace. At three, many children are still in nappies some or all of the time, and staying dry at night often comes much later.","bn":"শিশুরা আলাদা আলাদা বয়সে টয়লেটের জন্য তৈরি হয়। চাচাতো ভাই-বোন বা প্রতিবেশীর সাথে তুলনা (“ওর মেয়ে তো দুই বছরেই ছেড়েছে!”) চাপ বাড়ায়, কিন্তু শিশুর গতি বদলায় না। তিন বছরেও অনেক শিশু কিছু সময় বা পুরো সময় ডায়াপার পরে, আর রাতে শুকনো থাকা প্রায়ই অনেক পরে আসে।"},"why":{"en":"Common reasons include not yet being ready, a past bad experience such as painful poos or being scolded, constipation, a busy or changing household, and nappies being so comfortable that there is no reason to change. Less often there is a medical or developmental cause.","bn":"সাধারণ কারণ — এখনো তৈরি না হওয়া, আগে ব্যথাভরা পায়খানা বা বকা খাওয়ার খারাপ অভিজ্ঞতা, কোষ্ঠকাঠিন্য, ব্যস্ত বা বদলাতে থাকা সংসার, আর ডায়াপার এত আরামের যে বদলানোর কারণই নেই। কম ক্ষেত্রে স্বাস্থ্য বা বিকাশজনিত কারণ থাকে।"},"normal":{"en":"It is common for children to finish daytime toilet learning somewhere between about two and a half and four. Night-time dryness can take several more years.","bn":"মোটামুটি আড়াই থেকে চার বছরের মধ্যে দিনের বেলার টয়লেট শেখা শেষ হওয়া সাধারণ। রাতে শুকনো থাকতে আরও কয়েক বছর লাগতে পারে।"},"do_now":{"en":["Stop any pressure, scolding or comparison for a week or two.","Check for constipation: hard, painful or infrequent poos. Offer more water, fruit, vegetables and dal.","Look for readiness signs: staying dry for an hour or two, telling you when wet or dirty, hiding to poo.","Put a potty in the bathroom or play area and let your child see family members using the toilet."],"bn":["এক-দুই সপ্তাহের জন্য সব চাপ, বকা আর তুলনা বন্ধ করুন।","কোষ্ঠকাঠিন্য আছে কি না দেখুন — শক্ত, ব্যথাভরা বা কম কম পায়খানা। বেশি পানি, ফল, শাকসবজি আর ডাল দিন।","প্রস্তুতির লক্ষণ খুঁজুন — এক-দুই ঘণ্টা শুকনো থাকা, ভেজা বা নোংরা হলে জানানো, পায়খানার সময় আড়ালে যাওয়া।","বাথরুমে বা খেলার জায়গায় একটা পটি রাখুন, আর শিশুকে পরিবারের সদস্যদের টয়লেট ব্যবহার দেখতে দিন।"]},"steps":{"en":["Choose a calm period at home without big changes.","Use loose trousers or no trousers at home in the day, so your child feels when they wee.","Offer the potty at regular times: on waking, after meals, before bath and before going out.","If your child poos only in a nappy, let them do it in a nappy while sitting on the potty at first, then gradually loosen and remove the nappy.","Praise every small step, such as sitting or telling you, not only success.","Move to pants in the day when there are more successes than accidents. Keep a nappy at night as long as needed.","Ask everyone who cares for your child to follow the same simple routine and words."],"bn":["বড় কোনো পরিবর্তন নেই এমন শান্ত একটা সময় বেছে নিন।","দিনে বাসায় ঢিলা প্যান্ট বা প্যান্ট ছাড়া রাখুন, যাতে প্রস্রাব হলে শিশু টের পায়।","নির্দিষ্ট সময়ে পটিতে বসতে বলুন — ঘুম থেকে উঠে, খাওয়ার পরে, গোসলের আগে, বাইরে যাওয়ার আগে।","শিশু শুধু ডায়াপারে পায়খানা করলে প্রথমে ডায়াপার পরেই পটিতে বসে করতে দিন, তারপর ধীরে ধীরে ডায়াপার ঢিলা করে খুলে ফেলুন।","শুধু সফলতা নয়, প্রতিটি ছোট ধাপের প্রশংসা করুন — বসা বা জানানোও।","দুর্ঘটনার চেয়ে সফলতা বেশি হলে দিনে প্যান্ট পরান। রাতে যতদিন দরকার ডায়াপার রাখুন।","যারা শিশুকে দেখাশোনা করেন, সবাইকে একই সহজ রুটিন আর শব্দ মানতে বলুন।"]},"avoid":{"en":["Scolding, smacking or shaming for accidents","Making your child sit on the potty for a long time or against their will","Comparing them with other children in front of them","Starting during a new baby''s arrival, a move or illness","Holding back drinks to prevent accidents"],"bn":["দুর্ঘটনায় বকা, মারা বা লজ্জা দেওয়া","অনেকক্ষণ বা জোর করে পটিতে বসিয়ে রাখা","শিশুর সামনে অন্য শিশুর সাথে তুলনা","নতুন ভাই-বোন আসা, বাসা বদল বা অসুখের সময় শুরু করা","দুর্ঘটনা ঠেকাতে পানি কম খাওয়ানো"]},"example":{"en":"Ishan was three and a half and screamed whenever the potty came out. His mother noticed his poos were hard and he hid to push. She stopped all potty talk for two weeks and gave more water, papaya and dal. Once his poos were softer, she let him poo in his nappy while sitting on the potty. A few weeks later he agreed to try without the nappy, and was very proud.","bn":"ঈশানের বয়স সাড়ে তিন, পটি দেখলেই চিৎকার করত। আম্মু খেয়াল করলেন ওর পায়খানা শক্ত, আর আড়ালে গিয়ে চাপ দেয়। তিনি দুই সপ্তাহ পটির কথাই বন্ধ রাখলেন, আর বেশি পানি, পেঁপে আর ডাল দিলেন। পায়খানা নরম হলে ওকে ডায়াপার পরেই পটিতে বসে পায়খানা করতে দিলেন। কয়েক সপ্তাহ পরে সে ডায়াপার ছাড়া চেষ্টা করতে রাজি হলো — আর খুব গর্বিত হলো।"},"seek_help":{"en":["Your child is well past three and shows no readiness signs at all","Poos are often hard, painful, or there is soiling of pants with liquid poo","There are also concerns about speech, understanding or other development","Your child seems never to be dry, even for short periods","Any of the warning signs below"],"bn":["তিন বছর অনেকটা পার হয়েছে, কিন্তু প্রস্তুতির কোনো লক্ষণই নেই","প্রায়ই শক্ত বা ব্যথাভরা পায়খানা, বা প্যান্টে পাতলা পায়খানা লেগে থাকে","কথা বলা, বোঝা বা অন্য বিকাশ নিয়েও চিন্তা আছে","শিশু অল্প সময়ের জন্যও কখনো শুকনো থাকে না বলে মনে হয়","নিচের কোনো সতর্ক লক্ষণ"]},"warning_signs":{"en":["Pain, burning or crying when weeing","Blood in wee or poo","Fever with wetting or tummy pain","A constantly dribbling wee or a very weak stream","Very swollen tummy or vomiting with constipation"],"bn":["প্রস্রাবের সময় ব্যথা, জ্বালা বা কান্না","প্রস্রাব বা পায়খানায় রক্ত","ভেজানোর সাথে জ্বর বা পেটব্যথা","সারাক্ষণ ফোঁটা ফোঁটা প্রস্রাব, বা খুব দুর্বল ধারা","কোষ্ঠকাঠিন্যের সাথে পেট খুব ফুলে যাওয়া বা বমি"]}}'::jsonb, 3, 1096, 1461, '{}'::text[], 'any', ARRAY['nappies', 'diapers', 'toilet training', 'potty refusal', 'constipation', 'three years']::text[], false, 'in_review'::lp_review_status, 5031),
  ('ec-sc-toilet-accidents', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '💧', '{"en":"Accidents again after being toilet trained","bn":"টয়লেট শেখার পরও আবার কাপড় ভেজাচ্ছে"}'::jsonb, '{"en":"Going backwards for a while is common, often after a change, a busy day or constipation. Stay calm, look for the cause, and go back to simple reminders.","bn":"কিছুদিনের জন্য পিছিয়ে যাওয়া সাধারণ — প্রায়ই কোনো পরিবর্তন, ব্যস্ত দিন বা কোষ্ঠকাঠিন্যের পরে। শান্ত থাকুন, কারণ খুঁজুন, আর সহজভাবে মনে করিয়ে দেওয়ায় ফিরে যান।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"A child who has learned to use the toilet can still have accidents for months. Sometimes they are too busy playing to notice, sometimes something has upset them, and sometimes there is a physical cause.","bn":"টয়লেট শিখে ফেলা শিশুরও মাসের পর মাস মাঝে মাঝে দুর্ঘটনা হতে পারে। কখনো খেলায় এত মগ্ন যে টের পায় না, কখনো কিছু নিয়ে মন খারাপ, আর কখনো শারীরিক কোনো কারণ থাকে।"},"why":{"en":"Common causes are being absorbed in play, a new baby, starting pre-school, a move or family stress, constipation (a full bowel presses on the bladder), a urine infection, and being scolded for earlier accidents.","bn":"সাধারণ কারণ — খেলায় ডুবে থাকা, নতুন ভাই-বোন, প্রি-স্কুল শুরু, বাসা বদল বা পরিবারে চাপ, কোষ্ঠকাঠিন্য (ভরা অন্ত্র মূত্রথলিতে চাপ দেয়), প্রস্রাবের সংক্রমণ, আর আগের দুর্ঘটনায় বকা খাওয়া।"},"normal":{"en":"Occasional daytime accidents are common for months after training. Night-time wetting is very common in children under five and is not a sign of laziness.","bn":"শেখার পর কয়েক মাস পর্যন্ত দিনে মাঝে মাঝে দুর্ঘটনা সাধারণ। পাঁচ বছরের কম শিশুদের রাতে বিছানা ভেজানো খুব সাধারণ — এটা অলসতার লক্ষণ নয়।"},"do_now":{"en":["Clean up calmly and matter-of-factly: ''The wee came out. Let''s change and try the toilet next time.''","Let your child help a little, such as putting wet clothes in the bucket, without making it a punishment.","Remind them to use the toilet at regular times, especially before play, outings and sleep.","Check for constipation and for signs of a urine infection."],"bn":["শান্তভাবে, স্বাভাবিক গলায় পরিষ্কার করুন: “প্রস্রাব বের হয়ে গেছে। চলো বদলাই, পরের বার টয়লেটে চেষ্টা করব।”","শিশুকে একটু সাহায্য করতে দিন — যেমন ভেজা কাপড় বালতিতে রাখা — শাস্তি হিসেবে নয়।","নির্দিষ্ট সময়ে, বিশেষ করে খেলা, বাইরে যাওয়া আর ঘুমের আগে টয়লেটে যেতে মনে করিয়ে দিন।","কোষ্ঠকাঠিন্য আর প্রস্রাবের সংক্রমণের লক্ষণ আছে কি না দেখুন।"]},"steps":{"en":["Think about what has changed recently and give extra attention and comfort.","Build toilet trips into the daily routine rather than asking ''Do you need to go?''","Offer drinks regularly through the day, and fewer large drinks right before bed.","Treat constipation with water, fruit, vegetables and activity; see a health worker if it continues.","Dress your child in clothes that are easy to pull down quickly.","Keep spare clothes when going out.","Praise dry times and successful toilet trips."],"bn":["সম্প্রতি কী বদলেছে ভাবুন, আর বাড়তি মনোযোগ ও আদর দিন।","“টয়লেটে যাবে?” জিজ্ঞেস না করে টয়লেটে যাওয়াকে রোজকার রুটিনের অংশ বানান।","সারাদিন নিয়মিত পানি দিন, আর ঘুমের ঠিক আগে বেশি পানি কম দিন।","পানি, ফল, শাকসবজি আর নড়াচড়া দিয়ে কোষ্ঠকাঠিন্য সারান; না সারলে স্বাস্থ্যকর্মীকে দেখান।","এমন জামা পরান যা তাড়াতাড়ি নামানো যায়।","বাইরে গেলে বাড়তি জামা সাথে রাখুন।","শুকনো থাকার সময় আর টয়লেট ব্যবহারের প্রশংসা করুন।"]},"avoid":{"en":["Shouting, smacking or shaming, which makes children anxious and hold on","Putting a child back in nappies as a punishment","Telling relatives about accidents in front of the child","Cutting down water during the day"],"bn":["চিৎকার, মারা বা লজ্জা দেওয়া — এতে শিশু দুশ্চিন্তায় চেপে রাখে","শাস্তি হিসেবে আবার ডায়াপার পরানো","শিশুর সামনে আত্মীয়দের কাছে দুর্ঘটনার কথা বলা","দিনে পানি কম খাওয়ানো"]},"example":{"en":"Tasnim, aged three, had been dry for months, but started wetting after her baby brother was born. Her parents did not scold. Abbu began a special ''big girl time'' with her every evening, and they set toilet trips before play and before going out. Within a few weeks the accidents were rare again.","bn":"তিন বছরের তাসনিম কয়েক মাস ধরে শুকনো থাকত, কিন্তু ছোট ভাই জন্মের পর আবার ভেজাতে শুরু করল। বাবা-মা বকা দিলেন না। আব্বু প্রতি সন্ধ্যায় ওর সাথে ‘বড় আপুর সময়’ কাটাতে শুরু করলেন, আর খেলা ও বাইরে যাওয়ার আগে টয়লেটে যাওয়ার নিয়ম করলেন। কয়েক সপ্তাহের মধ্যে দুর্ঘটনা আবার কমে গেল।"},"seek_help":{"en":["Accidents start suddenly after a long dry period with no clear reason","Your child wees much more often than before, or is very thirsty","Constipation does not improve","Accidents continue despite calm support for several weeks","Any of the warning signs below"],"bn":["অনেক দিন শুকনো থাকার পর কোনো স্পষ্ট কারণ ছাড়া হঠাৎ দুর্ঘটনা শুরু","আগের চেয়ে অনেক বেশি বার প্রস্রাব, বা খুব পিপাসা","কোষ্ঠকাঠিন্য ভালো হচ্ছে না","কয়েক সপ্তাহ শান্ত সহায়তার পরও দুর্ঘটনা চলছে","নিচের কোনো সতর্ক লক্ষণ"]},"warning_signs":{"en":["Pain, burning or crying when weeing","Fever, tummy pain or back pain","Blood in the wee, or wee that is cloudy or smells very strong","Very thirsty, weeing a lot and losing weight","Signs that someone may have hurt the child, such as pain, injury or fear around the private parts"],"bn":["প্রস্রাবের সময় ব্যথা, জ্বালা বা কান্না","জ্বর, পেটব্যথা বা পিঠে ব্যথা","প্রস্রাবে রক্ত, ঘোলা প্রস্রাব বা খুব কড়া গন্ধ","খুব পিপাসা, অনেক প্রস্রাব আর ওজন কমা","কেউ শিশুকে আঘাত করেছে এমন লক্ষণ — গোপনাঙ্গে ব্যথা, ক্ষত বা ভয়"]}}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['accidents', 'wetting', 'toilet training', 'regression', 'urine infection', 'constipation']::text[], false, 'in_review'::lp_review_status, 5032),
  ('ec-sc-fears-dark-strangers', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '🌑', '{"en":"Afraid of the dark or of strangers","bn":"অন্ধকার বা অচেনা মানুষকে ভয় পায়"}'::jsonb, '{"en":"Fears of the dark, monsters, loud noises or new people are a normal part of a growing imagination. Take the fear seriously, comfort, and help your child face it in small, safe steps.","bn":"অন্ধকার, দৈত্য, জোরে শব্দ বা নতুন মানুষের ভয় — বাড়তে থাকা কল্পনাশক্তিরই স্বাভাবিক অংশ। ভয়টাকে গুরুত্ব দিন, সান্ত্বনা দিন, আর ছোট, নিরাপদ ধাপে ভয়ের মুখোমুখি হতে সাহায্য করুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Between two and four, children''s imagination grows fast, but they can''t yet tell clearly what is real. A shadow can become a monster. Being shy or clingy with new people is also common, especially in a busy home with many visitors.","bn":"দুই থেকে চার বছরে শিশুর কল্পনা দ্রুত বাড়ে, কিন্তু কোনটা সত্যি আর কোনটা নয়, সেটা এখনো পরিষ্কার বোঝে না। একটা ছায়াও দৈত্য হয়ে যেতে পারে। নতুন মানুষের সামনে লাজুক হওয়া বা আঁকড়ে ধরাও সাধারণ — বিশেষ করে অনেক মেহমান আসা-যাওয়ার ব্যস্ত ঘরে।"},"why":{"en":"Fears can grow after scary stories or videos, threats used to make children behave (''The jinn will come'', ''The chhele-dhora will take you''), a frightening event, or big changes at home. Some children are simply more cautious by nature.","bn":"ভয় বাড়তে পারে ভয়ের গল্প বা ভিডিও দেখার পরে, বাধ্য করাতে ভয় দেখানোর পরে (“জিন আসবে”, “ছেলেধরা নিয়ে যাবে”), ভয়ংকর কোনো ঘটনার পরে, বা ঘরে বড় পরিবর্তনের পরে। কিছু শিশু স্বভাবগতভাবেই বেশি সাবধানী।"},"normal":{"en":"Most young children have some fears, and they usually fade with time, comfort and gentle experience. Being wary of strangers is healthy; children don''t need to like everyone straight away.","bn":"বেশিরভাগ ছোট শিশুর কিছু না কিছু ভয় থাকে, আর সময়, আদর আর নরম অভিজ্ঞতায় সাধারণত কমে যায়। অচেনা মানুষের ব্যাপারে সতর্ক থাকা স্বাস্থ্যকর; সবাইকে সাথে সাথে পছন্দ করতে হবে, এমন নয়।"},"do_now":{"en":["Listen and name the fear: ''You''re scared of the dark corner. I''m here.''","Don''t laugh at the fear or say ''Don''t be silly''.","For the dark: use a small night light, leave the door open, and check the room together.","With new people: let your child stay close to you and warm up slowly. Don''t force them to go to someone''s lap or to hug.","Give a comfort object such as a soft toy or a cloth that smells of you."],"bn":["শুনুন আর ভয়ের নাম দিন: “তুমি ওই অন্ধকার কোণটাকে ভয় পাচ্ছ। আমি আছি।”","ভয় নিয়ে হাসবেন না, বা “বোকার মতো কথা বোলো না” বলবেন না।","অন্ধকারের জন্য: ছোট একটা মৃদু বাতি জ্বালিয়ে রাখুন, দরজা খোলা রাখুন, একসাথে ঘরটা দেখে নিন।","নতুন মানুষের সাথে: শিশুকে আপনার কাছে থাকতে দিন, ধীরে ধীরে সহজ হতে দিন। কারও কোলে যেতে বা জড়িয়ে ধরতে জোর করবেন না।","আরামের একটা জিনিস দিন — নরম খেলনা বা আপনার গন্ধমাখা একটা কাপড়।"]},"steps":{"en":["Play games that make the dark fun: torch games, shadow puppets, hide-and-seek in a dim room together.","Read books about brave characters who feel scared.","Before visitors arrive, tell your child who is coming and let them watch from your side first.","Practise greetings in pretend play: the doll says hello to a new friend.","Praise brave steps, however small: ''You said hello to Khalu today!''","Keep scary videos, news and frightening stories away from your child.","Teach simple body safety: their body belongs to them, and they can always tell you if something feels wrong."],"bn":["অন্ধকারকে মজার করে তোলে এমন খেলা খেলুন — টর্চের খেলা, হাতের ছায়ায় পশুপাখি, আবছা ঘরে একসাথে লুকোচুরি।","ভয় পেয়েও সাহসী হয় এমন চরিত্রের বই পড়ুন।","মেহমান আসার আগে শিশুকে বলুন কে আসছেন, আর প্রথমে আপনার পাশ থেকে দেখতে দিন।","ভান-খেলায় সম্ভাষণের অনুশীলন করুন — পুতুল নতুন বন্ধুকে সালাম দিচ্ছে।","ছোট হলেও সাহসের ধাপের প্রশংসা করুন: “আজ তুমি খালুকে সালাম দিলে!”","ভয়ের ভিডিও, খবর আর ভয়ংকর গল্প শিশুর কাছ থেকে দূরে রাখুন।","শরীরের নিরাপত্তার সহজ কথা শেখান: ওর শরীর ওর নিজের, আর কিছু খারাপ লাগলে সবসময় আপনাকে বলতে পারবে।"]},"avoid":{"en":["Using fear to control behaviour: ghosts, jinn, police, doctors, injections or ''the beggar will take you''","Forcing your child to sleep alone in the dark to ''toughen them up''","Pushing a shy child onto relatives or calling them ''rude'' for not greeting","Letting older children tease or frighten them"],"bn":["আচরণ নিয়ন্ত্রণে ভয় দেখানো — ভূত, জিন, পুলিশ, ডাক্তার, ইনজেকশন বা “ছেলেধরা নিয়ে যাবে”","‘সাহসী বানাতে’ অন্ধকারে একা ঘুমাতে জোর করা","লাজুক শিশুকে জোর করে আত্মীয়ের কাছে ঠেলে দেওয়া, বা সালাম না দিলে ‘বেয়াদব’ বলা","বড় বাচ্চাদের ওকে খ্যাপাতে বা ভয় দেখাতে দেওয়া"]},"example":{"en":"After a cousin told him about a bhoot in the bathroom, three-year-old Rayan refused to go there at night. His mother didn''t laugh. She said, ''That story scared you. There is no bhoot. Let''s check together.'' They took a torch and looked in every corner, and she put a small light in the corridor. For a week she walked with him; then she stood at the door; soon he went on his own.","bn":"এক কাজিন বাথরুমে ভূতের গল্প বলার পর তিন বছরের রায়ান রাতে বাথরুমে যেতে চাইত না। আম্মু হাসলেন না। বললেন, “গল্পটা শুনে তুমি ভয় পেয়েছ। ভূত নেই। চলো একসাথে দেখে আসি।” টর্চ নিয়ে দুজনে প্রতিটি কোণ দেখলেন, আর আম্মু বারান্দায় ছোট একটা বাতি লাগিয়ে দিলেন। এক সপ্তাহ তিনি সাথে গেলেন; তারপর দরজায় দাঁড়িয়ে থাকলেন; শিগগিরই রায়ান একাই যেতে লাগল।"},"seek_help":{"en":["Fears are so strong that they stop your child eating, sleeping, playing or leaving the house","A new, intense fear appears suddenly, especially of a particular person or place","Your child has frequent nightmares, panic or wakes screaming often","Your child has been through or seen something frightening, such as violence or an accident","You notice signs that someone may have harmed your child"],"bn":["ভয় এত বেশি যে শিশু খেতে, ঘুমাতে, খেলতে বা ঘর থেকে বের হতে পারে না","হঠাৎ নতুন, তীব্র ভয় — বিশেষ করে নির্দিষ্ট কোনো মানুষ বা জায়গা নিয়ে","ঘনঘন দুঃস্বপ্ন, আতঙ্ক, বা প্রায়ই চিৎকার করে জেগে ওঠা","শিশু ভয়ংকর কিছুর মধ্য দিয়ে গেছে বা দেখেছে — যেমন সহিংসতা বা দুর্ঘটনা","কেউ শিশুর ক্ষতি করেছে এমন কোনো লক্ষণ চোখে পড়লে"]}}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['fear', 'dark', 'strangers', 'shy', 'nightmares', 'monsters', 'anxiety']::text[], false, 'in_review'::lp_review_status, 5033),
  ('ec-sc-stammering', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '💬', '{"en":"My child stammers or repeats words","bn":"শিশু তোতলায় বা শব্দ বারবার বলে"}'::jsonb, '{"en":"Many children repeat sounds or words while their language grows fast. Give them time, listen calmly and don''t finish their sentences. If it lasts, gets worse or upsets your child, ask for a speech assessment.","bn":"ভাষা দ্রুত বাড়ার সময় অনেক শিশু ধ্বনি বা শব্দ বারবার বলে। সময় দিন, শান্তভাবে শুনুন, বাক্য শেষ করে দেবেন না। দীর্ঘদিন চললে, বাড়লে বা শিশু কষ্ট পেলে কথা বলার মূল্যায়ন করান।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Between two and five, children''s thoughts often run ahead of their speech. Many go through a stage of repeating whole words or phrases (''I-I-I want... I want milk''), stretching sounds or pausing. This is often called normal non-fluency, and many children grow out of it.","bn":"দুই থেকে পাঁচ বছরে শিশুর চিন্তা প্রায়ই মুখের কথার আগে ছোটে। অনেকে একটা সময় পুরো শব্দ বা বাক্যাংশ বারবার বলে (“আমি-আমি-আমি চাই… আমি দুধ চাই”), ধ্বনি টেনে বলে বা থেমে যায়। একে প্রায়ই স্বাভাবিক অসাবলীলতা বলা হয়, আর অনেক শিশু বড় হতে হতে এটা কাটিয়ে ওঠে।"},"why":{"en":"It is linked to how the brain is developing speech, not to bad parenting, nervousness or copying. It can be more noticeable when the child is excited, tired, rushed or has a lot to say. Stammering sometimes runs in families.","bn":"এটা মস্তিষ্কে কথা বলার ক্ষমতা কীভাবে গড়ে উঠছে তার সাথে সম্পর্কিত — খারাপ লালনপালন, ভয় বা নকল করার কারণে নয়। শিশু উত্তেজিত, ক্লান্ত বা তাড়াহুড়োয় থাকলে, বা অনেক কিছু বলার থাকলে বেশি বোঝা যায়। তোতলামি কখনো কখনো পরিবারে থাকে।"},"normal":{"en":"Easy repetitions of whole words or phrases, which come and go, are common at this age. Many children who start to stammer in early childhood stop without treatment, but some need help, and early support works best.","bn":"পুরো শব্দ বা বাক্যাংশ সহজভাবে বারবার বলা, যা আসে আবার চলে যায় — এই বয়সে সাধারণ। ছোটবেলায় তোতলামি শুরু হওয়া অনেক শিশু চিকিৎসা ছাড়াই ঠিক হয়ে যায়, তবে কারও কারও সাহায্য লাগে, আর আগে সহায়তা শুরু হলে সবচেয়ে ভালো কাজ করে।"},"do_now":{"en":["Stay calm and keep natural eye contact while your child speaks.","Wait patiently. Let them finish, even if it takes time.","Respond to what they said, not how they said it.","Speak to your child a little more slowly yourself, with pauses.","Don''t finish their words or sentences for them."],"bn":["শিশু কথা বলার সময় শান্ত থাকুন, স্বাভাবিকভাবে চোখে চোখ রাখুন।","ধৈর্য নিয়ে অপেক্ষা করুন। সময় লাগলেও শেষ করতে দিন।","কীভাবে বলল তা নয়, কী বলল তার উত্তর দিন।","নিজে শিশুর সাথে একটু ধীরে, থেমে থেমে কথা বলুন।","ওর শব্দ বা বাক্য আপনি শেষ করে দেবেন না।"]},"steps":{"en":["Set aside a few minutes of calm one-to-one time each day for relaxed talk and play.","Take turns talking at family meals so no one has to rush or compete to speak.","Ask fewer quick questions; comment instead: ''That''s a big tower you built.''","Make sure brothers, sisters and relatives don''t tease, imitate or hurry the child.","If your child seems aware or upset, acknowledge it kindly: ''Some words are bumpy today. That''s okay. I''m listening.''","Keep a simple note of when it happens and how it changes over weeks."],"bn":["প্রতিদিন কয়েক মিনিট শান্ত, শুধু দুজনের সময় রাখুন — আরামে কথা আর খেলা।","পরিবারের খাওয়ার সময় পালা করে কথা বলুন, যাতে কাউকে তাড়াহুড়ো বা প্রতিযোগিতা করে বলতে না হয়।","দ্রুত প্রশ্ন কম করুন; বরং মন্তব্য করুন: “তুমি তো বিশাল একটা টাওয়ার বানিয়েছ।”","ভাই-বোন আর আত্মীয়রা যেন খ্যাপায় না, নকল করে না, তাড়া দেয় না — খেয়াল রাখুন।","শিশু নিজে টের পেলে বা মন খারাপ করলে নরমভাবে স্বীকার করুন: “আজ কিছু শব্দ একটু আটকে যাচ্ছে। কোনো সমস্যা নেই। আমি শুনছি।”","কখন হয় আর কয়েক সপ্তাহে কীভাবে বদলায়, ছোট করে লিখে রাখুন।"]},"avoid":{"en":["''Slow down'', ''Take a breath'', ''Say it again properly''","Scolding, punishing, or laughing at the stammer","Asking the child to speak or perform in front of guests","Old remedies that frighten or hurt the child","Assuming it will definitely go away and waiting a long time if it is not improving"],"bn":["“আস্তে বলো”, “শ্বাস নিয়ে বলো”, “ঠিক করে আবার বলো”","তোতলানোর জন্য বকা, শাস্তি বা হাসাহাসি","মেহমানদের সামনে কথা বলতে বা কিছু করে দেখাতে বলা","ভয় দেখানো বা ব্যথা দেওয়া পুরোনো টোটকা","ভালো না হলেও ‘নিজে নিজে সেরে যাবে’ ধরে নিয়ে অনেক দিন অপেক্ষা করা"]},"example":{"en":"Three-year-old Zara began saying ''Ammu, Ammu, Ammu, can I…'' many times a day. Her grandmother kept saying ''Speak properly!'' The family agreed instead to stop, look at her and wait. Abbu began 10 minutes of quiet block play with her every evening. Over the next few months the repeating became less frequent. They had planned to see a speech therapist if it had not improved.","bn":"তিন বছরের জারা দিনে অনেকবার বলতে লাগল, “আম্মু, আম্মু, আম্মু, আমি কি…”। দাদু বারবার বলতেন, “ঠিক করে বলো!” পরিবার ঠিক করল এর বদলে থামবে, ওর দিকে তাকাবে আর অপেক্ষা করবে। আব্বু প্রতি সন্ধ্যায় ওর সাথে ১০ মিনিট চুপচাপ ব্লক নিয়ে খেলতে শুরু করলেন। পরের কয়েক মাসে বারবার বলা কমে এল। ভালো না হলে তাঁরা স্পিচ থেরাপিস্টের কাছে যাওয়ার পরিকল্পনাও করে রেখেছিলেন।"},"seek_help":{"en":["The stammering has lasted more than about six months, or is getting worse","Your child shows struggle or tension: blinking, facial tension, getting stuck with no sound coming out","Your child is upset about talking, avoids speaking or says ''I can''t talk''","There is a family history of stammering that continued into adulthood","There are other concerns about speech, understanding or hearing","You are worried; a speech and language therapist can assess at any age"],"bn":["তোতলামি মোটামুটি ছয় মাসের বেশি চলছে, বা বাড়ছে","শিশুর মধ্যে চেষ্টা বা টান দেখা যায় — চোখ পিটপিট, মুখের পেশি শক্ত, আটকে যাওয়া অথচ কোনো শব্দ বের হচ্ছে না","কথা বলা নিয়ে শিশু কষ্ট পায়, কথা এড়িয়ে চলে, বা বলে “আমি কথা বলতে পারি না”","পরিবারে কারও তোতলামি বড় হয়েও থেকে গেছে","কথা বলা, বোঝা বা শোনা নিয়ে অন্য চিন্তাও আছে","আপনার চিন্তা হচ্ছে — যেকোনো বয়সে স্পিচ অ্যান্ড ল্যাঙ্গুয়েজ থেরাপিস্ট মূল্যায়ন করতে পারেন"]}}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['stammering', 'stuttering', 'repeating words', 'speech', 'fluency', 'tolotlano']::text[], false, 'in_review'::lp_review_status, 5034),
  ('ec-sc-jealous-of-baby', 'scenario', 'scientific', 'family', 'routine', 'consensus', '🍼', '{"en":"My child is jealous of the new baby","bn":"নতুন বাবুকে দেখে বড়টা হিংসা করছে"}'::jsonb, '{"en":"Jealousy of a new sibling is normal. Accept the feelings, protect the baby, give your older child special time every day, and let the father and family step up.","bn":"নতুন ভাই-বোনকে হিংসা করা স্বাভাবিক। অনুভূতি মেনে নিন, বাবুকে নিরাপদ রাখুন, বড়টাকে প্রতিদিন আলাদা সময় দিন, আর বাবা ও পরিবারকে এগিয়ে আসতে দিন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Your older child may say ''Send the baby back'', act like a baby, cling to you, have more tantrums, or be rough with the baby. Underneath is a simple worry: ''Am I still loved?''","bn":"বড় সন্তান বলতে পারে “বাবুকে ফেরত দিয়ে আসো”, বাবুর মতো আচরণ করতে পারে, আপনাকে আঁকড়ে থাকতে পারে, বেশি রেগে কাঁদতে পারে, বা বাবুর সাথে রুক্ষ হতে পারে। এর নিচে একটা সহজ দুশ্চিন্তা: “আমাকে কি এখনো ভালোবাসে?”"},"why":{"en":"Overnight, the mother''s time, lap and attention are shared, visitors focus on the baby, and the older child is suddenly called ''big''. At two to four they don''t have the words to explain this loss.","bn":"রাতারাতি মায়ের সময়, কোল আর মনোযোগ ভাগ হয়ে যায়, মেহমানেরা বাবুকে ঘিরে থাকেন, আর বড়টাকে হঠাৎ ‘বড়’ বলা শুরু হয়। দুই থেকে চার বছর বয়সে এই হারানোর অনুভূতি বোঝানোর শব্দ তার নেই।"},"normal":{"en":"Jealousy, going backwards in toilet use or sleep, and more clinginess are very common in the first months after a new baby, and usually settle with time and attention.","bn":"নতুন বাবু আসার প্রথম কয়েক মাসে হিংসা, টয়লেট বা ঘুমে পিছিয়ে যাওয়া আর বেশি আঁকড়ে থাকা খুব সাধারণ, আর সময় ও মনোযোগে সাধারণত ঠিক হয়ে যায়।"},"do_now":{"en":["Never leave your older child alone with the baby.","If they are rough, calmly move their hands and say, ''I won''t let you hurt the baby. Show me gentle hands.''","Name the feeling without blame: ''It''s hard sharing Ammu. You wish it was just you sometimes.''","Give a hug and some one-to-one attention soon after, so the message is ''you are still loved''.","Accept baby-like behaviour calmly for now; a cuddle or a carry is fine."],"bn":["বড়টাকে কখনো বাবুর সাথে একা রাখবেন না।","রুক্ষ হলে শান্তভাবে হাত সরিয়ে দিয়ে বলুন: “বাবুকে ব্যথা দিতে দেব না। আমাকে দেখাও তো, নরম হাত কেমন।”","দোষ না দিয়ে অনুভূতির নাম দিন: “আম্মুকে ভাগ করতে কষ্ট লাগে, তাই না? মাঝে মাঝে ইচ্ছে করে আম্মু শুধু তোমার থাকুক।”","এরপর একটু জড়িয়ে ধরুন আর আলাদা মনোযোগ দিন, যাতে বার্তা যায় ‘তোমাকে এখনো ভালোবাসি’।","আপাতত বাবুর মতো আচরণ শান্তভাবে মেনে নিন; একটু আদর বা কোলে নেওয়া ঠিক আছে।"]},"steps":{"en":["Give 10–15 minutes of special time every day with each parent, without the baby, doing what your child chooses.","While feeding the baby, keep a ''feeding time box'' of books or toys for the older child, or read to them.","Ask visitors to greet the older child first, and keep small gifts ready for them.","Give them proud jobs: fetching a nappy, choosing the baby''s clothes, singing to the baby.","Talk about when they were a baby, with photos.","Let the father take over the older child''s bath, bedtime or outings while the mother rests.","Praise gentle moments with the baby, and their ''big'' skills."],"bn":["প্রতিদিন বাবা-মা দুজনেই বাবুকে ছাড়া ১০–১৫ মিনিট বড়টার সাথে আলাদা সময় কাটান — ও যা খেলতে চায়।","বাবুকে খাওয়ানোর সময় বড়টার জন্য বই বা খেলনা ভরা একটা ‘খাওয়ার সময়ের বাক্স’ রাখুন, বা ওকে গল্প পড়ে শোনান।","মেহমানদের অনুরোধ করুন আগে বড়টার সাথে কথা বলতে, আর ওর জন্য ছোট উপহার রেখে দিন।","গর্বের কাজ দিন — ডায়াপার এনে দেওয়া, বাবুর জামা বাছা, বাবুকে গান শোনানো।","ছবি দেখিয়ে ওর নিজের ছোটবেলার গল্প বলুন।","মা যখন বিশ্রাম নেবেন, বাবা বড়টার গোসল, ঘুম পাড়ানো বা বেড়াতে নেওয়ার দায়িত্ব নিন।","বাবুর সাথে নরম মুহূর্তগুলোর আর ওর ‘বড়’ দক্ষতাগুলোর প্রশংসা করুন।"]},"avoid":{"en":["Punishing your child for saying they don''t like the baby","''You''re big now, stop acting like a baby''","Comparing: ''Look how good the baby is''","Relatives teasing: ''Now no one will love you''","Big changes for the older child right now, such as a new bed or starting school, if they can wait"],"bn":["“বাবুকে ভালো লাগে না” বলার জন্য শাস্তি দেওয়া","“তুমি এখন বড় হয়েছ, বাবুর মতো কোরো না”","তুলনা: “দেখো, বাবু কত লক্ষ্মী”","আত্মীয়দের খ্যাপানো: “এখন তো আর তোমাকে কেউ আদর করবে না”","অপেক্ষা করা গেলে এই সময়ে বড়টার জীবনে বড় পরিবর্তন — নতুন বিছানা বা স্কুল শুরু"]},"example":{"en":"When baby Saba came home, two-and-a-half-year-old Rohan started pinching her and asking for a bottle. His father began taking him to the tea stall and the field every afternoon, ''just the two of us''. Ammu read to Rohan while breastfeeding Saba. When Rohan asked for a bottle, they gave him a cup of milk with a cuddle, without teasing. After a couple of months he was proudly singing to his sister.","bn":"ছোট্ট সাবা বাসায় আসার পর আড়াই বছরের রোহান ওকে চিমটি কাটতে আর ফিডার চাইতে শুরু করল। আব্বু প্রতি বিকেলে ‘শুধু আমরা দুজন’ বলে ওকে চায়ের দোকানে আর মাঠে নিয়ে যেতে লাগলেন। সাবাকে বুকের দুধ খাওয়ানোর সময় আম্মু রোহানকে গল্প পড়ে শোনাতেন। রোহান ফিডার চাইলে খ্যাপানো ছাড়া আদর করে কাপে দুধ দিতেন। মাস দুয়েক পরে সে গর্ব করে বোনকে গান শোনাত।"},"seek_help":{"en":["Your child repeatedly tries to hurt the baby despite supervision and support","Distress is very strong or continues for many months","Your child stops eating, sleeping or playing well, or seems very withdrawn","The mother is struggling with low mood, anxiety or exhaustion after the birth"],"bn":["নজর আর সহায়তার পরও শিশু বারবার বাবুকে আঘাত করার চেষ্টা করে","কষ্ট খুব তীব্র, বা অনেক মাস ধরে চলছে","শিশু ঠিকমতো খায় না, ঘুমায় না, খেলে না, বা খুব চুপচাপ গুটিয়ে গেছে","প্রসবের পর মা মন খারাপ, দুশ্চিন্তা বা ক্লান্তিতে ভুগছেন"]}}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['jealousy', 'new baby', 'sibling', 'regression', 'attention', 'big brother', 'big sister']::text[], false, 'in_review'::lp_review_status, 5035),
  ('ec-sc-wont-share', 'scenario', 'scientific', 'shared', 'educational', 'consensus', '🧸', '{"en":"My child won''t share","bn":"শিশু কিছুই ভাগ করতে চায় না"}'::jsonb, '{"en":"Not wanting to share is normal at two and three. Teach turn-taking, prepare before visitors, and show sharing yourself, rather than forcing it.","bn":"দুই-তিন বছর বয়সে ভাগ করতে না চাওয়া স্বাভাবিক। জোর না করে পালা করে খেলা শেখান, মেহমান আসার আগে প্রস্তুতি নিন, আর নিজে ভাগ করে দেখান।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"To a two-year-old, ''mine'' feels very important; they are just learning that they are a separate person with their own things. Understanding that a friend will give the toy back takes time and experience.","bn":"দুই বছরের শিশুর কাছে ‘আমার’ খুব গুরুত্বপূর্ণ — সে সবে শিখছে যে সে আলাদা একজন মানুষ, তার নিজের জিনিস আছে। বন্ধু খেলনাটা ফেরত দেবে — এটা বুঝতে সময় আর অভিজ্ঞতা লাগে।"},"why":{"en":"Young children can''t yet easily see things from another child''s point of view, and waiting is hard. Sharing is harder when the toy is special, when the child is tired, or when an adult takes the toy away to give to someone else.","bn":"ছোট শিশু এখনো সহজে অন্য শিশুর দিক থেকে ভাবতে পারে না, আর অপেক্ষা করা কঠিন। খেলনাটা বিশেষ হলে, শিশু ক্লান্ত থাকলে, বা বড় কেউ হাত থেকে নিয়ে অন্যকে দিয়ে দিলে ভাগ করা আরও কঠিন হয়।"},"normal":{"en":"Sharing gradually becomes easier between three and four, as children start to play together and take turns. Even older children don''t share everything, and that is okay.","bn":"তিন থেকে চার বছরে শিশুরা একসাথে খেলতে আর পালা নিতে শুরু করলে ভাগ করা ধীরে ধীরে সহজ হয়। বড় শিশুরাও সবকিছু ভাগ করে না — সেটাও ঠিক আছে।"},"do_now":{"en":["Stay close and calm when a tug-of-war starts.","Name both children''s wishes: ''You both want the car.''","Offer turns: ''Ayan has it now, then it''s your turn. Let''s count to twenty.''","Help the waiting child find something else to do while they wait.","Make sure the turn really comes back."],"bn":["টানাটানি শুরু হলে কাছে গিয়ে শান্ত থাকুন।","দুজনের চাওয়াই বলুন: “তোমরা দুজনেই গাড়িটা চাইছ।”","পালা প্রস্তাব করুন: “এখন আয়ানের, তারপর তোমার পালা। চলো বিশ পর্যন্ত গুনি।”","অপেক্ষা করা শিশুকে ততক্ষণ অন্য কিছু করতে সাহায্য করুন।","পালা যেন সত্যিই ফিরে আসে, খেয়াল রাখুন।"]},"steps":{"en":["Before cousins or guests come, let your child put away two or three special toys.","Bring out toys that are easy to share: blocks, balls, crayons, pots and spoons.","Practise turn-taking at home in simple games: rolling a ball, building a tower in turns.","Share in front of your child: offer food, lend things, say ''Your turn'' and ''Thank you''.","Praise any sharing or turn-taking you see.","Read stories about sharing and talk about how the characters feel."],"bn":["চাচাতো-মামাতো ভাই-বোন বা মেহমান আসার আগে শিশুকে দু-তিনটা বিশেষ খেলনা তুলে রাখতে দিন।","সহজে ভাগ করা যায় এমন খেলনা বের করুন — ব্লক, বল, রং পেনসিল, হাঁড়ি-চামচ।","ঘরে সহজ খেলায় পালার অনুশীলন করুন — বল গড়ানো, পালা করে টাওয়ার বানানো।","শিশুর সামনে ভাগ করুন — খাবার দিন, জিনিস ধার দিন, “তোমার পালা” আর “ধন্যবাদ” বলুন।","ভাগ করা বা পালা দেওয়া চোখে পড়লেই প্রশংসা করুন।","ভাগ করা নিয়ে গল্প পড়ুন, আর চরিত্রগুলোর কেমন লাগছে তা নিয়ে কথা বলুন।"]},"avoid":{"en":["Snatching the toy from your child to give to a guest","Calling your child selfish or stingy (''kipte'') in front of others","Making your child share their most special comfort toy","Punishing or hitting for not sharing"],"bn":["মেহমানকে দিতে শিশুর হাত থেকে খেলনা কেড়ে নেওয়া","অন্যদের সামনে শিশুকে স্বার্থপর বা ‘কিপটে’ বলা","শিশুর সবচেয়ে প্রিয়, আরামের খেলনাটাও ভাগ করতে বাধ্য করা","ভাগ না করায় শাস্তি দেওয়া বা মারা"]},"example":{"en":"When her cousins visited at Eid, three-year-old Labiba clutched all her dolls and screamed. The next time, her mother helped her choose two dolls to keep in the cupboard, and put out a basket of blocks and cooking pots. When the cousins arrived, Ammu said, ''Labiba, will you show them the blocks?'' The afternoon went much better, and Ammu praised her for taking turns with the pots.","bn":"ঈদে কাজিনরা বেড়াতে এলে তিন বছরের লাবিবা সব পুতুল আঁকড়ে ধরে চিৎকার করেছিল। পরের বার আম্মু ওকে আলমারিতে রাখার জন্য দুটো পুতুল বেছে নিতে সাহায্য করলেন, আর এক ঝুড়ি ব্লক আর হাঁড়ি-পাতিল বের করে রাখলেন। কাজিনরা আসতেই আম্মু বললেন, “লাবিবা, ওদের ব্লকগুলো দেখাবে?” বিকেলটা অনেক ভালো কাটল, আর হাঁড়ি নিয়ে পালা করে খেলার জন্য আম্মু ওর প্রশংসা করলেন।"},"seek_help":{"en":["Your child shows almost no interest in other children by three to four","Your child very often hurts others when playing","There are concerns about speech, understanding or development","Your child becomes extremely distressed whenever toys are moved or touched"],"bn":["তিন-চার বছরেও শিশু অন্য শিশুদের প্রতি প্রায় কোনো আগ্রহ দেখায় না","খেলার সময় শিশু খুব ঘনঘন অন্যদের আঘাত করে","কথা বলা, বোঝা বা বিকাশ নিয়ে চিন্তা আছে","খেলনা সরালে বা ছুঁলে শিশু অস্বাভাবিক রকম ভেঙে পড়ে"]}}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['sharing', 'mine', 'toys', 'cousins', 'guests', 'turn taking']::text[], false, 'in_review'::lp_review_status, 5036),
  ('ec-sc-cries-for-phone', 'scenario', 'scientific', 'shared', 'important', 'guideline', '📵', '{"en":"My child cries for the phone","bn":"ফোনের জন্য শিশু কান্নাকাটি করে"}'::jsonb, '{"en":"If the phone usually comes out when your child cries, eats or is bored, crying for it is a learned habit. Set clear screen times, keep phones away from meals and bed, and expect a few hard days while the habit changes.","bn":"কান্না, খাওয়া বা একঘেয়েমির সময় যদি প্রায়ই ফোন হাতে আসে, তাহলে ফোনের জন্য কান্না একটা শেখা অভ্যাস। স্ক্রিনের নির্দিষ্ট সময় ঠিক করুন, খাওয়া আর ঘুমের সময় ফোন দূরে রাখুন, আর অভ্যাস বদলানোর সময় কয়েকটা কঠিন দিনের জন্য তৈরি থাকুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Phones are bright, fast and always changing, which young children find very hard to stop. If crying has sometimes brought the phone back, your child has learned that crying works.","bn":"ফোন উজ্জ্বল, দ্রুত আর সারাক্ষণ বদলাতে থাকে — ছোট শিশুর পক্ষে এটা থামানো খুব কঠিন। কাঁদলে মাঝে মাঝে ফোন ফেরত এসেছে — তাহলে শিশু শিখে ফেলেছে, কাঁদলেই কাজ হয়।"},"why":{"en":"Common patterns: the phone is used to feed, to stop crying, to keep a child quiet in front of guests, or while adults are busy; videos auto-play endlessly; and different adults have different rules.","bn":"সাধারণ ধরন — খাওয়াতে, কান্না থামাতে, মেহমানের সামনে চুপ রাখতে, বা বড়রা ব্যস্ত থাকলে ফোন দেওয়া; ভিডিও একটার পর একটা নিজে নিজে চলতে থাকা; আর একেক বড়জনের একেক নিয়ম।"},"normal":{"en":"Protest when screens stop is very common. WHO advises no more than one hour a day of sitting screen time at two to four years, less being better, and none before two.","bn":"স্ক্রিন বন্ধ করলে প্রতিবাদ খুব সাধারণ। WHO-র পরামর্শ: দুই বছরের আগে স্ক্রিন নয়, আর দুই থেকে চার বছরে বসে স্ক্রিন দেখা দিনে এক ঘণ্টার বেশি নয় — যত কম, তত ভালো।"},"do_now":{"en":["Once you have said no, stay calm and don''t give the phone back to stop the crying.","Name the feeling: ''You''re angry the video stopped. You really like it.''","Put the phone out of sight.","Offer something else to do with you: a ball, a book, helping you, going outside.","Stay close until the storm passes."],"bn":["একবার ‘না’ বললে শান্ত থাকুন, কান্না থামাতে ফোন ফেরত দেবেন না।","অনুভূতির নাম দিন: “ভিডিও বন্ধ হওয়ায় তুমি রেগে গেছ। তুমি এটা খুব পছন্দ করো।”","ফোনটা চোখের আড়ালে রাখুন।","আপনার সাথে করার মতো অন্য কিছু দিন — বল, বই, আপনাকে সাহায্য করা, বাইরে যাওয়া।","ঝড় না থামা পর্যন্ত কাছে থাকুন।"]},"steps":{"en":["Decide together as a family when screens are allowed, for example one short programme after the afternoon nap.","Use the TV in a shared room rather than a phone in the child''s hands, and watch together.","Turn off auto-play, and choose a set number of short videos before you start.","Give a warning: ''Two more songs, then it''s finished.'' Then switch off kindly and firmly.","No phones at meals or in bed, for anyone.","Fill the gaps with people and play: outdoor time, blocks, drawing, small jobs.","Expect more crying for the first few days; it usually settles once the new rule is consistent."],"bn":["পরিবারের সবাই মিলে ঠিক করুন কখন স্ক্রিন চলবে — যেমন দুপুরের ঘুমের পর একটা ছোট অনুষ্ঠান।","শিশুর হাতে ফোন না দিয়ে সবার ঘরে টিভি ব্যবহার করুন, আর একসাথে দেখুন।","অটো-প্লে বন্ধ রাখুন, আর শুরুর আগেই কয়টা ছোট ভিডিও দেখবে ঠিক করে নিন।","আগে জানান: “আর দুটো গান, তারপর শেষ।” তারপর নরম কিন্তু দৃঢ়ভাবে বন্ধ করুন।","খাওয়ার সময় আর বিছানায় কারও জন্যই ফোন নয়।","ফাঁকা সময় মানুষ আর খেলা দিয়ে ভরান — বাইরে সময়, ব্লক, আঁকা, ছোট কাজ।","প্রথম কয়েক দিন বেশি কান্না আশা করুন; নতুন নিয়ম ধারাবাহিক থাকলে সাধারণত থিতিয়ে আসে।"]},"avoid":{"en":["Giving the phone to stop crying, then taking it away again","Feeding with videos playing","Screens in the hour before sleep","Fast, loud or violent videos and unsupervised YouTube","Using the phone as a reward or its removal as a frightening punishment"],"bn":["কান্না থামাতে ফোন দেওয়া, তারপর আবার কেড়ে নেওয়া","ভিডিও চালিয়ে খাওয়ানো","ঘুমের আগের এক ঘণ্টায় স্ক্রিন","দ্রুত, হইচইয়ের বা মারামারির ভিডিও, আর নজর ছাড়া ইউটিউব","পুরস্কার হিসেবে ফোন দেওয়া, বা ভয় দেখানোর শাস্তি হিসেবে কেড়ে নেওয়া"]},"example":{"en":"Two-and-a-half-year-old Fahim screamed every time the phone was taken away, so his family kept giving it back. His parents agreed on one 20-minute cartoon time after his nap, on the TV, and asked Dadi to keep her phone in her bag. The first three days were loud. Ammu stayed calm, said ''Phone time is finished. Let''s water the plants,'' and stuck to it. By the second week Fahim was asking ''Is it cartoon time?'' instead of crying.","bn":"আড়াই বছরের ফাহিম ফোন নিয়ে নিলেই চিৎকার করত, তাই পরিবারের লোকেরা বারবার ফেরত দিতেন। বাবা-মা ঠিক করলেন দুপুরের ঘুমের পর টিভিতে ২০ মিনিট কার্টুনের সময়, আর দাদিকে অনুরোধ করলেন ফোন ব্যাগে রাখতে। প্রথম তিন দিন খুব হইচই হলো। আম্মু শান্ত থেকে বললেন, “ফোনের সময় শেষ। চলো গাছে পানি দিই,” আর নিয়মে অটল থাকলেন। দ্বিতীয় সপ্তাহে ফাহিম কান্নার বদলে জিজ্ঞেস করতে লাগল, “এখন কি কার্টুনের সময়?”"},"seek_help":{"en":["Your child becomes extremely distressed for long periods whenever screens stop","Screens are crowding out sleep, eating, play or talking","There are concerns about speech, eye contact or how your child connects with people","You are finding it very hard to manage without screens and need support"],"bn":["স্ক্রিন বন্ধ করলেই শিশু লম্বা সময় ধরে অস্বাভাবিক রকম ভেঙে পড়ে","স্ক্রিনের কারণে ঘুম, খাওয়া, খেলা বা কথা বলা কমে যাচ্ছে","কথা বলা, চোখে চোখ রাখা বা মানুষের সাথে মেশা নিয়ে চিন্তা আছে","স্ক্রিন ছাড়া সামলাতে আপনার খুব কষ্ট হচ্ছে, সহায়তা দরকার"]}}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['phone', 'screen time', 'cartoons', 'youtube', 'crying', 'addiction', 'mealtime']::text[], false, 'in_review'::lp_review_status, 5037),
  ('ec-sc-grandparents-give-in', 'scenario', 'general', 'family', 'educational', 'consensus', '👵', '{"en":"Grandparents give in to everything","bn":"দাদা-দাদি, নানা-নানি সব আবদার মেনে নেন"}'::jsonb, '{"en":"Grandparents'' love is a gift, and their indulgence usually comes from that love. Agree on a few rules that really matter, ask kindly, and let grandparents keep their special place.","bn":"দাদা-দাদি, নানা-নানির ভালোবাসা একটা আশীর্বাদ, আর তাঁদের আবদার মেনে নেওয়া সাধারণত সেই ভালোবাসা থেকেই আসে। সত্যিই জরুরি কয়েকটা নিয়মে একমত হোন, নরমভাবে অনুরোধ করুন, আর তাঁদের বিশেষ জায়গাটা থাকতে দিন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"In many Bangladeshi homes, grandparents live with the family or help care for the children. They may give sweets, the phone, or anything the child cries for, or undo a rule the parents just set. Parents can feel undermined, while grandparents feel they are only showing love.","bn":"আমাদের অনেক ঘরে দাদা-দাদি বা নানা-নানি একসাথে থাকেন, বা নাতি-নাতনির দেখাশোনায় সাহায্য করেন। তাঁরা হয়তো মিষ্টি, ফোন বা শিশু কাঁদলেই যা চায় তা দিয়ে দেন, বা বাবা-মা সদ্য যে নিয়ম করলেন তা ভেঙে দেন। বাবা-মায়ের মনে হয় তাঁদের কথার দাম নেই, আর দাদা-দাদিদের মনে হয় তাঁরা শুধু ভালোবাসা দেখাচ্ছেন।"},"why":{"en":"Grandparents often feel their role is to spoil and comfort, as was common in their time. Advice on screens, sugar and discipline has also changed. And seeing a grandchild cry can be very hard for them.","bn":"দাদা-দাদিরা প্রায়ই মনে করেন তাঁদের কাজ আদর আর আহ্লাদ দেওয়া — তাঁদের সময়ে এটাই প্রচলিত ছিল। স্ক্রিন, চিনি আর শাসন নিয়ে পরামর্শও এখন বদলেছে। আর নাতি-নাতনিকে কাঁদতে দেখা তাঁদের জন্য খুব কষ্টের।"},"normal":{"en":"Some difference between parents'' and grandparents'' ways is normal and harmless. Children can learn that ''at Nanu''s house it''s different''. It matters most when it affects health, safety, or makes the child feel that crying always wins.","bn":"বাবা-মা আর দাদা-দাদির ধরনে কিছু পার্থক্য স্বাভাবিক আর ক্ষতিহীন। শিশু শিখে নিতে পারে, “নানুবাড়িতে নিয়ম একটু আলাদা।” সবচেয়ে জরুরি তখন, যখন এটা স্বাস্থ্য বা নিরাপত্তায় প্রভাব ফেলে, বা শিশু শেখে কাঁদলেই সবসময় জেতা যায়।"},"do_now":{"en":["Don''t argue in front of the child; talk later, privately and calmly.","Start by thanking them for their love and help.","Each parent speaks first to their own parents; it is usually received better.","Choose just two or three rules that really matter, such as no sweets before meals, no phone at meals or bedtime, and no hitting or frightening the child."],"bn":["শিশুর সামনে তর্ক করবেন না; পরে আলাদা করে, শান্তভাবে কথা বলুন।","শুরুতে তাঁদের ভালোবাসা আর সাহায্যের জন্য ধন্যবাদ দিন।","প্রত্যেকে আগে নিজের বাবা-মায়ের সাথে কথা বলুন — সাধারণত তাতে ভালোভাবে গ্রহণ করেন।","সত্যিই জরুরি মাত্র দুই-তিনটা নিয়ম বেছে নিন — যেমন খাবারের আগে মিষ্টি নয়, খাওয়া আর ঘুমের সময় ফোন নয়, শিশুকে মারা বা ভয় দেখানো নয়।"]},"steps":{"en":["Explain the reasons simply, linking to health: ''The doctor said sweets between meals harm her teeth.''","Suggest what they can give instead: fruit, a story, a walk, a special game only with Dadu.","Give grandparents a special role: storyteller, teacher of rhymes and prayers, the one who takes the child to see the garden.","Agree on what everyone says when the child cries for something already refused.","Keep the rules simple and written down, if that helps, for all carers.","Notice and thank grandparents when they follow the plan.","Accept small differences that don''t matter much, to keep peace and respect."],"bn":["স্বাস্থ্যের সাথে মিলিয়ে সহজ করে কারণ বলুন: “ডাক্তার বলেছেন, দুই খাবারের মাঝে মিষ্টি খেলে ওর দাঁত নষ্ট হবে।”","বদলে কী দিতে পারেন বলুন — ফল, গল্প, হাঁটতে যাওয়া, শুধু দাদুর সাথে বিশেষ একটা খেলা।","দাদা-দাদিকে একটা বিশেষ ভূমিকা দিন — গল্পকথক, ছড়া আর দোয়া শেখানোর শিক্ষক, বাগান দেখাতে নিয়ে যাওয়ার মানুষ।","যা আগেই ‘না’ বলা হয়েছে, তার জন্য শিশু কাঁদলে সবাই কী বলবেন, একমত হোন।","নিয়মগুলো সহজ রাখুন, দরকার হলে সব দেখাশোনাকারীর জন্য লিখে রাখুন।","দাদা-দাদিরা পরিকল্পনা মানলে খেয়াল করে ধন্যবাদ দিন।","যেসব ছোট পার্থক্য তেমন জরুরি নয়, শান্তি আর সম্মানের জন্য মেনে নিন।"]},"avoid":{"en":["Criticising grandparents in front of the child","Ultimatums or cutting grandparents off over small things","Expecting them to follow every detail of your routine","Making the child choose between parents and grandparents"],"bn":["শিশুর সামনে দাদা-দাদির সমালোচনা","ছোটখাটো বিষয়ে চরম শর্ত দেওয়া বা সম্পর্ক ছিন্ন করা","আপনার রুটিনের প্রতিটি খুঁটিনাটি মানবেন, এমন আশা করা","শিশুকে বাবা-মা আর দাদা-দাদির মধ্যে একজনকে বেছে নিতে বাধ্য করা"]},"example":{"en":"In a joint family in Sylhet, Dadi gave three-year-old Ayesha biscuits and the phone whenever she cried. Her father sat with his mother one evening: ''Amma, Ayesha loves you so much. The doctor said the biscuits are hurting her teeth and the phone is keeping her up. Could you be the one who tells her a story when she cries?'' Dadi grumbled at first, but soon bedtime stories with Dadi became Ayesha''s favourite time.","bn":"সিলেটের এক যৌথ পরিবারে তিন বছরের আয়েশা কাঁদলেই দাদি বিস্কুট আর ফোন দিয়ে দিতেন। এক সন্ধ্যায় আয়েশার বাবা নিজের মায়ের পাশে বসলেন: “আম্মা, আয়েশা আপনাকে খুব ভালোবাসে। ডাক্তার বলেছেন বিস্কুটে ওর দাঁতের ক্ষতি হচ্ছে আর ফোনের জন্য রাতে ঘুমাতে দেরি হচ্ছে। ও কাঁদলে আপনি কি ওকে একটা গল্প শোনাবেন?” দাদি প্রথমে একটু গজগজ করলেন, কিন্তু শিগগিরই দাদির কাছে ঘুমের আগের গল্প আয়েশার সবচেয়ে প্রিয় সময় হয়ে উঠল।"},"seek_help":{"en":["Disagreements are causing ongoing conflict or distress in the family","A carer hits, frightens or harms the child, or ignores safety rules around water, fire or medicines","Your child''s health is affected, for example tooth decay or poor growth","You feel unable to raise concerns safely; a trusted relative, counsellor or health worker can help"],"bn":["মতভেদে পরিবারে লাগাতার অশান্তি বা কষ্ট হচ্ছে","কোনো দেখাশোনাকারী শিশুকে মারেন, ভয় দেখান বা ক্ষতি করেন, বা পানি, আগুন বা ওষুধ নিয়ে নিরাপত্তার নিয়ম মানেন না","শিশুর স্বাস্থ্যে প্রভাব পড়ছে — যেমন দাঁতের ক্ষয় বা ঠিকমতো না বাড়া","আপনার মনে হচ্ছে নিরাপদে নিজের চিন্তা বলতে পারছেন না — বিশ্বস্ত আত্মীয়, কাউন্সেলর বা স্বাস্থ্যকর্মী সাহায্য করতে পারেন"]}}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['grandparents', 'joint family', 'dadi', 'nani', 'spoiling', 'rules', 'family conflict']::text[], false, 'in_review'::lp_review_status, 5038),
  ('ec-sc-says-no-to-everything', 'scenario', 'scientific', 'shared', 'educational', 'consensus', '🙅', '{"en":"My child says ''no'' to everything","bn":"শিশু সবকিছুতে ‘না’ বলে"}'::jsonb, '{"en":"''No!'' is how young children practise being their own person. Avoid power struggles: give fewer orders, offer two good choices, make routines predictable, and save firm limits for what really matters.","bn":"“না!” বলেই ছোট শিশু নিজের মতো একজন মানুষ হওয়ার অনুশীলন করে। ক্ষমতার লড়াই এড়িয়ে চলুন — কম আদেশ দিন, দুটো ভালো পছন্দ দিন, রুটিন নির্দিষ্ট রাখুন, আর দৃঢ় সীমা রাখুন শুধু সত্যিই জরুরি বিষয়ে।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Around two, children discover that they are separate from their parents and can have their own wishes. Saying ''no'' is a safe way to test that power. It doesn''t mean your child is disrespectful or ''jedi'' by nature.","bn":"দুই বছরের দিকে শিশু আবিষ্কার করে, সে বাবা-মা থেকে আলাদা, আর তার নিজের ইচ্ছা থাকতে পারে। ‘না’ বলা সেই ক্ষমতা পরীক্ষার একটা নিরাপদ উপায়। এর মানে এই নয় যে শিশু বেয়াদব বা স্বভাবে ‘জেদি’।"},"why":{"en":"Many ''no''s come from being given lots of orders in a day, being rushed, tiredness or hunger, or simply wanting to finish what they are doing. Sometimes ''no'' is just a reflex, and the child then does the thing anyway.","bn":"অনেক ‘না’ আসে দিনভর অনেক আদেশ শোনা, তাড়াহুড়ো, ক্লান্তি বা ক্ষুধা থেকে, বা যা করছে সেটা শেষ করতে চাওয়া থেকে। কখনো ‘না’ শুধুই অভ্যাসে বের হয়, তারপর শিশু কাজটা করেই ফেলে।"},"normal":{"en":"This stage is very common between about 18 months and three and a half, and usually eases as children gain language and feel more in control of their day.","bn":"মোটামুটি দেড় থেকে সাড়ে তিন বছরে এই পর্যায় খুব সাধারণ, আর ভাষা বাড়লে আর দিনের ওপর একটু নিয়ন্ত্রণ পেলে সাধারণত কমে আসে।"},"do_now":{"en":["Stay calm; don''t take the ''no'' personally.","Ask yourself: does this really matter? If not, let it go.","Turn questions into simple statements when there is no choice: ''It''s time to wash hands'', not ''Do you want to wash hands?''","Offer two choices you are happy with: ''Do you want to walk to the bath or hop like a frog?''","Use humour or a game: ''Can you get your shoes before I count to five?''"],"bn":["শান্ত থাকুন; ‘না’-কে ব্যক্তিগতভাবে নেবেন না।","নিজেকে জিজ্ঞেস করুন: এটা কি সত্যিই জরুরি? না হলে ছেড়ে দিন।","যেখানে পছন্দের সুযোগ নেই, প্রশ্ন না করে সহজভাবে বলুন: “এখন হাত ধোয়ার সময়” — “হাত ধোবে?” নয়।","আপনার কাছে ঠিক এমন দুটো পছন্দ দিন: “গোসলে হেঁটে যাবে, নাকি ব্যাঙের মতো লাফিয়ে?”","মজা বা খেলা ব্যবহার করুন: “পাঁচ গোনার আগে জুতা আনতে পারবে?”"]},"steps":{"en":["Keep a predictable daily routine so fewer instructions are needed.","Give warnings before changes: ''Five more minutes of play, then bath.''","Give fewer orders; say ''yes'' when you can (''Yes, you can play after lunch'').","Get down to eye level and give one short instruction at a time.","Praise cooperation specifically: ''You came straight away when I called. Thank you!''","For real safety limits (roads, fire, water), act calmly and firmly, even if your child protests.","Make sure your child gets enough sleep and regular meals."],"bn":["প্রতিদিনের রুটিন নির্দিষ্ট রাখুন, যাতে কম নির্দেশ দিতে হয়।","পরিবর্তনের আগে জানিয়ে দিন: “আর পাঁচ মিনিট খেলা, তারপর গোসল।”","আদেশ কম দিন; পারলে ‘হ্যাঁ’ বলুন (“হ্যাঁ, দুপুরের খাবারের পর খেলতে পারবে”)।","চোখের সমান হয়ে একবারে একটা ছোট নির্দেশ দিন।","সহযোগিতার নির্দিষ্ট প্রশংসা করুন: “ডাকতেই তুমি চলে এলে। ধন্যবাদ!”","সত্যিকারের নিরাপত্তার সীমায় (রাস্তা, আগুন, পানি) শিশু প্রতিবাদ করলেও শান্ত ও দৃঢ়ভাবে ব্যবস্থা নিন।","শিশু যেন যথেষ্ট ঘুমায় আর নিয়মিত খায়।"]},"avoid":{"en":["Getting into a battle of wills over small things","Shouting, smacking or threatening","Labelling: ''You are so stubborn'', ''such a jedi child''","Asking a question when there is really no choice","Giving in to long tantrums over limits that matter"],"bn":["ছোটখাটো বিষয়ে জেদের লড়াইয়ে জড়ানো","চিৎকার, মারা বা হুমকি","তকমা দেওয়া: “তুমি খুব জেদি”, “কী জেদি বাচ্চা”","আসলে পছন্দ নেই এমন বিষয়ে প্রশ্ন করা","জরুরি সীমার বিষয়ে লম্বা কান্নার কাছে হার মানা"]},"example":{"en":"Every morning, two-year-old Mahin shouted ''No!'' when it was time to get dressed. His mother stopped asking ''Shall we get dressed?'' and instead held up two shirts: ''Blue or green today?'' Mahin pointed to the green one. When he refused his socks, she said, ''Let''s see if your feet can find the socks by themselves!'' He laughed and pushed his feet in. Mornings became much calmer.","bn":"প্রতিদিন সকালে জামা পরার সময় দুই বছরের মাহিন চিৎকার করত, “না!” আম্মু “জামা পরবে?” জিজ্ঞেস করা বন্ধ করে দুটো জামা তুলে ধরলেন: “আজ নীলটা, নাকি সবুজটা?” মাহিন সবুজটা দেখাল। মোজা পরতে না চাইলে আম্মু বললেন, “দেখি তো, তোমার পা নিজে নিজে মোজা খুঁজে পায় কি না!” মাহিন হেসে পা ঢুকিয়ে দিল। সকালগুলো অনেক শান্ত হয়ে গেল।"},"seek_help":{"en":["Defiance is extreme, constant, and getting worse after age four","Your child is often aggressive or destructive","There are concerns about speech, hearing or understanding","Conflict at home is constant and you feel overwhelmed"],"bn":["চার বছরের পরেও অবাধ্যতা চরম, সারাক্ষণ, আর বাড়ছে","শিশু প্রায়ই আক্রমণাত্মক বা জিনিস ভাঙচুর করে","কথা বলা, শোনা বা বোঝা নিয়ে চিন্তা আছে","ঘরে সারাক্ষণ অশান্তি, আর আপনি দিশেহারা বোধ করছেন"]}}'::jsonb, 3, 730, 1461, '{}'::text[], 'any', ARRAY['saying no', 'defiance', 'stubborn', 'independence', 'choices', 'power struggle']::text[], false, 'in_review'::lp_review_status, 5039)
