INSERT INTO lp_task_templates (key, title, description, why, benefit, steps, safety_note, task_type, frequency, assignee, subject, min_day, max_day, estimated_minutes, xp, emoji, category_key, resource_slug, source_key, sex, review_status, sort_order) VALUES
  ('ec_handwash_meals', '{"en":"Wash hands with soap before meals, with a song","bn":"খাওয়ার আগে গান গেয়ে সাবান দিয়ে হাত ধোয়া"}'::jsonb, '{"en":"Before each meal today, wash hands with soap together while singing a short rhyme.","bn":"আজ প্রতি বেলা খাওয়ার আগে একসাথে ছোট একটা ছড়া গাইতে গাইতে সাবান দিয়ে হাত ধুয়ে নিন।"}'::jsonb, '{"en":"Handwashing with soap at key times is one of the most effective ways to prevent diarrhoea and chest infections in young children.","bn":"গুরুত্বপূর্ণ সময়ে সাবান দিয়ে হাত ধোয়া ছোট শিশুদের ডায়রিয়া আর বুকের সংক্রমণ প্রতিরোধের সবচেয়ে কার্যকর উপায়গুলোর একটা।"}'::jsonb, '{"en":"Fewer illnesses, and a habit your child will keep for life.","bn":"অসুখ কম হবে, আর এমন একটা অভ্যাস তৈরি হবে যা শিশু সারাজীবন রাখবে।"}'::jsonb, '[{"en":"Wet hands and rub with soap.","bn":"হাত ভিজিয়ে সাবান ঘষুন।"},{"en":"Scrub palms, backs, between fingers and nails while singing a rhyme twice.","bn":"একটা ছড়া দুইবার গাইতে গাইতে তালু, হাতের পিঠ, আঙুলের ফাঁক আর নখ ঘষুন।"},{"en":"Rinse well and dry on a clean cloth.","bn":"ভালো করে ধুয়ে পরিষ্কার কাপড়ে মুছে নিন।"}]'::jsonb, '{}'::jsonb, 'must_do', 'daily', 'any', 'child', 730, 1461, 3, 5, '🧼', 'hygiene', 'ec-handwashing-hygiene', 'who_diarrhoea', 'any', 'in_review'::lp_review_status, 5101),
  ('ec_special_time', '{"en":"Ten minutes of special time with each parent","bn":"বাবা-মা প্রত্যেকের সাথে ১০ মিনিটের বিশেষ সময়"}'::jsonb, '{"en":"Today, the mother and the father each spend about 10 minutes alone with your child, phone away, playing what the child chooses.","bn":"আজ মা আর বাবা প্রত্যেকে ফোন দূরে রেখে আলাদাভাবে প্রায় ১০ মিনিট শিশুর সাথে কাটান — শিশু যা খেলতে চায়, তাই।"}'::jsonb, '{"en":"Short, regular one-to-one attention helps young children feel secure and loved, which makes them more cooperative and calmer.","bn":"ছোট কিন্তু নিয়মিত একান্ত মনোযোগে শিশু নিরাপদ আর ভালোবাসা অনুভব করে — এতে সে বেশি সহযোগিতা করে, শান্ত থাকে।"}'::jsonb, '{"en":"A closer bond and often fewer battles during the day.","bn":"সম্পর্ক আরও গভীর হয়, আর দিনভর ঝগড়াও প্রায়ই কমে।"}'::jsonb, '[{"en":"Put your phone away and tell your child, ''This is our special time.''","bn":"ফোন সরিয়ে রেখে শিশুকে বলুন, “এখন আমাদের বিশেষ সময়।”"},{"en":"Let your child choose the game, and follow their lead.","bn":"খেলাটা শিশুকে বেছে নিতে দিন, আর ওর পেছনে পেছনে চলুন।"},{"en":"Describe and praise what they do; avoid questions and corrections.","bn":"ও যা করছে বলে বলে প্রশংসা করুন; প্রশ্ন আর ভুল ধরা এড়িয়ে চলুন।"}]'::jsonb, '{}'::jsonb, 'recommended', 'daily', 'shared', 'child', 730, 1461, 10, 10, '💛', 'emotions', 'ec-positive-discipline', 'cdc_positive_parenting', 'any', 'in_review'::lp_review_status, 5102),
  ('ec_two_choices', '{"en":"Offer a choice between two good options","bn":"দুটি ভালো বিকল্পের মধ্যে বেছে নিতে দিন"}'::jsonb, '{"en":"At least once today, instead of giving an order, offer your child two choices that are both fine with you.","bn":"আজ অন্তত একবার আদেশ না দিয়ে শিশুকে এমন দুটো বিকল্প দিন, যার দুটোই আপনার কাছে ঠিক আছে।"}'::jsonb, '{"en":"Young children want some control over their day. Small choices meet that need and reduce power struggles.","bn":"ছোট শিশু নিজের দিনের ওপর একটু নিয়ন্ত্রণ চায়। ছোট পছন্দ সেই চাওয়া পূরণ করে, ক্ষমতার লড়াই কমায়।"}'::jsonb, '{"en":"Fewer ''no''s, and your child practises making decisions.","bn":"‘না’ কম শুনবেন, আর শিশু সিদ্ধান্ত নেওয়ার অনুশীলন করবে।"}'::jsonb, '[{"en":"Pick a daily moment, such as dressing, snack or bath.","bn":"জামা পরা, নাশতা বা গোসলের মতো একটা রোজকার মুহূর্ত বেছে নিন।"},{"en":"Offer two options: ''Red shirt or blue shirt?''","bn":"দুটো বিকল্প দিন: “লাল জামা, নাকি নীলটা?”"},{"en":"Accept their choice, and praise them for deciding.","bn":"ওর পছন্দ মেনে নিন, আর সিদ্ধান্ত নেওয়ার জন্য প্রশংসা করুন।"}]'::jsonb, '{}'::jsonb, 'recommended', 'daily', 'any', 'child', 730, 1461, 2, 5, '✌️', 'positive_discipline', 'ec-sc-says-no-to-everything', 'cdc_positive_parenting', 'any', 'in_review'::lp_review_status, 5103),
  ('ec_little_chore', '{"en":"Let your child help with a small chore","bn":"ছোট একটা ঘরের কাজে শিশুকে সাহায্য করতে দিন"}'::jsonb, '{"en":"Give your child one small, safe job today, such as putting shoes in place, giving out spoons or folding small cloths.","bn":"আজ শিশুকে ছোট, নিরাপদ একটা কাজ দিন — জুতা জায়গামতো রাখা, সবাইকে চামচ দেওয়া বা ছোট কাপড় ভাঁজ করা।"}'::jsonb, '{"en":"Helping the family builds confidence, hand skills and a sense of responsibility and kindness.","bn":"পরিবারকে সাহায্য করলে আত্মবিশ্বাস, হাতের দক্ষতা আর দায়িত্ববোধ ও দয়া তৈরি হয়।"}'::jsonb, '{"en":"Your child feels useful and proud, and learns that everyone helps at home.","bn":"শিশু নিজেকে কাজের আর গর্বিত মনে করে, আর শেখে ঘরে সবাই হাত লাগায়।"}'::jsonb, '[]'::jsonb, '{"en":"Keep children away from knives, the stove, hot water and cleaning chemicals.","bn":"ছুরি-বঁটি, চুলা, গরম পানি আর পরিষ্কারের রাসায়নিক থেকে শিশুকে দূরে রাখুন।"}'::jsonb, 'family', 'daily', 'any', 'child', 730, 1461, 5, 5, '🧺', 'character', 'ec-manners-kindness', 'unicef_parenting', 'any', 'in_review'::lp_review_status, 5104),
  ('ec_count_together', '{"en":"Count things together","bn":"একসাথে জিনিস গুনুন"}'::jsonb, '{"en":"Count something real together today: stairs, spoons, mangoes, birds or cars.","bn":"আজ একসাথে সত্যিকারের কিছু গুনুন — সিঁড়ির ধাপ, চামচ, আম, পাখি বা গাড়ি।"}'::jsonb, '{"en":"Counting real objects, touching each one, builds early number sense far better than reciting numbers alone.","bn":"সত্যিকারের জিনিস প্রতিটা ছুঁয়ে ছুঁয়ে গুনলে শুধু মুখস্থ সংখ্যা বলার চেয়ে অনেক ভালোভাবে সংখ্যার ধারণা তৈরি হয়।"}'::jsonb, '{"en":"A playful start to maths, woven into everyday life.","bn":"রোজকার জীবনের মধ্যেই খেলার ছলে গণিতের শুরু।"}'::jsonb, '[{"en":"Choose a few objects, starting with up to five for younger children.","bn":"কয়েকটা জিনিস বেছে নিন — ছোটদের জন্য পাঁচটা পর্যন্ত দিয়ে শুরু করুন।"},{"en":"Touch or point to each one as you count aloud together.","bn":"জোরে জোরে গুনতে গুনতে প্রতিটা ছুঁয়ে বা আঙুল দিয়ে দেখান।"},{"en":"Ask, ''How many are there?'' and celebrate the answer.","bn":"জিজ্ঞেস করুন, “কয়টা হলো?” আর উত্তরটা উদযাপন করুন।"}]'::jsonb, '{}'::jsonb, 'learn', 'daily', 'any', 'child', 730, 1461, 5, 5, '🔢', 'brain_development', 'ec-father-playmate-teacher', 'who_nurturing_care', 'any', 'in_review'::lp_review_status, 5105),
  ('ec_bedtime_routine', '{"en":"Bedtime routine at the same time","bn":"একই সময়ে ঘুমের রুটিন"}'::jsonb, '{"en":"Start the same calm bedtime routine at your usual time tonight: wash, teeth, toilet, story, cuddle, lights off.","bn":"আজ রাতে স্বাভাবিক সময়ে একই শান্ত রুটিন শুরু করুন — হাতমুখ ধোয়া, দাঁত ব্রাশ, টয়লেট, গল্প, আদর, বাতি বন্ধ।"}'::jsonb, '{"en":"WHO advises regular sleep and wake-up times, with 11–14 hours of sleep at two and 10–13 hours at three to four, naps included.","bn":"WHO নিয়মিত সময়ে ঘুমানো আর ওঠার পরামর্শ দেয় — দুপুরের ঘুমসহ দুই বছরে ১১–১৪ ঘণ্টা আর তিন-চার বছরে ১০–১৩ ঘণ্টা।"}'::jsonb, '{"en":"Easier bedtimes, better sleep, and a calmer child the next day.","bn":"সহজে ঘুমাতে যাওয়া, ভালো ঘুম, আর পরদিন শান্ত শিশু।"}'::jsonb, '[{"en":"Switch off screens at least an hour before bed.","bn":"ঘুমের অন্তত এক ঘণ্টা আগে স্ক্রিন বন্ধ করুন।"},{"en":"Follow the same steps in the same order.","bn":"একই ধাপ, একই ক্রমে করুন।"},{"en":"End with a warm, clear goodnight.","bn":"উষ্ণ, স্পষ্ট শুভরাত্রি দিয়ে শেষ করুন।"}]'::jsonb, '{}'::jsonb, 'recommended', 'daily', 'shared', 'child', 730, 1461, 20, 10, '🌙', 'sleep', 'ec-sleep-2-to-4', 'who_activity_under5', 'any', 'in_review'::lp_review_status, 5106),
  ('ec_medicine_check', '{"en":"Check medicines and chemicals are stored up high","bn":"ওষুধ আর রাসায়নিক উঁচুতে রাখা আছে কি না দেখুন"}'::jsonb, '{"en":"Walk through your home and check that all medicines, kerosene, cleaners and poisons are out of reach and in their own containers.","bn":"পুরো ঘর ঘুরে দেখুন — সব ওষুধ, কেরোসিন, পরিষ্কারক আর বিষ নাগালের বাইরে আর নিজ নিজ পাত্রে আছে কি না।"}'::jsonb, '{"en":"Young children can climb and open containers. Poisoning from medicines, kerosene and household chemicals is common and preventable.","bn":"ছোট শিশু বেয়ে উঠতে আর পাত্র খুলতে পারে। ওষুধ, কেরোসিন আর ঘরের রাসায়নিকে বিষক্রিয়া সাধারণ — আর প্রতিরোধযোগ্য।"}'::jsonb, '{"en":"Peace of mind that the most common poisoning dangers are out of reach.","bn":"সবচেয়ে সাধারণ বিষক্রিয়ার বিপদ নাগালের বাইরে — এই নিশ্চিন্ততা।"}'::jsonb, '[{"en":"Gather all medicines, including iron tablets and vitamins, into one closed box stored up high.","bn":"আয়রন ট্যাবলেট আর ভিটামিনসহ সব ওষুধ একটা বন্ধ বাক্সে জড়ো করে উঁচুতে রাখুন।"},{"en":"Check that kerosene, phenyl, toilet cleaner, insect spray and rat poison are in their original containers, up high or locked.","bn":"কেরোসিন, ফিনাইল, টয়লেট ক্লিনার, কীটনাশক স্প্রে আর ইঁদুরের বিষ নিজের পাত্রে, উঁচুতে বা তালাবদ্ধ আছে কি না দেখুন।"},{"en":"Make sure no chemical is kept in a water or soft drink bottle.","bn":"নিশ্চিত করুন কোনো রাসায়নিক পানির বা কোমল পানীয়ের বোতলে রাখা নেই।"},{"en":"Check visitors'' bags and grandparents'' medicines too.","bn":"মেহমানদের ব্যাগ আর দাদা-দাদি, নানা-নানির ওষুধও দেখে নিন।"}]'::jsonb, '{"en":"If your child may have swallowed something harmful, do not make them vomit. Go to hospital or call 999 at once, and take the container.","bn":"শিশু ক্ষতিকর কিছু গিলেছে মনে হলে বমি করাবেন না। সাথে সাথে হাসপাতালে যান বা ৯৯৯-এ ফোন করুন, আর পাত্রটা সাথে নিন।"}'::jsonb, 'must_do', 'monthly', 'shared', 'family', 730, 1461, 10, 15, '💊', 'safety', 'ec-home-and-road-safety', 'who_child_injury', 'any', 'in_review'::lp_review_status, 5107),
  ('ec_no_screens_meals', '{"en":"No screens at meals today","bn":"আজ খাওয়ার সময় কোনো স্ক্রিন নয়"}'::jsonb, '{"en":"Keep the TV off and phones away at every meal today, for children and adults.","bn":"আজ প্রতি বেলা খাওয়ার সময় টিভি বন্ধ আর ফোন দূরে রাখুন — শিশু আর বড় সবার জন্য।"}'::jsonb, '{"en":"Eating in front of screens makes it harder for children to notice hunger and fullness, and takes away family conversation that builds language.","bn":"স্ক্রিনের সামনে খেলে শিশু ক্ষুধা আর পেট ভরার অনুভূতি টের পায় না, আর পরিবারের যে কথাবার্তা ভাষা গড়ে তোলে, সেটা হারিয়ে যায়।"}'::jsonb, '{"en":"Calmer meals, better eating and more time talking together.","bn":"শান্ত খাওয়া, ভালো খাওয়া, আর একসাথে বেশি গল্প।"}'::jsonb, '[{"en":"Put phones in another room or face down away from the table before eating.","bn":"খাওয়ার আগে ফোন অন্য ঘরে বা খাবার জায়গা থেকে দূরে উল্টো করে রাখুন।"},{"en":"Talk about the food: colours, tastes, who cooked it.","bn":"খাবার নিয়ে কথা বলুন — রং, স্বাদ, কে রান্না করেছে।"}]'::jsonb, '{}'::jsonb, 'family', 'daily', 'any', 'family', 730, 1461, 20, 5, '🍽️', 'digital_life', 'ec-screens-2-to-4', 'aap_media', 'any', 'in_review'::lp_review_status, 5108)
